using System.Diagnostics.CodeAnalysis;
using System.Reflection;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Unicode;
using System.Xml.Linq;
using VsBotKit.Agent;

namespace VsBotKit.Panel;

/// <summary>
/// ОКНО УПРАВЛЕНИЯ: страница в браузере, из которой бот виден и управляем.
///
/// ПОЧЕМУ БРАУЗЕР, А НЕ НАСТОЯЩЕЕ ОКНО. Бот безголовый: его место — фон на
/// рабочей машине или сервер без графики. Настольное окно там не запустится
/// вовсе, и пришлось бы писать второй способ управления — для сервера. Через
/// «ssh -L 42462:127.0.0.1:42462» одна и та же страница работает и дома, и на
/// сервере, и на трёх системах сразу, потому что рисует её браузер.
///
/// БЕЗОПАСНОСТЬ — не формальность. Панель может увести бота, поменять роль и
/// подключение, поэтому:
///   • слушаем только петлю (127.0.0.1) — см. <see cref="MiniHttp"/>;
///   • при каждом запуске рождается новый ключ доступа, он в ссылке;
///   • ЗАДАН ПАРОЛЬ АДМИНИСТРАТОРА — пускает только он, страницей входа, а
///     ключ в ссылке перестаёт что-либо открывать (см. <see cref="PanelDoor"/>);
///   • проверяем заголовок Host: без этого чужая страница могла бы прийти к
///     нам через подмену имени (браузер-то с этой же машины);
///   • токен мультиплеера, пароль сервера, ключ сессии, пароль окна и пропуск
///     НАРУЖУ НЕ ОТДАЮТСЯ: панель показывает только «задан / не задан».
/// Панель выключена по умолчанию и включается явно.
///
/// Панель НИЧЕГО не делает сама. Всё, что она умеет, — позвать то же, что
/// зовёт чат: команды, навыки, инструменты. Второго мозга у бота не заводится.
///
/// АВТОСОХРАНЕНИЕ. Хозяин просил не выбирать одно и то же на каждый запуск,
/// поэтому выбранное в окне ложится на диск сразу — но КАЖДОЕ в своё, уже
/// существующее место, второго хранилища ни для чего не заводится:
///   • адрес, порт, имя, uid, почта аккаунта, выбранный пресет, читы —
///     <see cref="BotConfig"/> (bot.json), один вызов Save();
///   • ручки роли — пресет (<see cref="PresetLibrary"/>, presets/&lt;id&gt;.json);
///   • очередь задач — <see cref="WorkPlanStore"/> (botjobs.json).
/// Пароль сервера, пароль аккаунта и ключ доступа к панели не сохраняются
/// нигде и никогда; при <see cref="BotConfig.SecretsFromCommandLine"/> панель
/// не сохраняет вовсе и говорит почему.
/// </summary>
public sealed class ControlPanel : IDisposable
{
    private readonly VsBot bot;
    private readonly MiniHttp http;
    private readonly List<string> log = [];
    private readonly Lock logLock = new();

    /// <summary>
    /// СКОЛЬКО СТРОК ВСЕГО ПРОШЛО ЧЕРЕЗ ЖУРНАЛ ОКНА ЗА ЗАПУСК — счёт, который
    /// не убывает. Он и есть закладка браузера (см. <see cref="LogSlice"/>).
    ///
    /// ЖИВОЙ СЛУЧАЙ, РАДИ КОТОРОГО ЗАВЕДЁН (ночь 18.08, слова заказчика:
    /// «в логах записи не было, почему-то они у бота не писались 20 минут
    /// целых, что странно»). В файле журнала эти двадцать минут ЕСТЬ — молчало
    /// именно ОКНО. Кольцо строк режется с головы (<see cref="Remember"/>), а
    /// закладка была НОМЕРОМ МЕСТА В СПИСКЕ: после первой же обрезки браузер
    /// просил строки с 800-й, в списке их оставалось 400, Skip(400) отдавал
    /// пустоту — и пустой ответ закладку не двигал. Кольцо больше 800 не
    /// растёт никогда, значит окно замолкало НАВСЕГДА, до перезагрузки
    /// страницы. Со счётом, который не убывает, обрезка закладку не задевает:
    /// сдвинулось начало списка — сдвинулось и <see cref="firstLine"/>.
    /// </summary>
    private long saidLines;

    /// <summary>Номер самой старой строки, которая ещё лежит в кольце.</summary>
    private long firstLine;

    /// <summary>
    /// КАРТА САМОГО СЕРВЕРА — подложка под точки бота, если её адрес задан
    /// (<see cref="PanelConfig.MapUrl"/>). Спрашивает сетку уровней фоном и
    /// один раз; окно из-за неё не ждёт ни секунды (см. <see cref="WebMapSource"/>).
    /// </summary>
    private readonly WebMapSource webMap = new();

    /// <summary>Чем кончилось последнее долгое дело — сводка для окна.</summary>
    private sealed record SkillDone(string Name, string Args, bool Ok, string Message, DateTime When);

    /// <summary>Последнее событие связи с сервером — то, чего «не в игре» не рассказывает.</summary>
    private sealed record LinkNote(string What, string Detail, DateTime When);

    // Пишет приёмный цикл бота, читает опрос из браузера — потому volatile:
    // окну нужна свежая ссылка, а не та, что осела в кэше потока
    private volatile SkillDone? lastSkill;
    private volatile LinkNote? link;

    // Аргументы знаем только про то, что запустили ИЗ ОКНА: событие о конце
    // навыка их не несёт, а из чата навык могли позвать с чем угодно
    private volatile string? startedName;
    private volatile string? startedArgs;

    private static readonly JsonSerializerOptions Json = new()
    {
        WriteIndented = false,
        Encoder = JavaScriptEncoder.Create(UnicodeRanges.All)
    };

    /// <summary>Порт по умолчанию: игра 42420, дверь мода 42461, панель 42462.</summary>
    public const int DefaultPort = 42462;

    /// <summary>
    /// ДВЕРЬ: кого пускать. Ключ этого запуска, пароль администратора (если
    /// задан), счёт промахов и пропуска вошедших — всё там, одним механизмом
    /// (см. <see cref="PanelDoor"/>). Панель у неё только спрашивает.
    /// </summary>
    public PanelDoor Door { get; } = new();

    /// <summary>Ключ доступа этого запуска. Без него панель не отвечает.</summary>
    public string Key => Door.Key;

    /// <summary>Сколько строк журнала держать для показа.</summary>
    public int LogLines { get; set; } = 400;

    /// <summary>
    /// УКРАШЕНИЯ ОКНА: подписи к настройкам из файла документации роли
    /// (<see cref="XmlDocs"/>).
    ///
    /// Замерено 11.08: VsBotKit.xml — это 4332 подписи и 2,6 МБ в памяти, и
    /// висят они там весь запуск. На своей машине это ничто, на сервере, где
    /// бота держат ради работы, а не ради чтения подписей, — заметно.
    ///
    /// Выключено — окно НЕ МОЛЧИТ, а говорит, что подписи выключены нарочно и
    /// каким ключом их вернуть. Иначе это неотличимо от «панель недоделана»,
    /// а именно такую жалобу мы уже получали про голый список ручек.
    /// </summary>
    public bool Explanations { get; set; } = true;

    /// <summary>Каталог ролей — панель показывает из него список.</summary>
    public RoleCatalog? Roles { get; set; }

    /// <summary>
    /// СЕКРЕТЫ БОТА: ключ нейросети, заданный из этого самого окна. Заводится
    /// один на панель и живёт здесь потому, что ЗАПИСЫВАЕТ в него ровно один —
    /// окно; читает же его тот, кто поднимает клиента нейросети, и читает через
    /// окружение процесса (см. <see cref="BotSecrets"/>).
    ///
    /// Наружу отсюда не выходит НИЧЕГО, кроме «задан / не задан»: ответ
    /// <c>/api/ai</c> несёт только это, ровно как и снимок поставщиков.
    /// </summary>
    public BotSecrets Secrets { get; set; } = new();

    /// <summary>Библиотека готовых ботов.</summary>
    public PresetLibrary Presets { get; set; } = new();

    /// <summary>Набор инструментов (тот же, что у нейросети).</summary>
    public BotToolbox? Tools { get; set; }

    /// <summary>Настройки запуска — панель показывает их без секретов.</summary>
    public BotConfig? Config { get; set; }

    /// <summary>
    /// Чем спросить пароль администратора при запуске — ввод БЕЗ ЭХА.
    ///
    /// Не задано — спрашивать некому (служба без консоли, режим MCP, где stdin
    /// занят протоколом). Тогда «panel.askPassword: true» не превращается молча
    /// в «пароля нет»: <see cref="PanelPasswordSource"/> объявляет беду, и
    /// <see cref="Start"/> честно отказывается открывать окно.
    /// </summary>
    public Func<string, string?>? AskSecret { get; set; }

    /// <summary>
    /// Чем читать переменные окружения. Довод, а не прямое обращение, — чтобы
    /// шов «переменная VS_PANEL_PASSWORD → запертая дверь» проверялся тестом,
    /// не правя окружение всего процесса.
    /// </summary>
    public Func<string, string?> Env { get; set; } = Environment.GetEnvironmentVariable;

    /// <summary>
    /// Чем заперта дверь — словами, как это сказано в журнал при
    /// <see cref="Start"/>. Пароля и отпечатка в этой строке нет и быть не может.
    /// </summary>
    public string DoorNote { get; private set; } = "";

    /// <summary>
    /// Очередь задач: бегун, в котором лежит и сама очередь
    /// (<see cref="WorkRunner.Plan"/>), и виды работ роли
    /// (<see cref="WorkRunner.Catalog"/>).
    ///
    /// Одна ручка, а не три, нарочно: очередь у бегуна уже есть, и завести
    /// рядом с ней вторую значило бы получить панель, которая правит не тот
    /// список, который исполняется.
    /// </summary>
    public WorkRunner? Jobs { get; set; }

    /// <summary>
    /// Файл очереди. Панель зовёт <see cref="WorkPlanStore.Save"/> после
    /// КАЖДОЙ правки: очередь на вечер не должна пропасть оттого, что бота
    /// перезапустили между задачами.
    /// </summary>
    public WorkPlanStore? JobsStore { get; set; }

    /// <summary>Виды работ роли — берутся у бегуна, второго списка не заводим.</summary>
    private WorkCatalog? Works => Jobs?.Catalog;

    /// <summary>Сама очередь — она же у бегуна.</summary>
    private WorkPlan? Plan => Jobs?.Plan;

    /// <summary>
    /// Аккаунт: панель умеет входить и выходить.
    ///
    /// Пароль здесь ТОЛЬКО ПРОХОДИТ НАСКВОЗЬ: приходит одним запросом по петле,
    /// уходит в сервер аккаунтов и забывается. Он не сохраняется, не пишется
    /// в журнал и не отдаётся обратно ни в каком виде.
    /// </summary>
    public BotAccount? Account { get; set; }

    /// <summary>
    /// ОКНО ПРОСИТ СМЕНИТЬ РОЛЬ НА ГОТОВОГО БОТА — и держатель бота отвечает
    /// ИТОГОМ, а не молчанием.
    ///
    /// БЫЛО <c>Action&lt;string&gt;</c>, и окно узнавало о смене одним способом:
    /// перечитывало <c>bot.Role</c>. То есть видело «роль другая», но не видело
    /// «вернулось ли всё»: <see cref="СменаРоли.Целиком"/> ему был недоступен.
    /// В итоге окно писало «перезапуск не нужен», а бот в ту же секунду писал в
    /// журнал «бот сейчас полубот; перезапустите его» — два противоположных
    /// ответа на одно нажатие.
    ///
    /// null в ответе — сменить роль НЕКОМУ (окно подняли без держателя бота) или
    /// готовый бот не собрался; и то и другое окно говорит вслух.
    /// </summary>
    public event Func<string, СменаРоли?>? OnRestartRequested;

    public event Action<string>? OnLog;

    /// <summary>
    /// Адрес с ключом — то, что открывают в браузере.
    ///
    /// ЭТО СЕКРЕТ ЦЕЛИКОМ: кто знает ссылку, тот управляет ботом. Его нельзя
    /// писать в журнал (файл читаемый, да ещё и с восемью архивными копиями) —
    /// только показать человеку здесь и сейчас. Для журнала есть <see cref="Where"/>.
    ///
    /// ЗАДАН ПАРОЛЬ — КЛЮЧА В АДРЕСЕ НЕТ, и это не мелочь: ключ там ничего не
    /// открывает, а напечатанный он выглядел бы как доступ и осел бы в истории
    /// браузера ни за чем.
    /// </summary>
    public string Url => Door.HasPassword ? Where : $"http://127.0.0.1:{http.Port}/?k={Key}";

    /// <summary>Адрес БЕЗ ключа — этот можно и в журнал, и в чат.</summary>
    public string Where => $"http://127.0.0.1:{http.Port}/";

    public ControlPanel(VsBot bot, int port = DefaultPort)
    {
        this.bot = bot;
        http = new MiniHttp(port);
        http.OnLog += m => OnLog?.Invoke(m);
        http.Handle = HandleAsync;

        // Карта сервера — чужая машина в интернете. И то, что бот к ней пошёл,
        // и то, что она не ответила, человек читает в журнале, а не гадает,
        // почему подложка пустая
        webMap.OnLog += m => OnLog?.Invoke(m);

        // Ключ рождается заново при каждом запуске (см. PanelDoor): старая
        // ссылка, оставшаяся в истории браузера, управлять новым ботом не должна

        // ЧТО СЛУЧИЛОСЬ С ФАЙЛОМ СЕКРЕТОВ — в тот же журнал. Значений там не
        // бывает никогда: только имя переменной и путь к файлу
        Secrets.OnLog += m => OnLog?.Invoke($"[секреты] {m}");

        // Журнал бота — то, ради чего панель чаще всего и открывают
        bot.OnLog += Remember;

        // Чем кончилось дело, видно было только в журнале — а журнал к тому
        // времени уже уехал вверх на сотню строк. Панель запоминает последний
        // итог отдельно, чтобы «что делал и чем кончилось» было видно сразу
        bot.Skills.OnSkillCompleted += RememberSkill;

        // «Не в игре» — правда, но не вся: бот мог быть выкинут сервером минуту
        // назад и как раз возвращаться. Запоминаем ПОСЛЕДНЕЕ СЛУЧИВШЕЕСЯ, а не
        // догадку о будущем: гадать, вернётся ли он, панель не вправе
        bot.Client.OnJoined += RememberJoined;
        bot.Client.OnDisconnected += RememberDisconnected;
        bot.Client.OnReconnecting += RememberReconnecting;

        // РУЧКУ КРУТЯТ НЕ ТОЛЬКО ЗДЕСЬ. Дом и склад задают ещё и словом в чате
        // («!дом тут», «!склад тут»), и накрученное словом обязано лечь в тот же
        // файл, что и накрученное мышью: жалоба заказчика «запоминание не
        // работает у дома и склада» — ровно про это.
        //
        // ПОЧЕМУ ОКНО ПЕРЕБИВАЕТ ЗАПИСЫВАЮЩЕГО, КОТОРОГО УЖЕ ПОСТАВИЛ ЗАПУСК.
        // Библиотека пресетов и настройки запуска у окна СВОИ (их кладут
        // снаружи, см. Presets и Config), и они могут быть не теми, что взял
        // запуск. Писать надо туда, откуда окно читает, — иначе человек правит
        // в браузере один файл, а словом в чате наполняет другой.
        //
        // Второй записи ручек при этом не заводится: SaveKnobs — тонкая обёртка
        // над тем же PresetLibrary.ЗапомнитьРучки, каким пользуется запуск
        bot.ЗапомнитьРучкиРоли = SaveKnobs;
    }

    private void RememberSkill(string name, SkillResult result)
    {
        string args = string.Equals(startedName, name, StringComparison.OrdinalIgnoreCase)
            ? startedArgs ?? ""
            : "";
        lastSkill = new SkillDone(name, args, result.Success, result.Message ?? "", DateTime.Now);
        startedName = null;
        startedArgs = null;
    }

    private void RememberJoined() => link = new LinkNote("вошёл в игру", "", DateTime.Now);

    private void RememberDisconnected(string reason) =>
        link = new LinkNote("отключён сервером", reason, DateTime.Now);

    private void RememberReconnecting(int attempt) =>
        link = new LinkNote("попытка вернуться", $"№{attempt}", DateTime.Now);

    private void Remember(string line)
    {
        lock (logLock)
        {
            log.Add($"{DateTime.Now:HH:mm:ss} {line}");
            saidLines++;
            if (log.Count > LogLines * 2)
            {
                int cut = log.Count - LogLines;
                log.RemoveRange(0, cut);
                firstLine += cut;
            }
        }
    }

    /// <summary>
    /// Открыть панель. Возвращает адрес для браузера.
    ///
    /// ДВЕРЬ ЗАПИРАЕТ САМА ПАНЕЛЬ, И ЭТО ГЛАВНОЕ ЗДЕСЬ. Пароль администратора
    /// умели брать (<see cref="PanelPasswordSource"/>) и умели проверять
    /// (<see cref="PanelDoor"/>), но звать их было некому: запуск бота создавал
    /// панель и сразу открывал её, минуя дверь. Заказчик ставил
    /// «export VS_PANEL_PASSWORD=…», получал в консоли прежнюю ссылку с ключом
    /// и был уверен, что окно заперто паролем. Поэтому пароль берётся ЗДЕСЬ:
    /// открыть панель, не спросив про дверь, теперь нельзя ниоткуда.
    /// </summary>
    /// <exception cref="InvalidOperationException">
    /// Пароль ПРОСИЛИ, а взять его не вышло (мусор в переменной с отпечатком,
    /// одни пробелы в переменной с паролем, «спросить при запуске» без консоли).
    /// Окно тогда не открывается вовсе — и это нарочно: пустить по ключу того,
    /// кто просил пароль, значит оставить дверь распахнутой, а человека — в
    /// уверенности, что заперли.
    /// </exception>
    public string Start()
    {
        LockDoor();
        http.Start();
        // В ЖУРНАЛ — БЕЗ КЛЮЧА И БЕЗ ПАРОЛЯ. Ссылка с ключом это и есть доступ
        // к боту, а журнал лежит обычным файлом и хранит восемь прошлых копий.
        // Чем именно заперта дверь, сказать надо: «панель открыта» без этого
        // слова человек читает как «её видно всем»
        OnLog?.Invoke(Door.HasPassword
            ? $"окно управления открыто: {Where} (вход по паролю администратора)"
            : $"окно управления открыто: {Where} (ключ доступа — в консоли запуска)");
        OnLog?.Invoke("оно доступно ТОЛЬКО с этой машины; на сервере — через " +
                      $"«ssh -L {http.Port}:127.0.0.1:{http.Port} …»");

        // ЗАМЕТКИ КАТАЛОГА РОЛЕЙ ЗДЕСЬ НЕ ПИШУТСЯ — И ЭТО НАРОЧНО.
        //
        // ЖИВОЙ СЛУЧАЙ СБОРКИ. Две правки одной волны завели их в журнал
        // порознь: приложение — сразу после Roles.Catalog() («[роли] …»), окно
        // — вот здесь («[панель] роли: …»). В прогоне с папкой «roles» человек
        // читал КАЖДУЮ строку дважды подряд, слово в слово: «своя роль
        // „сторож“ … из „МояРоль.dll“» — и первым делом искал, не поднялись ли
        // две роли вместо одной.
        //
        // Говорит о них тот, кто говорит ВСЕГДА: приложение (Program.cs). Окно
        // человек выключает («panel.use: false»), и тогда рассказ о взятом
        // чужом коде пропал бы вместе с ним. В САМОМ окне заметки на месте —
        // они стоят рядом со списком ролей (см. PresetList: поле «заметки»),
        // а это не журнал, это другая пара глаз.
        return Url;
    }

    /// <summary>
    /// ВЗЯТЬ ПАРОЛЬ АДМИНИСТРАТОРА И ЗАПЕРЕТЬ ИМ ДВЕРЬ.
    ///
    /// Правило «откуда берётся пароль» живёт одно и целиком в
    /// <see cref="PanelPasswordSource.Take"/> — здесь только его вызов и то, что
    /// панель делает с ответом. Три исхода:
    ///   • пароль взят — дверь закрыта им, ключ в ссылке перестаёт что-либо
    ///     открывать (см. <see cref="PanelDoor"/>);
    ///   • пароля не просили — прежний порядок, ключ в ссылке;
    ///   • пароль просили, а взять не вышло — окно НЕ открывается.
    ///
    /// В журнал уходит только строка выбора: пароля и отпечатка в ней нет.
    /// </summary>
    private void LockDoor()
    {
        // Заперли снаружи (так делают тесты и встраивание в чужую программу) —
        // не трогаем: свой пароль тут был бы слабее того, что уже поставили
        if (Door.HasPassword)
        {
            DoorNote = "вход по паролю администратора (задан до запуска окна)";
            OnLog?.Invoke($"дверь: {DoorNote}");
            return;
        }

        var выбор = PanelPasswordSource.Take(Config?.Panel, AskSecret, Env);
        DoorNote = выбор.Say;
        OnLog?.Invoke($"дверь: {выбор.Say}");

        if (выбор.Trouble)
            throw new InvalidOperationException(
                выбор.Say + ". Окно управления НЕ открыто нарочно: пустить по ключу того, " +
                "кто просил пароль, значит оставить дверь распахнутой, а человека — " +
                "в уверенности, что заперли");

        if (выбор.Fingerprint is { } отпечаток)
            Door.UsePassword(отпечаток);
    }

    public void Stop() => http.Stop();

    public void Dispose()
    {
        bot.OnLog -= Remember;
        bot.Skills.OnSkillCompleted -= RememberSkill;
        bot.Client.OnJoined -= RememberJoined;
        bot.Client.OnDisconnected -= RememberDisconnected;
        bot.Client.OnReconnecting -= RememberReconnecting;
        http.Dispose();
        webMap.Dispose();
    }

    /// <summary>
    /// Попробовать открыть страницу в браузере хозяина. Не вышло — не беда:
    /// адрес всё равно напечатан.
    /// </summary>
    public bool OpenInBrowser()
    {
        try
        {
            System.Diagnostics.Process.Start(
                new System.Diagnostics.ProcessStartInfo(Url) { UseShellExecute = true });
            return true;
        }
        catch (Exception e)
        {
            OnLog?.Invoke($"браузер сам не открылся ({e.Message}) — откройте ссылку руками");
            return false;
        }
    }

    // ---------------- разбор запросов ----------------

    private async Task<HttpAnswer> HandleAsync(HttpRequest r)
    {
        // Чужая страница не должна дотянуться до панели через подмену имени:
        // браузер пришёл бы с нашей же машины, и петля тут не защита
        if (r.H("host") is { } host && !IsOurHost(host))
            return HttpAnswer.Denied("панель отвечает только на 127.0.0.1");

        // Кого пускать, решает дверь: ключ этого запуска или пароль
        // администратора, если он задан. Здесь только достаём то, чем стучатся
        var впуск = Door.Enter(r.Q("k"), r.H("x-panel-key"), PassOf(r));
        if (!впуск.Ok)
            return Outside(r, впуск);

        return r.Path switch
        {
            "/" or "/index.html" => HttpAnswer.Html(Page()),
            "/api/door" => HttpAnswer.Json(DoorState(inside: true)),
            "/api/panel/login" => AlreadyIn(),
            "/api/panel/logout" => PanelLogout(r),
            "/api/state" => HttpAnswer.Json(State()),
            "/api/log" => HttpAnswer.Json(LogTail(r)),
            "/api/commands" => HttpAnswer.Json(Commands()),
            "/api/skills" => HttpAnswer.Json(Skills()),
            "/api/tools" => HttpAnswer.Json(ToolList()),
            "/api/role" => HttpAnswer.Json(RoleState()),
            "/api/presets" => HttpAnswer.Json(PresetList()),
            // КОНСТРУКТОР РОЛИ: настройки роли, которой сейчас никто не бегает.
            // Заказчик: «нужен конструктор ролей прямо в вебформе». Роль и
            // готовый бот приходят СТРОКОЙ ЗАПРОСА: у каждой открытой вкладки
            // свой черновик, и держать его у бота значило бы завести второе
            // место, где живут настройки
            "/api/builder" => HttpAnswer.Json(BuilderState(r)),
            "/api/settings" => HttpAnswer.Json(Settings()),
            "/api/account" => HttpAnswer.Json(AccountState()),
            "/api/cheats" => HttpAnswer.Json(CheatState()),
            "/api/memory" => HttpAnswer.Json(MemoryState()),
            "/api/works" => HttpAnswer.Json(WorkList(r)),
            "/api/jobs" => HttpAnswer.Json(JobList()),
            "/api/inventory" => HttpAnswer.Json(InventoryState()),
            // КАРТИНКА ПРЕДМЕТА — готовый файл из папки рядом с ботом. Бот их
            // не рисует (нечем: видеокарты нет), а вот показать выгруженные
            // графическим клиентом — может; см. ItemIcons
            "/api/icon" => IconFile(r),
            // «ЧТО БОТ ПОНЯЛ ПОД ЭТИМ СЛОВОМ» — пока человек ещё набирает.
            // Тот же поиск по именам, каким бот переводит слово в код при
            // исполнении задачи (Errands.Suggest), и та же картинка
            "/api/things" => HttpAnswer.Json(ThingSuggest(r)),
            "/api/depot" => HttpAnswer.Json(DepotState()),
            // Масштаб карты приходит СТРОКОЙ ЗАПРОСА, а не настройкой: у каждой
            // открытой вкладки свой взгляд, и записывать его в bot.json значило
            // бы менять чужое окно из своего (см. MapState)
            "/api/map" => HttpAnswer.Json(MapState(r)),
            "/api/ai" => HttpAnswer.Json(AiState()),
            // Отбор весов приходит СТРОКОЙ ЗАПРОСА (от/до/слово/изменённые):
            // у каждой открытой вкладки свой взгляд на список, и записывать его
            // в настройки бота значило бы менять чужое окно из своего
            "/api/weights" => HttpAnswer.Json(WeightsState(r)),

            "/api/account/login" => await LoginAsync(r),
            "/api/account/logout" => Logout(),
            "/api/bot/connect" => BotConnect(r),
            "/api/bot/disconnect" => BotDisconnect(r),
            "/api/bot/reconnect" => BotReconnect(),
            "/api/cheats/set" => SetCheat(r),
            "/api/memory/set" => SetMemory(r),

            "/api/say" => await SayAsync(r),
            "/api/command" => await CommandAsync(r),
            "/api/skill" => await SkillAsync(r),
            "/api/skill/stop" => StopSkill(),
            "/api/tool" => await ToolAsync(r),
            "/api/role/set" => SetKnob(r),
            "/api/weights/set" => SetWeight(r),
            // КЛЮЧ НЕЙРОСЕТИ — ТОЛЬКО НА ВВОД. Дверь односторонняя нарочно:
            // отдать ключ обратно окну нельзя, а прочитать «задан ли» можно
            // через /api/ai. См. BotSecrets
            "/api/ai/key" => AiKeySet(r),
            "/api/preset/save" => SavePreset(r),
            "/api/preset/apply" => ApplyPreset(r),
            // Собранное в конструкторе уходит боту ОДНИМ куском: сохранить
            // половину настроек значит выпустить не того бота, кого собирали
            "/api/builder/save" => BuilderSave(r),

            // «Сколько это займёт» — до пуска и без постановки в очередь
            "/api/jobs/eta" => JobEta(r),
            // «ВО ЧТО ПРЕВРАТИТСЯ ЗАКАЗ» — пока человек ещё набирает задание.
            // Заказчик: «лучше отображать в вебформе тоже, придумай красиво в
            // конструкторе задачи». Считает библиотека, окно только показывает
            "/api/jobs/preview" => JobPreview(r),
            "/api/jobs/add" => AddJob(r),
            "/api/jobs/set" => SetJob(r),
            "/api/jobs/copy" => CopyJob(r),
            "/api/jobs/move" => MoveJob(r),
            "/api/jobs/remove" => RemoveJob(r),
            "/api/jobs/enable" => EnableJob(r),
            "/api/jobs/repeat" => RepeatJob(r),
            "/api/jobs/run" => RunJobs(r),
            "/api/jobs/stop" => StopJobs(),

            // «Посмотри папку с картинками заново» — человек кладёт их при
            // живом боте и ждёт ответа сразу, а не через срок обхода
            "/api/icons/rescan" => IconsRescan(),

            "/api/depot/ask" => AskDepot(r),
            "/api/depot/scan" => await ScanDepotAsync(),

            "/api/map/set" => SetMap(r),

            // ТОЧКА НА КАРТЕ — И БОТ САМ РЕШАЕТ, КАК ТУДА ПОПАСТЬ. Заказ
            // дословно: «хочу по веб админке на карте давать точку куда ему
            // бежать, и он уже думал, через телепорты или пешком и шел».
            // Шага ДВА нарочно: «покажи план» и «иди». Случайный щелчок по
            // карте не должен уводить бота за десять тысяч блоков
            "/api/map/pick" => MapPickAnswer(r),
            "/api/map/goto" => MapGoTo(r),

            // НАРИСОВАННОЕ НА КАРТЕ → ПОЛЯ ТОЙ ЖЕ ЗАДАЧИ. Заказ дословно:
            // «добавим добавление задач с карты, чтобы можно было нарисовать
            // где копать к примеру». Отдельного пути в очередь тут НЕТ: ответ
            // только называет поля, а ставит задачу тот же конструктор
            "/api/map/draw" => MapDrawAnswer(r),

            // ПРАВАЯ КНОПКА НА ВЕЩИ во вкладке «Инвентарь». Заказчик: «чтобы
            // можно в вебформе пкм на предмет и выбирать на него надеть,
            // отнести на склад или выкинуть»
            "/api/inventory/wear" => await WearItemAsync(r),
            // СНЯТЬ — вторая половина той же пары. Жалоба заказчика: «в вебформе
            // инвентаря нельзя снять вручную броню, ток надеть»
            "/api/inventory/undress" => await TakeOffItemAsync(r),
            // «Снять всю броню» одной кнопкой — той же дверью, которой бот
            // раздевается сам, когда рядом стало тихо
            "/api/inventory/undress-all" => await TakeOffArmorAsync(),
            "/api/inventory/hand" => await HoldItemAsync(r),
            "/api/inventory/haul" => await HaulItemAsync(r),
            "/api/inventory/drop" => await DropItemAsync(r),

            _ => HttpAnswer.NotFound()
        };
    }

    private static bool IsOurHost(string host)
    {
        string name = host.Split(':')[0].Trim('[', ']');
        return name is "127.0.0.1" or "localhost" or "::1" or "";
    }

    /// <summary>
    /// КУДА ЧЕЛОВЕКУ КЛАСТЬ ВЫГРУЖЕННЫЕ КАРТИНКИ — полным путём, одной строкой.
    ///
    /// ЖИВОЙ ПРОГОН 15.08: «нет текстур в инвентаре, мы же обсуждали». Разбор
    /// показал не поломку, а молчание: бот говорил «картинок нет» и звал в
    /// ЗАПУСК.md, но НИ РАЗУ не называл папку, в которую их ждёт. Человек
    /// выгрузил бы их за минуту, знай он, куда положить.
    ///
    /// Папку НЕ ВЫДУМЫВАЕМ: берём первую из тех, что бот и правда обходит
    /// (<see cref="ItemIcons.FolderCandidates()"/>) — иначе рецепт послал бы
    /// человека класть файлы туда, куда бот не смотрит.
    /// </summary>
    private static string IconsFolderWanted()
    {
        // Папка уже нашлась — называем ЕЁ: человек кладёт добавку туда же,
        // где лежит остальное
        if (ItemIcons.Look().Path is { Length: > 0 } нашлась)
            return нашлась;
        foreach (string куда in ItemIcons.FolderCandidates())
            return куда;
        return "";
    }

    /// <summary>
    /// «ПОСМОТРИ ПАПКУ ЗАНОВО» — по нажатию, а не через двадцать секунд.
    ///
    /// Человек кладёт картинки при живом боте и тут же смотрит в окно. Ждать
    /// молча, пока подойдёт срок обхода, — это то же самое молчание, из-за
    /// которого он и решил, что «текстур нет»: сделал всё правильно, а окно не
    /// изменилось, и понять, дошло или нет, нечем.
    /// </summary>
    private HttpAnswer IconsRescan()
    {
        ItemIcons.Forget();
        var папка = ItemIcons.Look();
        // Успех — ТОЛЬКО ПО ФАКТУ: сколько файлов вправду нашлось. «Готово»
        // без числа человек проверить не может
        return HttpAnswer.Json(Answer(папка.Files > 0,
            папка.Files > 0
                ? $"нашёл картинок: {папка.Files} шт. в {папка.Path}. Обновите страницу — " +
                  "в клетках появятся те, что выгружены"
                : $"картинок не нашлось. Жду папку «{ItemIcons.FolderName}» здесь: " +
                  $"{IconsFolderWanted()} — внутри неё должны лежать " +
                  $"«{ItemIcons.BlockFolder}» и «{ItemIcons.ItemFolder}» с png", []));
    }

    /// <summary>
    /// КАРТИНКА ОДНОГО ПРЕДМЕТА. Отдельным запросом, а не строкой внутри json
    /// инвентаря: картинок в сетке до сотни, и вшей мы их в ответ (data:base64),
    /// каждый опрос окна таскал бы мегабайты ради того, что не меняется вовсе.
    /// Отдельные запросы браузер к тому же кеширует сам.
    ///
    /// «вид» СПРАШИВАЕМ, А НЕ УГАДЫВАЕМ: блок и предмет с одним кодом — не
    /// редкость (candle, cheese, egg, leather, ore, paper…), и картинки у них
    /// разные. Кто спрашивает, тот и знает, что у него в клетке.
    ///
    /// Нет файла — честный 404 со словами, а не пустая картинка: пустая
    /// картинка в клетке неотличима от «у бота там пусто».
    /// </summary>
    private static HttpAnswer IconFile(HttpRequest r)
    {
        string код = r.Q("code") ?? "";
        if (код.Length == 0)
            return HttpAnswer.Bad("не сказано, какой предмет рисовать (code)");

        string вид = r.Q("kind") ?? "";
        if (вид is not (ItemIcons.BlockFolder or ItemIcons.ItemFolder))
            return HttpAnswer.Bad(
                $"«вид» бывает только {ItemIcons.BlockFolder} или {ItemIcons.ItemFolder}, " +
                $"а спросили «{вид}»");

        return ItemIcons.Bytes(код, вид == ItemIcons.BlockFolder) is { } png
            ? HttpAnswer.Png(png)
            : HttpAnswer.NotFound($"картинки для «{код}» рядом с ботом нет — {ItemIcons.Recipe}");
    }

    /// <summary>
    /// ЧТО БОТ ПОНЯЛ ПОД НАБРАННЫМ СЛОВОМ — списком, с настоящим кодом и
    /// картинкой.
    ///
    /// ПРЯМАЯ ПРОСЬБА ЗАКАЗЧИКА 16.08: «при выдаче задания на поиск чего-либо и
    /// добычу неплохо выпадающий список при вводе с иконкой, чтобы я точно знал,
    /// что бот понял меня». Поле «что» у наряда — обычная строка: человек писал
    /// в неё «медь» и узнавал, что из этого вышло, ЧЕРЕЗ СОРОК МИНУТ.
    ///
    /// ИЩЕТ НЕ ЭТОТ МЕТОД. Имена ищет <see cref="Errands.Suggest"/> — тем же
    /// поиском по языковым файлам игры и тем же реестром сервера, каким бот
    /// переводит слово человека в код, когда задача уже пошла
    /// (<see cref="Errands.Resolve"/>). Второго поиска по именам в проекте нет.
    /// Картинку называет <see cref="ItemIcons.Ask"/> — тот же один способ на все
    /// вкладки, где есть вещи.
    ///
    /// ЧЕГО ЗДЕСЬ НЕТ. Догадки. Пустой список — это ответ «не знаю такого», и он
    /// приходит СО СЛОВАМИ: реестр ещё не пришёл, языковых файлов нет, или
    /// такого имени в игре нет вовсе. Молчаливый пустой список человек читает
    /// как «подсказки сломались» и набирает дальше вслепую.
    /// </summary>
    private string ThingSuggest(HttpRequest r)
    {
        string набрано = (r.Q("q") ?? "").Trim();
        int сколько = int.TryParse(r.Q("сколько"), out int n) && n is > 0 and <= 30 ? n : 8;

        // ФАКТЫ, БЕЗ КОТОРЫХ ПОДСКАЗЫВАТЬ НЕЧЕМ, — оба спрашиваются дёшево и
        // оба нужны человеку словами. Реестр приходит пакетом при входе в мир,
        // языковые файлы лежат у установленной игры; не бывает ни того, ни
        // другого — и это разные беды с разным лечением
        // «ПРИШЁЛ ЛИ РЕЕСТР» — вопрос к самому реестру (WorldModel.BlockRegistryReady),
        // а не поиск-пустышка по нему: тот же вопрос задаёт разбор заказа, и
        // две разные мерки готовности разошлись бы в тот же день, когда одна из
        // них научится отвечать раньше другой
        bool реестрЕсть = bot.World.BlockRegistryReady;
        int имён = bot.Errands.Lang?.NameCount ?? 0;

        var найдено = реестрЕсть && набрано.Length > 0
            ? bot.Errands.Suggest(набрано, сколько)
            : [];

        return JsonSerializer.Serialize(new
        {
            набрано,
            есть = найдено.Count > 0,
            почему = набрано.Length == 0 ? ""
                : !реестрЕсть
                    ? "реестр блоков сервера ещё не пришёл — что такое " +
                      $"«{набрано}», сказать пока не могу"
                : найдено.Count > 0 ? ""
                : имён == 0
                    ? $"«{набрано}» не похоже ни на один код реестра сервера, а языковых " +
                      "файлов игры у меня нет и по человеческому имени искать нечем"
                    : $"«{набрано}»: ни кода с таким именем в реестре сервера, ни такого " +
                      $"имени среди {имён} названий игры",
            вещи = найдено.Select(в =>
            {
                // Один код бывает И блоком, И предметом (candle, cheese, egg,
                // ore…), и картинки у них разные — поэтому «блок или предмет»
                // спрашивается у реестра, а не у вида кода
                var значок = ItemIcons.Of(в.Code, в.IsBlock);
                return new
                {
                    код = в.Code,
                    имя = в.Name,
                    блок = в.IsBlock,
                    класс = значок.Kind,
                    картинка = значок.Has,
                    // Насколько точно попали: 0 — имя названо целиком, 3 —
                    // принято за опечатку в одну букву. Человеку это надо
                    // видеть: «принял за опечатку» и «так и называется» —
                    // очень разная уверенность
                    точность = в.Nearness,
                    // Слова про уверенность живут у самой находки
                    // (ThingName.Understood): их читает и разбор заказа
                    // («во что превратится наряд»), и вторая такая же лесенка
                    // разошлась бы с этой на первой же новой ступени точности
                    какПонял = в.Understood
                };
            })
        }, Json);
    }

    // ---------------- дверь: пароль администратора ----------------

    /// <summary>
    /// Пропуск вошедшего. Двумя путями, потому что панель смотрят двумя:
    /// браузер носит печеньку сам, а скрипт (curl, проверка живости) ставит
    /// заголовок руками.
    /// </summary>
    private static string? PassOf(HttpRequest r) =>
        r.H("x-panel-pass") is { Length: > 0 } заголовок
            ? заголовок
            : PanelDoor.CookieValue(r.H("cookie"), PanelDoor.CookieName);

    /// <summary>
    /// Что видно ДО входа. Ровно три вещи и ни одной больше: страница входа,
    /// сама попытка входа и «заперто ли» без единой подробности. Любой другой
    /// путь отвечает отказом с причиной — молчаливый 403 человек читает как
    /// поломку окна и лезет чинить сеть.
    /// </summary>
    private HttpAnswer Outside(HttpRequest r, DoorVerdict впуск)
    {
        if (!Door.HasPassword)
            return HttpAnswer.Text(впуск.Why, впуск.Code);

        return r.Path switch
        {
            "/" or "/index.html" => HttpAnswer.Html(LoginPage()),
            "/api/panel/login" => PanelLogin(r),
            "/api/door" => HttpAnswer.Json(DoorState(inside: false)),
            _ => HttpAnswer.Text(впуск.Why, впуск.Code)
        };
    }

    /// <summary>
    /// Попытка входа по паролю.
    ///
    /// ПАРОЛЬ ОТСЮДА НИКУДА НЕ ИДЁТ: он уходит в дверь, там превращается в
    /// отпечаток для сравнения и забывается. В журнал пишется ТОЛЬКО итог
    /// словами — ни пароля, ни его длины, ни первых букв.
    /// </summary>
    private HttpAnswer PanelLogin(HttpRequest r)
    {
        var итог = Door.Login(Field(Body(r), "пароль"));

        OnLog?.Invoke(итог.Ok
            ? "вход в окно управления по паролю администратора"
            : $"в окно управления не пустило: {итог.Why}");

        string json = JsonSerializer.Serialize(new
        {
            ok = итог.Ok,
            message = итог.Ok ? "вошли" : итог.Why,
            // Сколько ждать — числом, чтобы страница входа могла показать
            // обратный отсчёт, а не предлагать жать кнопку впустую
            ждатьСекунд = (int)Math.Ceiling(Door.Guard.Wait(Door.Clock()).TotalSeconds)
        }, Json);

        var ответ = HttpAnswer.Json(json, итог.Code);
        // Пропуск уходит ТОЛЬКО печенькой и только сейчас: в теле ответа его
        // нет, чтобы он не осел в журнале браузера и в чужом расширении
        return итог.Ok
            ? ответ.WithCookie(PanelDoor.CookieName, итог.Token,
                (int)Door.PassLife.TotalSeconds)
            : ответ;
    }

    /// <summary>Выйти из окна: пропуск гасится и здесь, и в браузере.</summary>
    private HttpAnswer PanelLogout(HttpRequest r)
    {
        // Без пароля выходить не из чего, и молчать об этом нельзя: человек
        // нажал «Выход», увидел «вышли» и ушёл, оставив окно открытым
        if (!Door.HasPassword)
            return HttpAnswer.Json(Fail(
                "пароль администратора не задан — выходить не из чего: окно пускает " +
                "по ключу в адресе, и закрыть его можно только остановкой бота"));

        Door.Leave(PassOf(r));
        OnLog?.Invoke("вышли из окна управления");
        // Max-Age=0 — браузеру велено печеньку забыть; без этого кнопка «Выход»
        // оставляла бы в браузере мёртвый пропуск и путала следующего
        return HttpAnswer.Json(Ok("вышли из окна"))
            .WithCookie(PanelDoor.CookieName, "", 0);
    }

    /// <summary>Вход, когда уже внутри. Отвечаем правду про эту дверь.</summary>
    private HttpAnswer AlreadyIn() => HttpAnswer.Json(Door.HasPassword
        ? Ok("уже вошли")
        : Fail("пароль администратора в этом запуске не задан: окно пускает по ключу " +
               "в адресе (полная ссылка печатается в консоли при запуске бота)"));

    /// <summary>
    /// Состояние двери НАРУЖУ: «задан / не задан» и сколько ждать. Ни пароля,
    /// ни отпечатка, ни ключа, ни пропуска здесь нет и быть не может — окно
    /// оставляют открытым на весь вечер.
    /// </summary>
    private string DoorState(bool inside) =>
        JsonSerializer.Serialize(Door.State(inside), Json);

    /// <summary>
    /// СТРАНИЦА ВХОДА — единственное, что видно из окна до пароля.
    ///
    /// Она отдельная и крошечная нарочно. Настоящая страница панели весит сотню
    /// килобайт и по десять раз в секунду спрашивает у бота состояние, роль,
    /// очередь и журнал; отдавать её тому, кто пароля не знает, значит отдавать
    /// ему имя бота, имя роли и весь список умений — то есть половину того, что
    /// пароль и закрывает.
    /// </summary>
    private static string LoginPage() =>
        """
        <!doctype html>
        <html lang="ru">
        <head>
        <meta charset="utf-8">
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <title>Vintage Bot Story — вход</title>
        <style>
          /* Ничего со стороны: панель обязана работать на машине без сети */
          :root { --фон:#14161a; --карточка:#1c2027; --рамка:#2b313b;
                  --текст:#e6e9ee; --тихий:#98a2b3; --свой:#6ea8fe; --беда:#e5776a; }
          @media (prefers-color-scheme: light) {
            :root { --фон:#f4f6f9; --карточка:#fff; --рамка:#dde2e9;
                    --текст:#1b2027; --тихий:#5d6b7f; --свой:#1f6feb; }
          }
          * { box-sizing: border-box; }
          body { margin:0; min-height:100vh; display:flex; align-items:center;
                 justify-content:center; background:var(--фон); color:var(--текст);
                 font:15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
          form { background:var(--карточка); border:1px solid var(--рамка);
                 border-radius:10px; padding:20px; width:min(380px, 92vw); }
          h1 { font-size:17px; margin:0 0 4px; }
          p { color:var(--тихий); font-size:13px; margin:0 0 14px; }
          input { width:100%; background:var(--фон); color:var(--текст);
                  border:1px solid var(--рамка); border-radius:7px;
                  padding:9px; font:inherit; }
          input:focus { outline:2px solid var(--свой); outline-offset:-1px; }
          button { margin-top:12px; width:100%; background:var(--свой);
                   border:1px solid var(--свой); color:#fff; padding:9px;
                   border-radius:7px; cursor:pointer; font:inherit; }
          button[disabled] { opacity:.55; cursor:default; }
          #беда { margin-top:12px; color:var(--беда); font-size:13px; display:none; }
        </style>
        </head>
        <body>
        <form id="вход" autocomplete="off">
          <h1>Vintage Bot Story — окно управления</h1>
          <p>Закрыто паролем администратора. Ключ в адресе в этом запуске ничего
             не открывает.</p>
          <input id="пароль" type="password" placeholder="Пароль" autofocus
                 autocomplete="current-password">
          <button id="кнопка" type="submit">Войти</button>
          <div id="беда"></div>
        </form>
        <script>
        const форма = document.getElementById('вход');
        const поле = document.getElementById('пароль');
        const кнопка = document.getElementById('кнопка');
        const беда = document.getElementById('беда');
        let отсчёт = 0;

        function сказать(текст) {
          беда.textContent = текст;
          беда.style.display = текст ? 'block' : 'none';
        }

        // Ждать велено — ждём ВИДИМО. Кнопка, которая молча не работает,
        // читается как поломка, и человек жмёт её чаще, делая себе хуже
        function ждать(секунд, текст) {
          clearInterval(отсчёт);
          if (!секунд) { кнопка.disabled = false; сказать(текст); return; }
          кнопка.disabled = true;
          let осталось = секунд;
          const тик = () => {
            сказать(текст + ' Осталось ' + осталось + ' с.');
            if (осталось-- <= 0) { clearInterval(отсчёт); кнопка.disabled = false; сказать(текст); }
          };
          тик();
          отсчёт = setInterval(тик, 1000);
        }

        форма.addEventListener('submit', async е => {
          е.preventDefault();
          кнопка.disabled = true;
          сказать('');
          try {
            const ответ = await fetch('/api/panel/login', {
              method: 'POST',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ пароль: поле.value })
            });
            const итог = await ответ.json();
            // Пароль не держим в поле ни секунды дольше нужного
            поле.value = '';
            if (итог.ok) { location.replace('/'); return; }
            ждать(итог.ждатьСекунд || 0, итог.message || 'не пустило');
          } catch (е) {
            кнопка.disabled = false;
            сказать('панель не ответила: ' + е.message);
          }
        });
        </script>
        </body>
        </html>
        """;

    private static JsonElement Body(HttpRequest r)
    {
        if (r.Body.Length == 0)
            return default;
        try
        {
            return JsonDocument.Parse(r.Body).RootElement.Clone();
        }
        catch
        {
            return default;
        }
    }

    private static string? Field(JsonElement body, string name) =>
        body.ValueKind == JsonValueKind.Object && body.TryGetProperty(name, out var v)
            ? v.ValueKind == JsonValueKind.String ? v.GetString() : v.ToString()
            : null;

    private static string Ok(string message) =>
        JsonSerializer.Serialize(new { ok = true, message }, Json);

    private static string Fail(string message) =>
        JsonSerializer.Serialize(new { ok = false, message }, Json);

    /// <summary>
    /// Ответ с жалобами. Жалобы едут ОТДЕЛЬНО от «получилось»: у задачи может
    /// быть чужое поле или пустой список масок — это надо сказать вслух, но
    /// набранное человеком из-за этого не теряется.
    /// </summary>
    private static string Answer(bool ok, string message, IReadOnlyList<string> complaints) =>
        JsonSerializer.Serialize(new { ok, message, жалобы = complaints }, Json);

    // ---------------- что показываем ----------------

    private string State()
    {
        var self = bot.Self;

        // «Что делал и чем кончилось» одной строкой. Время берём местное: окно
        // смотрит человек, и ему нужно сверить итог с часами на стене
        var done = lastSkill;
        object? дело = done == null ? null : new
        {
            имя = done.Name,
            аргументы = done.Args,
            получилось = done.Ok,
            сообщение = done.Message,
            когда = done.When.ToString("HH:mm:ss")
        };

        // Точка бота ЧИСЛАМИ и по-игровому — ради кнопки «взять мою точку»:
        // человек стоит там, где хочет поставить склад или центр карьера, и
        // переписывать три числа с экрана игры руками — верный способ
        // ошибиться знаком у Z
        object? точка = null;
        if (bot.Joined && bot.CoordsKnown() && self.Position is { } p)
        {
            var g = bot.GameOf(new BlockPos((int)Math.Floor(p.X), (int)Math.Floor(p.Y),
                (int)Math.Floor(p.Z)));
            точка = new { x = g.X, y = g.Y, z = g.Z };
        }

        return JsonSerializer.Serialize(new
        {
            имя = bot.Name,
            вИгре = bot.Joined,
            // Пока сдвиг спавна не пришёл, перевод игровой точки в мировую
            // уводит на полмиллиона блоков — окно обязано знать об этом и не
            // предлагать «взять мою точку», пока бот не в мире
            координатыИзвестны = bot.CoordsKnown(),
            точка,
            // Пусто, а не «нет»: слово подбирает окно — оно знает свой язык,
            // а роль называет себя сама и переводу не подлежит
            роль = bot.Role?.Name ?? "",
            здоровье = self.Health,
            здоровьеВсего = self.MaxHealth,
            сытость = self.Saturation,
            сытостьВсего = self.MaxSaturation,
            // ВОЗДУХ ПОД ВОДОЙ. Приходит с сервера теми же наблюдаемыми
            // атрибутами, что здоровье и сытость (поддерево «oxygen», ключи
            // currentoxygen/maxoxygen) — по ним же рисует полоску и сам клиент
            // игры (HudStatbar.UpdateOxygen). null — сервер поддерева ещё не
            // прислал; НОЛЬ здесь означал бы «задыхается», и подставлять его
            // нельзя
            воздух = self.Entity?.Oxygen,
            воздухВсего = self.Entity?.MaxOxygen,
            // ТЕМПЕРАТУРА ТЕЛА — поддерево «bodyTemp», ключ «bodytemp».
            // Спрашиваем тот же механизм, который по ней решает, мёрзнет ли
            // бот (BodyHeat): второго описания одного числа не заводим.
            //
            // ЧИСЛО ЗДЕСЬ ВИДИМОЕ, А НЕ СЫРОЕ. Экран персонажа в игре ужимает
            // всё, что выше 37 °C, вдесятеро (BodyHeat.ShownTemperature —
            // там выписан сам код игры), поэтому сырые 45 человек видит как
            // 37,8. Окно писало 45 при том же значке «°C» — и заказчик 17.08
            // сверил его с игрой: «температура в игре другая же, 38 мне
            // казалось максимальная». Он был прав. Верх шкалы взят от той же
            // видимой шкалы, иначе согретый бот стоял бы залитым на треть
            температура = bot.Cold.Ready ? bot.Cold.TemperatureShown : null,
            температураМин = BodyHeat.ColdestTemperature,
            температураМакс = BodyHeat.HottestShownTemperature,
            // ГДЕ У ЭТОГО ЧИСЛА ГРАНИЦЫ, КОТОРЫЕ ЧТО-ТО ЗНАЧАТ. Раньше окну
            // уходила «норма 37», и окно красило всё, что выше нормы, цветом
            // беды — то есть здоровый бот стоял с полной КРАСНОЙ полоской.
            // А верх шкалы у согретого игрока — это НЕ жар: тело в игре копит
            // запас тепла до потолка (см. BodyHeat.HottestTemperature), и 37 не
            // значит ничего видимого. Видимых границ ровно две, и обе приходят
            // от бота — теми же числами, по которым он сам решает, одеваться ли
            // и идти ли к огню (BodyHeat.IsCold/IsDangerousCold). Пересчёта в
            // видимую шкалу они не требуют: обе ниже 37, а там показ игры
            // совпадает с сырым числом (см. BodyHeat.TemperatureShown):
            //   мёрзнет     — ниже 35 игра считает тело мёрзнущим (доля
            //                 замерзания отрывается от нуля, и бот одевается);
            //   обморожение — ниже 33 сервер копит часы до урона Frost
            температураПороги = new
            {
                мёрзнет = bot.Cold.FreezingBelow,
                обморожение = bot.Cold.FrostbiteBelow
            },
            // «Насколько мёрзну» 0..1 — та самая сила эффекта замерзания
            // (freezingEffectStrength), по которой игра и решает, что с телом
            мёрзну = bot.Cold.Ready ? bot.Cold.ColdFraction : (double?)null,
            место = bot.PlayerCoordsHere(),
            // Пока сумок нет (бот не в мире), свободных мест не «ноль», а
            // НЕИЗВЕСТНО: ноль в окне читался как «сумка забита под завязку»
            местСвободно = self.CarrySlots().Any() ? self.FreeCarrySlots() : (int?)null,
            занят = bot.Context.Turn.Busy ?? "",
            навык = bot.Skills.CurrentSkill ?? "",
            дело,
            время = bot.Clock.ToString(),
            буря = bot.Storms.Known
                ? bot.Storms.Active ? $"идёт ({bot.Storms.Strength})"
                                    : $"через {bot.Storms.DaysUntilStorm:0.#} сут"
                : "неизвестно",
            // ТЕМПОРАЛЬНАЯ СТАБИЛЬНОСТЬ — тем же одним ответом, что уходит в
            // чат и в журнал (StabilityRules.Say): три описания одного числа
            // разошлись бы в первый же день
            стабильность = bot.Stability.Say(),
            // ЕЁ ЖЕ ЧИСЛОМ — заказчик просил «стабильность в процентах».
            // Проценты честные: сервер держит её в долях и сам зажимает в
            // [0; 1] (EntityBehaviorTemporalStabilityAffected: OwnStability =
            // GameMath.Clamp(OwnStability + …, 0, 1)), так что 0,34 — это
            // ровно 34 %. Строка выше остаётся: она говорит, что это ЗНАЧИТ.
            // null — сервер числа не присылал (в мире без временной
            // стабильности игра не вешает игроку и самого поведения)
            стабильностьДоля = bot.Stability.Own,
            // ГДЕ У ЭТОГО ЧИСЛА ОПАСНЫЕ КРАЯ — чтобы окно красило полоску не
            // по своей догадке. Все три порога из сборок игры и уже лежат
            // одним местом (StabilityRules): ниже 0,13 сервер бьёт временным
            // уроном, ниже 0,2 у живого игрока «глючит» экран, ниже 0,3 мир
            // затягивает ржавым туманом
            стабильностьПороги = new
            {
                бьёт = StabilityRules.HurtsBelow,
                глючит = StabilityRules.GlitchBelow,
                туман = StabilityRules.FogBelow
            },
            // Разломы показываем ТОЛЬКО вредящие: видно их бывает с двухсот
            // блоков, а тянет стабильность лишь тот, что в трёх блоках от тела
            разломРядом = bot.Self.Position is { } же &&
                          bot.Stability.NearestHarmful(же.X, же.Y, же.Z) is { } близко
                ? $"{близко.Distance:0.#} бл"
                : "",
            // Не в игре инвентарь пуст не потому, что всё вышло, а потому, что
            // его ещё не присылали: сводка «нет ничего» там была бы выдумкой
            // ЗАПАСЫ — РАЗОБРАННЫМИ, А НЕ ГОТОВОЙ СТРОКОЙ. Строка тут была одна
            // («torch: 0/16 (не хватает 16)»), и в ней не разобрать ни вещи, ни
            // чисел: значок поставить не к чему, а окно не может даже покрасить
            // недостающее. Заказ 16.08 — «везде где нужно теперь мы можем
            // использовать игровые иконки» — на этой строке и спотыкался.
            //
            // Сама фраза никуда не делась и по-прежнему собирается ЗАПАСАМИ
            // (StockNeed.ToString): та же, что уходит в журнал и в чат. Второго
            // описания одной нужды панель не сочиняет
            запасы = bot.Joined && bot.Stock.Wants.Count > 0
                ? bot.Stock.Check().Select(н =>
                {
                    var значок = Значок(н.Code);
                    return new
                    {
                        код = н.Code,
                        имя = GameNames.Name(н.Code) ?? "",
                        надо = н.Want,
                        есть = н.Have,
                        неХватает = н.Missing,
                        строка = н.ToString(),
                        картинка = значок.Has,
                        класс = значок.Kind
                    };
                }).ToArray()
                : [],
            склад = bot.Depot.Known
                ? bot.Depot.Chests.Select(c => bot.PlayerCoords(c.X, c.Y, c.Z)).ToArray()
                : []
        }, Json);
    }

    /// <summary>
    /// КАКОЙ КУСОК КОЛЬЦА ОТДАТЬ ПО ЗАКЛАДКЕ БРАУЗЕРА — чистое правило, без
    /// времени и мира, поэтому проверяется стендом (правило 7 проекта).
    ///
    /// ЗАКЛАДКА — ЭТО НОМЕР СТРОКИ ОТ НАЧАЛА ЗАПУСКА, А НЕ МЕСТО В СПИСКЕ.
    /// Разбор — в <see cref="saidLines"/>: место в списке пережить обрезку
    /// кольца не может, и окно от этого замолкало на двадцать минут.
    ///
    /// ПРО ПРОПУСК ГОВОРИМ ЧИСЛОМ, А НЕ МОЛЧИМ. Браузер, отставший больше чем
    /// на кольцо, часть строк уже не получит никогда — этих строк в памяти
    /// нет. Молча склеить края значит соврать: человек прочтёт две соседние
    /// строки с разницей в двадцать минут и решит, что бот стоял. Поэтому
    /// пропуск возвращается числом и печатается в окне отдельной строкой.
    /// </summary>
    /// <param name="since">Закладка браузера: сколько строк он уже прочёл.</param>
    /// <param name="firstLine">Номер самой старой строки, лежащей в кольце.</param>
    /// <param name="have">Сколько строк лежит в кольце сейчас.</param>
    /// <param name="max">Сколько строк отдавать за один ответ.</param>
    /// <returns>
    /// Откуда и сколько брать из кольца, сколько строк потеряно безвозвратно и
    /// какой закладка станет после этого ответа.
    /// </returns>
    public static (int From, int Take, long Missed, long Next) LogSlice(
        long since, long firstLine, int have, int max)
    {
        have = Math.Max(0, have);
        max = Math.Max(1, max);
        long last = firstLine + have;
        // Закладка ВПЕРЕДИ кольца — так бывает у вкладки, открытой до
        // перезапуска бота: счёт начался заново, а браузер помнит старый.
        // Отдаём хвост кольца целиком, а не пустоту: пустота — это и есть
        // то самое молчание, которое мы чиним
        if (since > last)
            since = firstLine;
        long missed = since < firstLine ? firstLine - since : 0;
        int from = (int)Math.Clamp(since - firstLine, 0, have);
        int take = Math.Min(max, have - from);
        return (from, take, missed, firstLine + from + take);
    }

    private string LogTail(HttpRequest r)
    {
        long since = long.TryParse(r.Q("since"), out long n) ? Math.Max(0, n) : 0;
        lock (logLock)
        {
            var (from, take, missed, next) = LogSlice(since, firstLine, log.Count, LogLines);
            var строки = log.GetRange(from, take);
            if (missed > 0)
                строки.Insert(0, $"{DateTime.Now:HH:mm:ss} [окно] пропущено {missed} строк: " +
                                 $"окно держит {LogLines * 2} последних, а прочесть их не успели — " +
                                 "они есть в файле журнала целиком");
            return JsonSerializer.Serialize(new
            {
                всего = saidLines,
                прочтено = next,
                пропущено = missed,
                // РАЗМЕТКА ДЕЛАЕТСЯ ЗДЕСЬ, А НЕ В БРАУЗЕРЕ. Правило «что в
                // строке главное» — чистая функция, и её видит стенд; в
                // странице оно было бы тем кодом, который проверить нечем.
                // Строки уже экранированы и вставляются как HTML (см.
                // обновитьЖурнал в panel.html); ФАЙЛ журнала при этом остаётся
                // обычным текстом — размечен только показ
                строки = строки.Select(PanelLogWords.Html).ToArray()
            }, Json);
        }
    }

    private string Commands() => JsonSerializer.Serialize(
        bot.Commands.All.Select(c => new { имя = c.Name, что = c.Description }), Json);

    private string Skills() => JsonSerializer.Serialize(new
    {
        сейчас = bot.Skills.CurrentSkill ?? "",
        список = bot.Skills.Registered.Select(s => new { имя = s.Name, что = s.Description })
    }, Json);

    private string ToolList() => JsonSerializer.Serialize(
        (Tools ?? []).Select(t => new
        {
            имя = t.Name,
            что = t.Description,
            схема = JsonDocument.Parse(t.Schema).RootElement
        }), Json);

    /// <summary>
    /// Настройки роли ВМЕСТЕ С ОБЪЯСНЕНИЯМИ.
    ///
    /// ЖИВАЯ ЖАЛОБА, ради которой это здесь: «не юзерфрендли и нефига не
    /// понятно, что делают некоторые». Панель показывала голый список «имя =
    /// значение», а имена вроде «ОбходитьПередКопанием» или «ДержатьсяОтЧужого»
    /// человеку не говорят ничего.
    ///
    /// Объяснения ВЫДУМЫВАТЬ НЕЛЬЗЯ: соврать про настройку хуже, чем не
    /// подписать её. Поэтому текст берётся из ЕЁ ЖЕ док-строки в роли
    /// (<see cref="XmlDocs"/>), а нет файла документации — панель говорит об
    /// этом вслух и показывает голое имя, как раньше.
    /// </summary>
    private string RoleState()
    {
        if (bot.Role is not { } role)
            return JsonSerializer.Serialize(new { роль = "", ручки = Array.Empty<object>() }, Json);
        return RoleFaceJson(role, Config?.Preset ?? "");
    }

    /// <summary>
    /// ИМЯ РОЛИ В КАТАЛОГЕ по самой роли. Каталог зовёт роли короткими именами
    /// («guard»), а живая роль знает только своё название («Стражник»); связь
    /// между ними — совпадение <c>RoleEntry.Title</c> и <c>BotRole.Name</c>, и
    /// это давнее правило каталога, а не догадка (см. Roles.ТолькоНаши).
    ///
    /// Пусто — роли в каталоге нет (её создали руками, каталог к окну не
    /// подключён). Тогда «своё у роли» не считается вовсе, и окно об этом
    /// скажет: сравнивать не с чем.
    /// </summary>
    private string RoleIdOf(BotRole role) =>
        Roles?.All.FirstOrDefault(e =>
            string.Equals(e.Title, role.Name, StringComparison.Ordinal))?.Id ?? "";

    /// <summary>
    /// ВСЕ НАСТРОЙКИ ОДНОЙ РОЛИ так, как их рисует окно: разделы, подписи,
    /// заводские значения, «изменена», из чего выбирать.
    ///
    /// РОЛЬ ПРИХОДИТ ДОВОДОМ, А НЕ БЕРЁТСЯ У БОТА, И ЭТО НЕ ИЗЯЩЕСТВО. Тем же
    /// ответом живёт КОНСТРУКТОР РОЛИ: человек собирает бота, которым сейчас
    /// никто не бегает (<see cref="BuilderState"/>). Спроси конструктор свои
    /// настройки вторым способом — окно рисовало бы собранную роль иначе, чем
    /// живую: другие разделы, другой порядок, другое «заводское». Разойтись
    /// этим двум нельзя, поэтому способ один.
    /// </summary>
    /// <param name="role">Роль: живая у бота или свежесозданная для сборки.</param>
    /// <param name="preset">В какой пресет ложатся её ручки (для показа).</param>
    /// <param name="roleId">
    /// Имя роли В КАТАЛОГЕ. Пусто — узнаём по названию (<see cref="RoleIdOf"/>).
    /// Конструктор знает его точно и говорит прямо: там роль берут ИЗ каталога.
    /// </param>
    private string RoleFaceJson(BotRole role, string preset, string roleId = "")
    {
        // ПОДПИСИ ВЫКЛЮЧЕНЫ — НЕ ЧИТАЕМ ФАЙЛ ВОВСЕ. Спросить XmlDocs хоть раз
        // значит поднять в память все 2,6 МБ подписей: экономия, которая
        // случается уже после траты, — не экономия
        var беды = Explanations
            ? XmlDocs.Problems(role.GetType())
            : ["подписи к настройкам выключены (серверный режим, экономия 2,6 МБ) — " +
               "вернуть их можно в разделе «Память»"];
        var заводские = RoleDefaults.Of(role.GetType());
        var главные = KnobHelp.DeclaredMain(role);
        var ручки = RoleKnobs.Of(role);

        // ДОНОСИТ ЛИ ЭТА РОЛЬ ПОВЁРНУТОЕ ДО МЕХАНИЗМА — считается ОДИН раз на
        // всю роль, а не на каждую ручку: это свойство роли, а не настройки
        bool доноситЖивьём = PanelWhenApplies.CarriesKnobsLive(role.GetType());

        // ЧТО У ЭТОЙ РОЛИ СВОЁ — считает КАТАЛОГ, сравнением со всеми
        // остальными ролями (RoleCatalog.OnlyHere), а не догадкой по имени
        // класса, где ручка объявлена. Роль, собранная на основе копателя,
        // объявит его настройки не у себя — а человеку они всё равно
        // копательские.
        //
        // РАДИ ЧЕГО ЭТО ЗДЕСЬ. Заказчик: «я думаю проще отдельная вкладка
        // настройка роли, что мы туда вписали кастомного, то отдельно и
        // настраивается». Вкладке нужен ПРИЗНАК У КАЖДОЙ РУЧКИ, а не отдельный
        // список: делить список на странице значило бы завести второе правило
        // «что считать своим» и однажды разойтись с каталогом.
        string имяВКаталоге = roleId.Length > 0 ? roleId : RoleIdOf(role);
        var своиИмена = new HashSet<string>(
            имяВКаталоге.Length > 0
                ? Roles?.Faces().FirstOrDefault(л => string.Equals(л.Id, имяВКаталоге,
                      StringComparison.OrdinalIgnoreCase))?.Own ?? []
                : [],
            StringComparer.OrdinalIgnoreCase);

        return JsonSerializer.Serialize(new
        {
            роль = role.Name,
            имяРоли = имяВКаталоге,
            пресет = preset,
            // ПОЧЕМУ «СВОЕГО» МОЖЕТ НЕ БЫТЬ — словами, а не пустой вкладкой.
            // Пусто у роли и «не с чем сравнивать» — РАЗНОЕ, и человек, у
            // которого каталог к окну не подключён, не должен читать это как
            // «у роли нет своих настроек»
            своеСчитано = имяВКаталоге.Length > 0 && Roles != null,
            почемуНеСчитано = Roles == null
                ? "каталог ролей к окну не подключён — сравнить эту роль не с чем"
                : имяВКаталоге.Length == 0
                    ? $"роли «{role.Name}» нет в каталоге (её создали помимо него) — " +
                      "сравнить её не с чем"
                    : "",
            // Почему у настроек нет пояснений — СЛОВАМИ. Молчаливый голый
            // список человек читает как «панель недоделана», а он лечится
            // одной строкой в файле проекта роли
            пояснения = new
            {
                есть = Explanations && XmlDocs.AnyFor(role.GetType()),
                // Каждая сборка родословной СВОЕЙ строкой: у копателя часть
                // ручек своя, а часть досталась от LivingRole, и лечатся они
                // разными файлами проектов
                почему = string.Join(" ", беды)
            },
            заводскиеИзвестны = заводские != null,
            // ДОНОСИТ ЛИ РОЛЬ ПОВЁРНУТОЕ ДО МЕХАНИЗМА. Свойство всей роли, и
            // окно говорит о нём одной строкой на вкладке, а не двадцатью
            // бирками на каждом поле
            доноситРучкиЖивьём = доноситЖивьём,
            разделы = KnobHelp.SectionsFor(role)
                .Select(р => new { имя = р.Id, название = р.Title, что = р.About }),
            ручки = ручки.Select((k, номер) =>
            {
                string текст = Explanations
                    ? KnobHelp.Clean(XmlDocs.SummaryOf(role.GetType(), k.Name))
                    : "";
                object? заводское = заводские != null && заводские.TryGetValue(k.Name, out var d)
                    ? d
                    : null;
                bool знаемЗаводское = заводские?.ContainsKey(k.Name) == true;
                bool изменена = знаемЗаводское && !RoleDefaults.Same(k.Value, заводское);
                // Место ручки в окне говорит ОНА САМА (метка рядом с ней) или
                // роль (список ГлавныеНастройки); догадка по словам — последняя
                // мера, и панель не скрывает, что это догадка
                var место = KnobHelp.PlaceOf(role.GetType(), k, текст, главные, номер, изменена);
                // КОГДА ЭТА РУЧКА ПОДЕЙСТВУЕТ — у КАЖДОЙ и своим ответом.
                // Прежде окно на любую отвечало «часть настроек подействует
                // после перезапуска», ни разу не называя какая; человек читал
                // это как «ни одна не подействовала» и перезапускал бота после
                // каждой правки
                var когда = PanelWhenApplies.Knob(k.Name, role.Name, доноситЖивьём,
                    KnobHelp.MarkOf(role.GetType(), k.Name)?.AtStartOnly);
                return new
                {
                    имя = k.Name,
                    подпись = KnobHelp.Words(k.Name),
                    тип = k.Kind,
                    значение = k.Value,
                    // Три числа в окне — это либо (258, 111, −260), либо
                    // (512258, 111, 511740), и человеку надо СКАЗАТЬ, какие из
                    // них ждут: на этой самой путанице заказчик потерял склад
                    // «за полмиллиона блоков». Вид ручки («клетка») у обоих один,
                    // различает их только тип свойства — потому и спрашиваем тип
                    координаты = k.Kind == WorkFieldKinds.Cell
                        ? PanelSettings.CoordsOf(KnobType(role, k.Name))
                        : "",
                    // ИЗ ЧЕГО ВЫБИРАТЬ. Пусто — обычное поле. Пока этого списка
                    // не было, «БезДела» приходилось набирать вслепую, и жалоба
                    // заказчика «настройку вроде включил» была именно про это:
                    // включать было нечего, а промахнувшееся слово Enum.Parse
                    // отвергал (см. RoleKnobs.ChoicesOf)
                    значения = RoleKnobs.ChoicesOf(KnobType(role, k.Name)),
                    раздел = место.Section,
                    порядок = место.Order,
                    ктоРасставил = место.Source,
                    что = текст,
                    коротко = KnobHelp.Short(текст),
                    // Что будет на краю значений — ЕЁ ЖЕ словами. «Ноль — не
                    // требовать вовсе» человек читает, стоя над полем, а не
                    // за кнопкой «подробнее»
                    край = KnobHelp.EdgeBesides(KnobHelp.Short(текст), KnobHelp.EdgeOf(текст)),
                    единица = KnobHelp.UnitOf(k.Name, текст, k.Kind),
                    заводское,
                    заводскоеЗнаем = знаемЗаводское,
                    изменена,
                    главная = место.Main,
                    // Код, а не готовая фраза: фразу окно составляет само и
                    // переводит вместе со всей обстановкой
                    когда = PanelWhenApplies.Code(когда.When),
                    // Причина нужна только исключению; у обычной ручки её нет,
                    // и пустая строка честнее, чем «подействует сразу» под
                    // каждым полем
                    почемуЗапуск = когда.When == WhenApplies.Now ? "" : когда.Why,
                    // СВОЯ ЛИ ЭТА НАСТРОЙКА У РОЛИ — то есть нет ли её ни у
                    // одной другой роли каталога (RoleCatalog.OnlyHere). Это
                    // ответ про РОДСТВО, и он идёт наружу отдельно: по нему
                    // список ролей показывает, чем роли отличаются
                    своя = своиИмена.Contains(k.Name),
                    // А ВОТ ПО ЭТОМУ ПРИЗНАКУ ОКНО ДЕЛИТ ДВЕ ВКЛАДКИ:
                    // «Настройка роли» и «Общие настройки». Он ШИРЕ «своей»:
                    // ручка попадает на вкладку роли либо потому, что её нет у
                    // соседей, либо потому, что ОНА САМА так сказала меткой
                    // (KnobPlaceAttribute.RoleTab).
                    //
                    // РАДИ ЧЕГО РАЗВЕДЕНО НАДВОЕ. Заказчик просил дословно:
                    // «сохранение склада и дома давай на одной странице
                    // настроек — в настройки роли». «Дом» и «Склад» есть у
                    // ВСЕХ ролей, и своими они не станут никогда — а вкладку
                    // он назвал вслух. Слепи мы два ответа в один — список
                    // ролей начал бы врать («у стражника своя настройка
                    // „Дом“»), а вкладка осталась бы без двух точек, за
                    // которыми в неё и приходят.
                    //
                    // СКЛАДЫВАЕТСЯ ЗДЕСЬ, И ТОЛЬКО ЗДЕСЬ: страница читает
                    // готовое поле. Своё правило «что показывать на вкладке
                    // роли» она держала (раздел «ии») — и однажды разошлось бы
                    // с этим; теперь его там нет
                    наВкладкеРоли = место.RoleTab || своиИмена.Contains(k.Name)
                };
            })
        }, Json);
    }

    /// <summary>
    /// Тип свойства-ручки. Нужен ровно затем, чтобы отличить игровую клетку от
    /// мировой: <see cref="RoleKnob"/> этого не несёт, а вид у обеих «клетка».
    /// </summary>
    // ТИП РУЧКИ СПРАШИВАЕТСЯ У RoleKnobs, А НЕ ЗДЕСЬ. Своя копия отражения
    // жила тут до 28.08, и рядом с ней завелась вторая — в памяти мест, где
    // нужен тот же ответ («игровые» против «мировых»). Две копии одного вопроса
    // расходятся молча, а ценой расхождения будет точка за полмиллиона блоков
    private static Type? KnobType(BotRole role, string name) => RoleKnobs.TypeOf(role, name);

    /// <summary>
    /// СПИСОК РОЛЕЙ И ГОТОВЫХ БОТОВ — и рядом с каждой ролью то, ЧЕМ ОНА
    /// ОТЛИЧАЕТСЯ ОТ ОСТАЛЬНЫХ.
    ///
    /// ЖИВЫЕ СЛОВА ЗАКАЗЧИКА, ради которых сюда добавлены три поля: «Не
    /// понимаю как выбор роли на что-то влияет… у продавца тоже будут свои, а
    /// сейчас как-то все не так». Разница между ролями была настоящей, но
    /// увидеть её можно было ровно одним способом — перезапустить бота другой
    /// ролью и сравнить два окна по памяти. В списке стояли три строки
    /// описания и ни одной приметы.
    ///
    /// Числа и имена считает КАТАЛОГ (<see cref="RoleCatalog.Faces"/>), а не
    /// окно: «что у роли своё» — это свойство набора ролей, и второй такой
    /// счёт в панели однажды разошёлся бы с первым.
    /// </summary>
    private string PresetList() => JsonSerializer.Serialize(new
    {
        роли = (Roles?.Faces() ?? []).Select(л =>
        {
            var e = Roles!.Find(л.Id)!;
            return new
            {
                имя = e.Id,
                название = e.Title,
                что = e.About,
                нужно = e.Needs,
                // «Своя роль из файла» и «наша роль» ведут себя одинаково ровно
                // до первой беды: обновление заменит наши файлы и не тронет
                // чужой. Человек должен видеть, чей это код
                откуда = e.Source,
                настроек = л.Knobs.Count,
                своих = л.Own.Count,
                // Имена своих настроек — не украшение: именно они отвечают на
                // «чем эта роль отличается». Длинный список окно ужмёт само
                свои = л.Own,
                почему = л.Why
            };
        }),
        // ЧТО СЛУЧИЛОСЬ, ПОКА СОБИРАЛСЯ КАТАЛОГ: взятые свои роли, отвергнутые
        // файлы, занятые имена. Молча пропущенная роль — это бот, который
        // поднялся не тем, кем его просили
        заметки = Roles?.Notes ?? [],
        готовые = Presets.All().Select(p => new
        {
            имя = p.Id, название = p.Title, что = p.About, роль = p.Role, нужно = p.Needs,
            // Пресет называет роль ИМЕНЕМ. Роли с таким именем может и не
            // быть (файл от чужой сборки, своя роль не положена рядом) — тогда
            // бот с ним не поднимется, и сказать это надо ДО выбора, а не при
            // следующем запуске
            рольЕсть = Roles?.Has(p.Role) ?? true,
            // КОГДА ПОДЕЙСТВУЕТ — РЕШАЕТ БОТ, А НЕ СТРАНИЦА. Страница считала
            // это сама (сравнивала имена в JS) — то есть вторым экземпляром
            // правила PanelWhenApplies.PresetKind, и уже разошлась с ним: тут
            // есть Trim («файл правят руками, пробел не делает пресет чужим»),
            // а в JS его не было. Пресет с «"role": "survivor "» получал в окне
            // красную бирку «только при запуске», а бот отвечал «перезапуск не
            // нужен» — окно и бот говорили разное про одно нажатие
            когда = PanelWhenApplies.PresetKind(
                        bot.Role is { } живая ? RoleIdOf(живая) : "", p.Role) switch
            {
                PresetSwap.SameRole => PanelWhenApplies.КодСразу,
                PresetSwap.OtherRole => PanelWhenApplies.КодСмена,
                _ => ""
            }
        })
    }, Json);

    // ---------------- конструктор роли ----------------

    /// <summary>
    /// КОНСТРУКТОР РОЛИ: настройки роли, которой сейчас никто не бегает.
    ///
    /// ЖИВАЯ ПРОСЬБА ЗАКАЗЧИКА: «нужен конструктор ролей прямо в вебформе с
    /// инструкцией как нам кастомизировать… нужно сделать базовый конструктор
    /// поведения из того что есть в вебформе». До этого настроить можно было
    /// РОВНО ОДНУ роль — ту, которой бот бежит прямо сейчас: окно спрашивало
    /// настройки у <c>bot.Role</c>. Чтобы собрать продавца, сидя за копателем,
    /// приходилось перезапускать бота продавцом, накрутить и перезапустить
    /// обратно — то есть остановить работу ради настройки будущей работы.
    ///
    /// Роль создаётся СВЕЖАЯ и живёт ровно один запрос: она ничего не знает о
    /// боте, в мир не входит и в журнал не пишет. Настройки берутся из
    /// названного пресета, если он назван, — так правят уже собранного бота, а
    /// не начинают каждый раз с заводского.
    ///
    /// ЧЕРНОВИК ЗДЕСЬ НЕ ХРАНИТСЯ НАРОЧНО. Половина собранной роли, забытая в
    /// памяти бота, — это второе место, где живут настройки, и оно разошлось бы
    /// с файлом пресета в первый же вечер. Собранное лежит в окне у человека и
    /// уходит боту ОДНИМ куском, когда он нажмёт «Сохранить»
    /// (<see cref="BuilderSave"/>).
    /// </summary>
    private string BuilderState(HttpRequest r)
    {
        if (Roles is not { } каталог)
            return JsonSerializer.Serialize(new
            {
                есть = false,
                почему = "каталог ролей к окну не подключён — собирать не из чего",
                роль = "",
                ручки = Array.Empty<object>()
            }, Json);

        string presetId = (r.Q("пресет") ?? "").Trim();
        var пресет = presetId.Length > 0 ? Presets.Find(presetId) : null;
        if (presetId.Length > 0 && пресет == null)
            return JsonSerializer.Serialize(new
            {
                есть = false,
                почему = $"готового бота «{presetId}» нет",
                роль = "",
                ручки = Array.Empty<object>()
            }, Json);

        string roleId = (r.Q("роль") ?? "").Trim();
        if (roleId.Length == 0)
            roleId = пресет?.Role ?? "";
        if (каталог.Find(roleId) is not { } запись)
            return JsonSerializer.Serialize(new
            {
                есть = false,
                почему = roleId.Length == 0
                    ? $"не сказано, из какой роли собирать. Есть такие: {каталог.Names()}"
                    : $"роли «{roleId}» нет. Есть такие: {каталог.Names()}",
                роль = "",
                ручки = Array.Empty<object>()
            }, Json);

        BotRole роль;
        try
        {
            роль = запись.Create();
        }
        catch (Exception e)
        {
            // Роль не создалась — это правда о роли, а не пустой список ручек:
            // молчаливая пустота читается как «у роли нет настроек»
            return JsonSerializer.Serialize(new
            {
                есть = false,
                почему = $"роль «{запись.Title}» не создалась: {e.Message}",
                роль = запись.Title,
                ручки = Array.Empty<object>()
            }, Json);
        }

        var жалобы = new List<string>();
        if (пресет?.Settings is { } настройки && пресет.Role.Length > 0)
        {
            // ПРЕСЕТ ЧУЖОЙ РОЛИ НЕ ПРИМЕНЯЕМ. Настройки продавца, вкрученные в
            // копателя, дали бы десяток жалоб «у роли нет настройки» и один
            // молча совпавший ключ — то есть наполовину чужого бота
            if (!string.Equals(пресет.Role, запись.Id, StringComparison.OrdinalIgnoreCase))
                жалобы.Add($"готовый бот «{пресет.Id}» собран для роли «{пресет.Role}», " +
                           $"а собираем «{запись.Id}» — его настройки не брал: " +
                           "они про другую роль");
            else
                RoleKnobs.ApplyAll(роль, настройки, out жалобы);
        }

        // Собранная роль показывается ТЕМ ЖЕ ответом, что и живая: разделы,
        // подписи, «заводское», списки выбора, «своё у роли» — всё одно и то
        // же. Имя в каталоге здесь известно ТОЧНО (роль взята из каталога), и
        // угадывать его по названию незачем
        string лицо = RoleFaceJson(роль, пресет?.Id ?? "", запись.Id);
        using var разобрано = JsonDocument.Parse(лицо);
        var поля = разобрано.RootElement.EnumerateObject()
            .ToDictionary(p => p.Name, p => (object?)p.Value.Clone());
        поля["есть"] = true;
        поля["почему"] = "";
        поля["изРоли"] = запись.Id;
        поля["изПресета"] = пресет?.Id ?? "";
        поля["жалобы"] = жалобы;
        return JsonSerializer.Serialize(поля, Json);
    }

    /// <summary>
    /// СОБРАННОЕ В ОКНЕ — В ФАЙЛ ГОТОВОГО БОТА. Одна дверь и один кусок: имя,
    /// название, роль и ВСЕ настройки разом.
    ///
    /// Почему одним куском, а не по ручке за раз, как на вкладке роли: там
    /// крутится ЖИВОЙ бот, и каждая ручка обязана доехать до него сейчас же.
    /// Здесь бота нет вовсе — есть черновик в браузере, и «сохранил половину»
    /// было бы худшим из исходов: файл готового бота с половиной настроек
    /// поднимет при следующем запуске не того, кого собирали.
    ///
    /// ЖАЛОБЫ НЕ ОТМЕНЯЮТ ФАЙЛ, но и не молчат: из-за одной чужой строки
    /// терять остальные девять глупо, а промолчать — значит выпустить бота,
    /// который работает не так, как написано в окне.
    /// </summary>
    private HttpAnswer BuilderSave(HttpRequest r)
    {
        if (Roles is not { } каталог)
            return HttpAnswer.Json(Fail("каталог ролей к окну не подключён — собирать не из чего"));

        var body = Body(r);
        string id = (Field(body, "id") ?? "").Trim();
        if (id.Length == 0)
            return HttpAnswer.Json(Fail("у готового бота должно быть имя"));

        string roleId = (Field(body, "role") ?? "").Trim();
        if (каталог.Find(roleId) is not { } запись)
            return HttpAnswer.Json(Fail(
                $"роли «{roleId}» нет. Есть такие: {каталог.Names()}"));

        BotRole роль;
        try
        {
            роль = запись.Create();
        }
        catch (Exception e)
        {
            return HttpAnswer.Json(Fail($"роль «{запись.Title}» не создалась: {e.Message}"));
        }

        var жалобы = new List<string>();
        if (body.ValueKind == JsonValueKind.Object &&
            body.TryGetProperty("settings", out var настройки) &&
            настройки.ValueKind == JsonValueKind.Object)
        {
            // ПОЛОВИНА ТОЧКИ — НЕ ТОЧКА, и здесь тоже: окно шлёт клетку тремя
            // числами, а недозаполненная ось стала бы нулём и увела бы бота
            foreach (var поле in настройки.EnumerateObject())
            {
                if (RoleKnobs.Of(роль).FirstOrDefault(k =>
                        string.Equals(k.Name, поле.Name, StringComparison.OrdinalIgnoreCase))
                        is { Kind: WorkFieldKinds.Cell } &&
                    PanelSettings.WhyCellBad(поле.Value) is { } плохаяКлетка)
                {
                    жалобы.Add($"настройка «{поле.Name}»: {плохаяКлетка}");
                    continue;
                }
                if (RoleKnobs.Apply(роль, поле.Name, поле.Value) is { } жалоба)
                    жалобы.Add(жалоба);
            }
        }

        var пресет = PresetLibrary.Capture(id, запись.Id, роль,
            Field(body, "title"), Field(body, "about"));
        // «Что подготовить» человек пишет своими словами; не написал — берём
        // то, что роль требует сама. Выдумывать за неё нечего
        пресет.Needs = (Field(body, "needs") ?? "")
            .Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            is { Length: > 0 } свои ? свои : запись.Needs;
        Presets.Save(пресет);
        OnLog?.Invoke($"собран готовый бот «{пресет.Id}» на роли «{запись.Id}»" +
                      (жалобы.Count > 0 ? $", отвергнуто настроек {жалобы.Count}" : ""));

        // ЧТО БУДЕТ ДАЛЬШЕ — ПО ПРАВДЕ И ДВУМЯ ВЕТКАМИ. Прежде здесь стояло
        // «перезапустите бота» на оба случая; теперь пресет ТОЙ ЖЕ роли, что у
        // живого бота, применяется сейчас же (см. ApplyPreset), и обещать
        // перезапуск там, где он не нужен, значило бы врать
        string какПрименится = bot.Role is { } живая &&
            PanelWhenApplies.PresetKind(RoleIdOf(живая), запись.Id) == PresetSwap.SameRole
            ? $"Роль у него та же, что у бота сейчас («{запись.Id}»), — выберите его на вкладке " +
              "«Готовые боты», и он подействует сразу, без перезапуска"
            : "Роль меняется только при запуске — выберите его на вкладке «Готовые боты» " +
              "и перезапустите бота";

        return HttpAnswer.Json(Answer(true,
            $"готовый бот «{пресет.Id}» собран: {пресет.SourcePath}. {какПрименится}",
            жалобы));
    }

    /// <summary>
    /// Настройки БЕЗ СЕКРЕТОВ. Токен, пароль сервера и ключ сессии наружу не
    /// уходят никогда: панель показывает только «задан или нет». Иначе
    /// открытая в браузере страница становится местом, где лежит доступ.
    /// </summary>
    private string Settings() => JsonSerializer.Serialize(
        PanelSettings.Public(Config, bot.Name, GameFolders.Describe(), JobsStore?.Path), Json);

    /// <summary>
    /// Каким видом рисовать инвентарь: полосой хотбара, сеткой рюкзака, блоком
    /// одежды или отдельной стопкой на курсоре.
    ///
    /// ЗАЧЕМ ОТДЕЛЬНОЕ СЛОВО. Заказчик просил показывать инвентарь «таким как
    /// в игре», а в игре у каждого инвентаря СВОЙ вид, и вёрстке надо знать
    /// какой. Русское название рядом остаётся тем, что сказал бот, — по нему
    /// вёрстка не решает ничего: перевод окна на английский тогда сломал бы
    /// раскладку.
    ///
    /// Различаем инвентари НЕ вторым разбором id, а спрашивая тот же механизм,
    /// который уже это умеет (<see cref="Bags.Title"/>). Два разбора одного и
    /// того же однажды разойдутся — и рюкзак нарисуется полосой хотбара.
    /// Неизвестный вид — не беда: вёрстка нарисует его простой сеткой,
    /// а тест на четыре знакомых вида скажет, если у механизма поменялись слова.
    /// </summary>
    private static string InventoryKind(string inventoryId) => Bags.Title(inventoryId) switch
    {
        "хотбар" => "hotbar",
        "рюкзак" => "backpack",
        "одежда и броня" => "character",
        "на курсоре" => "mouse",
        _ => "other"
    };

    /// <summary>
    /// ЦИФРЫ НА МЕСТАХ ХОТБАРА: 1..9 и 0 на десятом. Не выдуманы — спрошены у
    /// игры: <c>HotkeyManager</c> заводит «hotbarslot1»…«hotbarslot9» на
    /// <c>GlKeys.Number1</c>…<c>Number9</c>, а «hotbarslot10» — на
    /// <c>GlKeys.Number0</c>; их-то <c>HudHotbar.drawIcon</c> и рисует в углу
    /// клетки цветом <c>GuiStyle.HotbarNumberTextColor</c> («the color of the
    /// 1..9 numbers on the hotbar slots»).
    ///
    /// Мест с цифрой ровно десять — столько же, сколько до умения
    /// (<see cref="Bags.SkillSlot"/> = 10), и длина этой строки и есть их число:
    /// второго «десять» в коде не заводится.
    ///
    /// ЧЕГО МЫ НЕ ЗНАЕМ И НЕ ОБЕЩАЕМ. Игра рисует не цифру места, а ТЕКУЩУЮ
    /// раскладку клавиши (<c>CurrentMapping</c>): переназначил человек «взять
    /// пятое место» на F5 — в игре нарисуется F5. Чужую раскладку бот не видит
    /// (по сети её не шлют), поэтому здесь стоят заводские цифры, и обещать
    /// «нажми это» окно не вправе — оно и не обещает: подписи «клавиша» нет.
    /// </summary>
    private const string HotbarDigits = "1234567890";

    /// <summary>
    /// Чем подписано место в окне: цифрой хотбара или ничем.
    ///
    /// ЗАЧЕМ. Заказчик сверяет окно с игровым: «хотбар — полоса в десять мест,
    /// номера 1..9 и 0». Без цифры человек считает клетки глазами и на седьмой
    /// сбивается, а «слот 6» из журнала бота вообще не сходится с тем, что он
    /// насчитал: журнал считает с нуля, игра подписывает с единицы. Поэтому в
    /// подсказке клетки остаётся и «место 6» — бот считает по-своему, и врать
    /// ему в подсказку нельзя.
    ///
    /// СЧИТАЕТ БОТ, А НЕ ОКНО. Реши вёрстка сама «первые десять — с цифрами»,
    /// она разошлась бы с ботом на инвентаре другой длины и подписала бы цифрой
    /// умение или левую руку — а их в хотбаре игры нет вовсе: HudHotbar кладёт
    /// в полосу ровно места 0..9, левая рука (11) идёт отдельной клеткой слева,
    /// сумки — отдельной справа. Поэтому у мест с именем
    /// (<see cref="Bags.SlotName"/>) цифры нет, а вид инвентаря спрашивается у
    /// того же <see cref="InventoryKind"/>, что и всё остальное.
    /// </summary>
    private static string HotbarNumber(string inventoryId, int slot) =>
        InventoryKind(inventoryId) == "hotbar"
        && Bags.SlotName(inventoryId, slot) == null
        && slot < HotbarDigits.Length
            ? HotbarDigits[slot].ToString()
            : "";

    private static int InventoryCells(BagSection section)
    {
        int cells = section.Slots;
        foreach (var item in section.Items)
            cells = Math.Max(cells, item.Slot + 1);
        return cells;
    }

    /// <summary>
    /// Что у бота в сумках. Данные, человеческие имена и объяснение про
    /// картинки собирает механизм (<see cref="Bags"/>) — панель только рисует.
    ///
    /// КАРТИНОК НЕТ И НЕ БУДЕТ, и это не недоделка вкладки: у игры нет готовых
    /// изображений предметов вовсе, предмет рисуется объёмной моделью на
    /// видеокарте. Строка «почемуБезКартинок» идёт наружу затем, чтобы человек
    /// видел ПРИЧИНУ, а не гадал.
    ///
    /// ПУСТЫЕ МЕСТА ОТДАЁМ ТОЖЕ («клетки»). Заказчик: «инвентарь в вебформе
    /// сделать таким как в игре». В игровом окне пустая клетка — это тоже
    /// сведение на экране: по ней видно, сколько у бота свободно и куда встанет
    /// следующая стопка. Снимок сумок перечисляет только ЗАНЯТОЕ — для чата
    /// это правильно, но сетку из него не собрать: у пустого места нет ни
    /// номера, ни имени. Имя каждого места спрашиваем у того же механизма
    /// (<see cref="Bags.SlotName"/>), а годность под вещи — у того же, кто
    /// считает свободные места (<see cref="SelfState.IsStorageSlot"/>):
    /// второго списка «слот 11 — это левая рука» здесь не заводится.
    /// </summary>
    private string InventoryState()
    {
        // Опрос из браузера идёт своим потоком, а бот ровно в это время может
        // перекладывать вещи. Уронить из-за этого весь ответ окна нельзя,
        // промолчать — тоже: пустая вкладка читается как «сумки пусты»
        BagReport снимок;
        try
        {
            снимок = Bags.Snapshot(bot.Context);
        }
        catch (Exception e)
        {
            снимок = new BagReport(false,
                $"сумки прямо сейчас меняются, снимок не вышел ({e.Message})", [], 0, 0, "", "");
        }
        return JsonSerializer.Serialize(new
        {
            известно = снимок.Known,
            сообщение = снимок.Message,
            видов = снимок.Kinds,
            штук = снимок.Pieces,
            имена = снимок.NamesFrom,
            почемуБезКартинок = снимок.IconsWhy,
            // КУДА КЛАСТЬ КАРТИНКИ. Живой прогон: «нет текстур в инвентаре, мы
            // же обсуждали». Рецепт у бота был, и он на него честно ссылался —
            // а вот САМОГО ГЛАВНОГО, куда положить выгруженную папку, не
            // говорил нигде. Человек прочёл «картинок нет» и остался с этим
            картинкиКуда = IconsFolderWanted(),
            картинкиСколько = ItemIcons.Look().Files,
            // ПРАВДА ПРО ПРАВУЮ РУКУ — СЛОВАМИ БОТА, один раз на весь ответ.
            // Заказчик: «и в инвентаре у тебя надеть на правую руку, нет такого,
            // в хотбаре выбраный предмет и есть правая рука». Он прав, и
            // проверено это по сборкам игры (см. Hands.RightHandIsHotbar):
            // RightHandItemSlot ВОЗВРАЩАЕТ ActiveHotbarSlot, своего места у
            // правой руки нет. Строку пишет механизм, а не страница: напиши её
            // страница — на английском окне она осталась бы русской, а главное,
            // разошлась бы с тем, что бот делает на самом деле
            проПравуюРуку = Hands.RightHandIsHotbar,
            инвентари = снимок.Sections.Select(s => new
            {
                название = s.Title,
                id = s.InventoryId,
                вид = InventoryKind(s.InventoryId),
                // ГДЕ ЭТОТ РАЗДЕЛ СТОИТ В ОКНЕ — числом БОТА (<see cref="Bags.Order"/>),
                // тем же, которым он уже разложил разделы в снимке. Страница
                // держала свой список имён («hotbar, backpack, character, other,
                // mouse») и сортировала им заново — то есть ОДИН порядок был
                // записан дважды, и две записи уже разошлись: у бота курсор шёл
                // перед «прочим», у страницы — наоборот. А цена ошибки тут не
                // косметическая: пока полоса рук стояла в этом списке последней,
                // фонарь в левой руке уезжал за нижний край окна — ровно
                // жалоба «в инвентаре фонарь не отобразился в левой руке»
                порядок = Bags.Order(s.InventoryId),
                мест = s.Slots,
                свободно = s.Free,
                // СКОЛЬКО КЛЕТОК В РЯД — числом ИГРЫ, а не на глаз. Ноль —
                // у игры своей раскладки нет, окно решает само (см.
                // Bags.Columns). Из-за отсутствия этого числа сетка тянулась
                // «сколько влезет», и четыре сумки с одеждой занимали три
                // экрана пустых клеток — ровно та жалоба, что «в игре всё
                // умещается на одном экране»
                колонок = Bags.Columns(s.InventoryId),
                клетки = Enumerable.Range(0, InventoryCells(s)).Select(i => new
                {
                    место = i,
                    имяМеста = Bags.SlotName(s.InventoryId, i) ?? "",
                    // РОЛЬ МЕСТА МАШИННЫМ СЛОВОМ. По ней вёрстка ставит левую
                    // руку туда, где её рисует игра (отдельной клеткой слева от
                    // полосы), а не в общую кучу «особых мест». Русское имя
                    // рядом остаётся человеку: реши вёрстка по нему — окно на
                    // английском потеряло бы левую руку вместе с фонарём в ней
                    роль = Bags.SlotRole(s.InventoryId, i),
                    // РИСУЕТ ЛИ ЭТУ КЛЕТКУ САМА ИГРА. Заказчик: «и в игре нет
                    // умений, лишнее окно в инвентаре». Проверено по сборкам:
                    // клетки умения в игре нет нигде, но САМО МЕСТО есть и в
                    // ванили в него кладётся умение «timeswitch» — поэтому
                    // пустое не показываем, а занятое обязаны
                    вИгре = Bags.ShownInGame(s.InventoryId, i,
                        s.Items.Any(в => в.Slot == i)),
                    подВещи = SelfState.IsStorageSlot(s.InventoryId, i),
                    номер = HotbarNumber(s.InventoryId, i),
                    // ВЫБРАННОЕ МЕСТО ПОМЕЧАЕМ У САМОЙ КЛЕТКИ, а не только у
                    // вещи. Пустое выбранное место — обычное дело: бот работает
                    // рукой, и Hands так и говорит («нечего применять: активный
                    // слот пуст»). Вещи там нет, помечать было нечего, и окно
                    // рисовало «ничего не выбрано» — то есть врало о том, чем
                    // бот сейчас работает. Какой слот выбран, знает СЕРВЕР
                    // (пакет 53) и держит Hands.ActiveSlot — спрашиваем его же,
                    // тот самый, по которому считается «вРуке» у вещи
                    вРуке = InventoryKind(s.InventoryId) == "hotbar"
                            && i == bot.Hands.ActiveSlot
                }),
                вещи = s.Items.Select(i =>
                {
                    // НАДЕВАЕТСЯ ЛИ ЭТО, РЕШАЕТ НЕ ОКНО. Спрашиваем тот же
                    // механизм, который потом и будет надевать (Hands.WhereWorn
                    // → реестр сервера): реши окно своей формулой — в меню
                    // светилось бы «надеть», а бот отвечал бы «не надевается»
                    var куда = bot.Hands.WhereWorn(i.Code);
                    // В РУКУ — ТОЖЕ НЕ ОКНО РЕШАЕТ. Оба ответа даёт тот самый
                    // механизм, который потом и понесёт вещь: правую руку —
                    // Hands, левую — HandLight (он же кладёт туда фонарь). Так
                    // серый пункт меню и отказ бота говорят одно и то же
                    var вРуку = bot.Hands.WhyToHand(s.InventoryId, i.Slot, i.Code);
                    var вЛевую = bot.Light.WhyOffHand(s.InventoryId, i.Slot, i.Code);
                    // СНЯТЬ — ТОЖЕ НЕ ОКНО РЕШАЕТ. Жалоба заказчика: «в вебформе
                    // инвентаря нельзя снять вручную броню, ток надеть». Ответ
                    // даёт тот же механизм, который потом и снимет
                    // (Hands.WhyTakeOff → Cold.UndressSlotAsync): реши окно
                    // своей формулой — пункт светился бы, а бот отвечал бы «в
                    // сумках нет места»
                    var снять = bot.Hands.WhyTakeOff(s.InventoryId, i.Slot, i.Code);
                    return new
                    {
                        место = i.Slot,
                        имяМеста = i.SlotName ?? "",
                        код = i.Code,
                        имя = i.Name,
                        имяИзвестно = i.NameKnown,
                        штук = i.Count,
                        прочность = i.Durability,
                        прочностьВсего = i.MaxDurability,
                        вРуке = i.InHand,
                        // ЛЕВАЯ РУКА — ОТДЕЛЬНЫМ ОТВЕТОМ. Живая ошибка
                        // заказчика: «в инвентаре фонарь не отобразился в левой
                        // руке». Про руки окно знало ровно одно — какой слот
                        // хотбара выбран, — и бот с фонарём в левой руке
                        // показывался с пустыми руками
                        вЛевойРуке = i.InOffHand,
                        надевается = куда.Can,
                        кудаНадеть = куда.Where,
                        почемуНеНадеть = куда.Why,
                        берётсяВРуку = вРуку.Can,
                        почемуНеВРуку = вРуку.Why,
                        // ПРАВАЯ РУКА — ЭТО ВЫБРАННОЕ МЕСТО ХОТБАРА, и окно
                        // обязано звать вещи своими именами. Заказчик: «в
                        // хотбаре выбраный предмет и есть правая рука». Значит,
                        // «взять в правую руку» — это либо ВЫБРАТЬ это место
                        // (вещь уже под рукой), либо СПЕРВА ПЕРЕЛОЖИТЬ её в
                        // хотбар. Что именно выйдет, знает тот, кто это и
                        // сделает (Hands.InRightHandReach) — окно своей копии
                        // условия не заводит
                        ужеПодРукой = bot.Hands.InRightHandReach(s.InventoryId, i.Slot),
                        берётсяВЛевуюРуку = вЛевую.Can,
                        почемуНеВЛевуюРуку = вЛевую.Why,
                        // НАДЕТО ЛИ ЭТО — ответ бота (BagItem.Worn), а не догадка
                        // окна по русскому названию раздела: на английском окне
                        // такая догадка молча спрятала бы пункт «Снять»
                        надето = i.Worn,
                        снимается = снять.Can,
                        почемуНеСнять = снять.Why,
                        // ЕСТЬ ЛИ КАРТИНКА, решает бот, а не окно: файл лежит
                        // у него, и только он знает, под каким из игровых имён
                        // (block/item, «/» или «-»). Окно, спрашивай оно
                        // картинку вслепую, рисовало бы битые квадратики у
                        // каждой вещи, которую человек ещё не выгрузил
                        // Спрашивается ОДНИМ способом на все вкладки
                        // (BagItem.Icon → ItemIcons.Of): склад, запасы и задачи
                        // берут те же три поля, и вторая пара строк здесь рано
                        // или поздно разошлась бы с ними на один дефис
                        картинка = i.Icon.Has,
                        // Блок это или предмет — тоже ответ бота (по реестрам
                        // сервера): один код бывает и блоком, и предметом
                        // (candle, cheese, egg, ore…), картинки у них разные, и
                        // без этого поля окно показало бы не ту вещь. Названо
                        // как у игры (EnumItemClass), и НЕ «вид» — «вид» уже
                        // занят видом инвентаря выше
                        класс = i.Icon.Kind
                    };
                })
            })
        }, Json);
    }

    /// <summary>
    /// ОПИСЬ СКЛАДА: что и сколько лежит по сундукам и когда бот туда смотрел.
    ///
    /// ЗАКАЗ ЗАКАЗЧИКА, ради которого вкладка есть: «каждое возвращение домой
    /// сканировать все сундуки и записывать, чтобы потом ориентироваться, нужно
    /// домой чтобы что-то взять или нет». Опись ведёт склад
    /// (<see cref="Depot"/>) — панель её только показывает и ничего не считает
    /// сама: реши она «этого дома нет» своей формулой, окно и бот отвечали бы
    /// человеку разное.
    ///
    /// ВРЕМЯ ОСМОТРА ПОКАЗЫВАЕМ ВСЕГДА. Опись — это память, а не нынешнее
    /// положение дел: из сундука могли всё вынести минуту назад. Строка «видов
    /// 12, штук 340» без «смотрел 2 ч назад» была бы обещанием, которого бот
    /// давать не вправе.
    /// </summary>
    private string DepotState()
    {
        var склад = bot.Depot;

        // Опись пишет бот, а читает опрос из браузера. Уронить из-за этого всю
        // вкладку нельзя, промолчать — тоже: пустая вкладка читается как
        // «на складе ничего нет», а это совсем другой ответ
        IReadOnlyList<DepotShelf> опись;
        string беда = "";
        try
        {
            опись = склад.Shelves;
        }
        catch (Exception e)
        {
            опись = [];
            беда = $"опись прямо сейчас меняется, снимок не вышел ({e.Message})";
        }

        var сейчас = DateTime.UtcNow;
        bool поИгровому = bot.CoordsKnown();
        string Где(BlockPos p) => поИгровому
            ? bot.GameOf(p).ToString()
            : $"{p} (мировые: сдвиг спавна ещё не пришёл)";

        return JsonSerializer.Serialize(new
        {
            сводка = беда.Length > 0 ? беда : склад.Inventory(),
            // «Сколько сундуков в складе» и «сколько из них описано» — разные
            // числа, и человеку нужны оба: по их разнице видно, полна ли опись
            точек = склад.Points().Count,
            описано = опись.Count,
            свежесть = склад.ScanFreshMinutes,
            протухает = склад.ScanStaleMinutes,
            осматриватьПриРейсе = склад.ScanOnHaul,
            сундуки = опись.Select(с => new
            {
                где = Где(с.Pos),
                мест = с.Slots,
                свободно = с.FreeSlots,
                видов = с.Kinds,
                штук = с.Pieces,
                когда = с.Seen.ToLocalTime().ToString("HH:mm:ss"),
                давно = Depot.Ago(с.AgeMinutes(сейчас)),
                вещи = с.Items.OrderByDescending(p => p.Value).Select(p =>
                {
                    var значок = Значок(p.Key);
                    return new
                    {
                        код = p.Key,
                        // Имя ищем там же, где его ищет вкладка «Инвентарь»
                        // (ItemIcons): двух списков имён у бота не заводится
                        имя = GameNames.Name(p.Key) ?? "",
                        штук = p.Value,
                        картинка = значок.Has,
                        класс = значок.Kind
                    };
                })
            }),
            // Итог по всему складу: человеку нужен ответ «есть ли у меня дома
            // шестерёнка», а не таблица по сундукам
            всего = опись
                .SelectMany(с => с.Items)
                .GroupBy(p => p.Key, StringComparer.Ordinal)
                .Select(g =>
                {
                    var значок = Значок(g.Key);
                    return new
                    {
                        код = g.Key,
                        имя = GameNames.Name(g.Key) ?? "",
                        штук = g.Sum(p => p.Value),
                        сундуков = g.Count(),
                        картинка = значок.Has,
                        класс = значок.Kind
                    };
                })
                .OrderByDescending(x => x.штук)
        }, Json);
    }

    /// <summary>
    /// КАРТИНКА ВЕЩИ ПО КОДУ — для тех вкладок, где кроме кода ничего нет
    /// (опись склада). Не второй способ, а тот же самый: за ним стоит
    /// <see cref="ItemIcons.Ask(WorldModel, string?)"/>, которым отвечают и
    /// сумки (<see cref="BagItem.Icon"/>), и подсказка вещей.
    ///
    /// ЗАЧЕМ ОТДЕЛЬНАЯ СТРОЧКА ЗДЕСЬ. Заказ 16.08 дословно: «и везде где нужно
    /// теперь мы можем использовать игровые иконки, допустим на складе».
    /// Механизм завела одна волна, вёрстку — соседняя, а шов между ними остался
    /// не сшит: страница уже звала <c>значокВещи(в)</c> у каждой строки описи, а
    /// опись отдавала голый код — и значок молча не появлялся ни у одной вещи.
    /// Собирать «картинка» и «класс» здесь второй парой строк было бы вторым
    /// способом спросить одно и то же: он разошёлся бы с первым на один дефис,
    /// и на складе показалась бы не та вещь, которая там лежит (один код бывает
    /// И блоком, И предметом: candle, cheese, egg, ore, paper…).
    /// </summary>
    private ItemIcon Значок(string код) => ItemIcons.Ask(bot.World, код);

    /// <summary>
    /// СПРОСИТЬ ОПИСЬ: надо ли домой за этим. Отвечает тот же механизм, что
    /// решает это за бота (<see cref="Depot.Ask"/>), — окно не считает ничего
    /// своего, иначе оно обещало бы одно, а бот делал другое.
    /// </summary>
    private HttpAnswer AskDepot(HttpRequest r)
    {
        var body = Body(r);
        string что = (Field(body, "что") ?? "").Trim();
        if (что.Length == 0)
            return HttpAnswer.Json(Fail("не сказано, что искать: впишите часть кода вещи " +
                                        "(«pickaxe», «gear-temporal»)"));
        int надо = int.TryParse(Field(body, "сколько"), out int n) && n > 0 ? n : 1;

        var ответ = bot.Depot.Ask(что, надо);
        // Ответ показываем ВСЕГДА как удачный запрос: «домой не пойду» — это
        // не сбой окна, а разумный ответ, и красным его красить нельзя
        return HttpAnswer.Json(JsonSerializer.Serialize(new
        {
            ok = true,
            message = ответ.Reason,
            идти = ответ.Worth,
            вСумке = ответ.InBag,
            наСкладе = ответ.InDepot
        }, Json));
    }

    /// <summary>
    /// ОБОЙТИ СКЛАД И ПЕРЕПИСАТЬ ЕГО ПРЯМО СЕЙЧАС. Обычно опись обновляется
    /// сама при возвращении домой; кнопка нужна тогда, когда человек только что
    /// разложил вещи руками и хочет, чтобы бот об этом узнал, не дожидаясь рейса.
    /// </summary>
    private async Task<HttpAnswer> ScanDepotAsync()
    {
        if (!bot.Joined)
            return HttpAnswer.Json(Fail("бот не в мире — обходить нечего и некому"));

        // ТЕЛО БЕРЁМ, КАК И ВСЯКИЙ ПРИКАЗ. Обход двигает бота по складу, а тело
        // у него одно: не спроси мы очередь на тело — обход и идущий наряд
        // тянули бы бота в разные стороны. Важность «приказ»: человек нажал
        // кнопку и ждёт ответа, но спасение жизни всё равно важнее
        using var hold = await bot.Context.Turn.TakeAsync("обход склада из окна",
            BodyArbiter.Importance.Command, waitSeconds: 5);
        if (hold == null)
            return HttpAnswer.Json(Fail(
                $"обходить склад некогда: тело занято «{bot.Context.Turn.Busy}» — " +
                "остановите это дело или подождите"));

        try
        {
            var итог = await bot.Depot.ScanAsync(hold.Token);
            return HttpAnswer.Json(Broke(hold) is { } оборвали
                ? Fail($"{итог.Reason}; {оборвали}")
                : Ok(итог.Reason));
        }
        catch (Exception e)
        {
            return HttpAnswer.Json(Fail($"обход склада сорвался: {e.Message}"));
        }
    }

    /// <summary>
    /// ДЕЛО ПО КНОПКЕ ОБОРВАЛИ — СКАЗАТЬ ОБ ЭТОМ, А НЕ ОТМОЛЧАТЬСЯ.
    /// null — не обрывали.
    ///
    /// СЛОВА ДАЁТ ОБЩЕЕ ПРАВИЛО (<see cref="Resume.NoReturn"/>), там же, где
    /// живёт приговор работам с возвратом: двух наборов слов про один и тот же
    /// разбор конца (<see cref="BodyArbiter.Ending"/>) быть не должно.
    ///
    /// ВОЗВРАТА У КНОПКИ НЕТ И БЫТЬ НЕ МОЖЕТ, и это надо назвать прямо. Кнопка
    /// окна — это ОДИН запрос, который ждёт ответа: браузер держит соединение,
    /// пока бот работает. Отдать такое дело общему возврату (<see cref="Resume"/>)
    /// значило бы заставить запрос ждать освобождения тела до
    /// <c>Resume.WaitForBodySeconds</c> — до трёх минут, — и человек увидел бы
    /// не «подождите», а оборванную страницу. Работа, которую надо доделывать
    /// после боя, живёт в ОЧЕРЕДИ ЗАДАЧ: она идёт в своём потоке, и возврат у
    /// неё уже есть.
    /// </summary>
    private static string? Broke(BodyArbiter.Hold hold) =>
        Resume.NoReturn(hold.End, hold.EndedBy);

    // ---------------- карта ----------------
    //
    // ЗАКАЗ ЗАКАЗЧИКА: «хочу вывод положения игрока на вебкарте, но КАК ДОП
    // НАСТРОЙКА». Отсюда всё устройство вкладки:
    //   • по умолчанию выключено (см. PanelConfig.Map) — на сервере окно
    //     открывают редко, а карта работает на каждый опрос;
    //   • своей памяти у карты нет: рисуется то, что бот УЖЕ знает — дом
    //     (Shelter.Home), склад (Depot), запомненные клетки (ResourceMemory);
    //   • координаты только ИГРОВЫЕ, как их видит человек в игре: в журнале
    //     бот уже говорит ими, и второй набор чисел сбивал бы с толку;
    //   • про живых людей — только имя и место, и только по отдельному
    //     выключателю (PanelConfig.MapPeople), тоже выключенному.
    //
    // Границы окна, потолки числа точек и отказы словами живут одним чистым
    // правилом (PanelMapRules) — здесь только сбор точек у механизмов бота.

    /// <summary>
    /// Точка карты из мировой клетки. ПЕРЕВОД ОДИН и тот же, что у журнала
    /// (<see cref="GameCoords.GameOf"/>): заведи карта свой — одно место
    /// называлось бы разными числами в журнале и на картинке.
    /// </summary>
    private MapMark Mark(MapMarkKind kind, BlockPos cell, string title, string note = "")
    {
        var g = bot.GameOf(cell);
        return new MapMark(kind, title, note, g.X, g.Y, g.Z);
    }

    /// <summary>
    /// ЧТО РИСОВАТЬ НА КАРТЕ. Собирается у механизмов бота и нигде не
    /// запоминается: карта — это взгляд, а не ещё одна память.
    /// </summary>
    /// <param name="запрос">
    /// Запрос страницы. Из него берётся ВЗГЛЯД — всё, что знает только браузер:
    ///   • «сторона» — сколько блоков в окне попросил человек кнопками или
    ///     колесом мыши. Нет числа — окно подбирается само, как и раньше;
    ///   • «центрX», «центрZ» — где человек держит карту, утянув её курсором.
    ///     Заказ 16.08: «карте добавить возможность двигать ее курсором как
    ///     любую другую карту». Нет чисел — окно едет за ботом;
    ///   • «сдвигX», «сдвигZ» — на какую долю окна карту только что утянули.
    ///     Считает сдвиг БОТ (<see cref="MapZoomRules.Pan"/>): перевод долей
    ///     окна в блоки — то самое место, где ось Z путают с высотой;
    ///   • «пикселей» — во сколько точек экрана эта картинка развернётся.
    ///     Без него уровень картинок карты сервера выбирался вслепую, и
    ///     заказчик 16.08 назвал это «плохое качество карты» (разобрано в
    ///     <see cref="WebMapRules.LevelForScreen"/>).
    /// Запоминать взгляд в настройках НЕ НАДО: карта — это взгляд, и взгляд
    /// у каждой открытой вкладки свой.
    /// </param>
    private string MapState(HttpRequest? запрос = null)
    {
        int? просятСторону =
            int.TryParse(запрос?.Q("сторона"), out int сторонаИзЗапроса) && сторонаИзЗапроса > 0
                ? сторонаИзЗапроса
                : null;
        // Ноль по оси — законная координата, поэтому «нет числа» и «ноль»
        // различаются: подставь мы ноль вместо отсутствия, карта на первом же
        // опросе прыгнула бы к точке спавна
        MapPick? просятСередину =
            int.TryParse(запрос?.Q("центрX"), out int серединаX) &&
            int.TryParse(запрос?.Q("центрZ"), out int серединаZ)
                ? new MapPick(серединаX, серединаZ)
                : null;
        // Доли перетаскивания разбирает та же дверь, что и прочие числа строки
        // запроса, — с десятичной точкой, а не по языку машины: JavaScript
        // пишет «0.125» и в русской Windows тоже, а местный разбор прочёл бы
        // это как 125, и карта улетала бы на сто окон вбок от одного движения
        double? тянулиX = Число(запрос?.Q("сдвигX"));
        double? тянулиZ = Число(запрос?.Q("сдвигZ"));
        int точекЭкрана =
            int.TryParse(запрос?.Q("пикселей"), out int точекИзЗапроса) && точекИзЗапроса > 0
                ? точекИзЗапроса
                : 0;
        bool карта = Config?.Panel.Map ?? false;
        bool люди = Config?.Panel.MapPeople ?? false;
        // СЕРВЕРНЫЙ РЕЖИМ — тот самый, ради которого карта и заведена доп
        // настройкой: он велит боту не отжирать лишнего, и карта под ним режет
        // свои потолки и говорит об этом вслух
        bool серверный = Config?.ServerMode.Use ?? false;

        // Отказ — тоже полноценный ответ, и он ОБЯЗАН объяснять себя: пустая
        // вкладка читается как «бот нигде не был», а это совсем другое
        if (PanelMapRules.WhyNoMap(карта, bot.CoordsKnown(), серверный) is { } нет)
            return JsonSerializer.Serialize(new
            {
                рисовать = false,
                включена = карта,
                людиВключены = люди,
                серверныйРежим = серверный,
                почему = нет,
                почемуБезЛюдей = PanelMapRules.WhyNoPeople(люди) ?? "",
                проСерверныйРежим = PanelMapRules.ServerModeNote(серверный),
                точки = Array.Empty<object>(),
                окно = (object?)null,
                заКраем = 0,
                // Про карту сервера отвечаем и в отказе: человек, вписавший её
                // адрес, должен видеть, дошёл ли бот до неё, — иначе он чинил
                // бы адрес, когда дело в выключенной карте
                // Ходить за сеткой уровней разрешаем, только если карта
                // ВКЛЮЧЕНА: выключенная затем и выключена, чтобы бот не делал
                // лишнего там, где на окно неделями никто не смотрит
                вебкарта = WebMapState(null, ask: карта)
            }, Json);

        var точки = new List<MapMark>();
        MapMark? якорь = null;

        // 1. САМ БОТ — то, ради чего карту и просили
        if (bot.Joined && bot.Self.Position is { } p)
        {
            var клетка = new BlockPos((int)Math.Floor(p.X), (int)Math.Floor(p.Y),
                (int)Math.Floor(p.Z));
            var метка = Mark(MapMarkKind.Bot, клетка, bot.Name, "здесь бот сейчас");
            якорь = метка;
            точки.Add(метка);
        }

        // 2. ДОМ. Он у бота ОДИН и живёт в укрытии — второго «где мой дом» в
        // библиотеке нет, и карта его не заводит
        if (bot.Shelter.Home is { } дом)
            точки.Add(Mark(MapMarkKind.Home, дом, "дом", "сюда бот уходит в бурю и после смерти"));

        // 2б. ПОСТ. Спрашиваем у самой способности удержания — второго «где
        // мой пост» в проекте нет, и заводить его на карте нельзя: разъехались
        // бы значок и ноги. Пост не задан — способность молчит, метки нет
        if (bot.Behaviors.Get<BehaviorHoldPost>()?.Post is { } пост)
            точки.Add(Mark(MapMarkKind.Post, пост, "пост", "здесь боту велено стоять"));

        // 3. СКЛАД. Спрашиваем у самого склада (Points): там же лежит правило
        // про соседние сундуки, и считать их второй раз здесь нельзя
        var сундуки = bot.Depot.Chests;
        foreach (var точка in bot.Depot.Points())
        {
            bool свой = сундуки.Contains(точка);
            точки.Add(Mark(MapMarkKind.Depot, точка,
                свой ? "склад" : "сундук рядом со складом",
                свой
                    ? (bot.Depot.Temporary ? "временное хранилище задачи" : "сундук склада")
                    : "подобран складом по соседству"));
        }

        // 4. ЗАПОМНЕННЫЕ КЛЕТКИ. Отбор — у самой памяти (Recall): она уже
        // умеет и забывать по сроку, и не выдавать подсмотренное читом.
        // Считать это здесь заново значило бы завести второе правило честности
        // ПОСТ СТАРШЕ ДОМА И ЗДЕСЬ ТОЖЕ. Бот не в мире, дом не задан, а пост
        // задан — карта открывалась на первом попавшемся сундуке или в (0,0,0),
        // то есть за полмиллиона блоков от того единственного места, которое
        // человек этому боту и назвал
        var откуда = якорь is { } я
            ? bot.WorldCell(я.X, я.Y, я.Z)
            : bot.Behaviors.Get<BehaviorHoldPost>()?.Post
              ?? bot.Shelter.Home ?? (сундуки.Count > 0 ? сундуки[0] : new BlockPos(0, 0, 0));
        double сейчасЧасов = bot.Resources.NowHours;
        foreach (var с in bot.Resources.Recall("", откуда, PanelMapRules.ResourceCapFor(серверный)))
            точки.Add(Mark(MapMarkKind.Resource, с.Pos,
                с.Kind.Length > 0 ? с.Kind : с.Code,
                ResourceMemory.AgeWords(с.AgeHours(сейчасЧасов))));

        // 5. ВСТРЕЧИ. Только по отдельному выключателю и только имя с местом —
        // см. PanelConfig.MapPeople. Времени встречи, счёта встреч и
        // приветствий здесь нет и быть не может
        if (люди)
            foreach (var встреча in MeetingPlaces(откуда, PanelMapRules.MeetingCapFor(серверный)))
                точки.Add(встреча);

        // ОКНО: само по себе — или ровно то, что человек попросил кнопками
        // масштаба и рукой. Заказ 16.08: «неплохо было бы и нам его добавить на
        // нашу» и «двигать ее курсором как любую другую карту».
        // Одна и та же MapFrame идёт и в доли точек, и в плитки подложки —
        // иначе метки и картинка разъедутся, как в живом прогоне 15.08
        var авто = PanelMapRules.Frame(точки, якорь);
        var взгляд = new MapLook(просятСторону, просятСередину);
        var окно = MapZoomRules.Frame(авто, якорь, взгляд);

        // КАРТУ ТОЛЬКО ЧТО УТЯНУЛИ КУРСОРОМ. Сдвигаем ТО САМОЕ окно, по
        // которому тянули (доли считаны от него), и дальше живём уже новой
        // серединой — её же страница получит назад и будет присылать сама.
        // Считает сдвиг правило, а не строчка здесь: см. MapZoomRules.Pan
        if (тянулиX is { } долейX && тянулиZ is { } долейZ)
        {
            взгляд = взгляд with { Center = MapZoomRules.Pan(окно, долейX, долейZ) };
            окно = MapZoomRules.Frame(авто, якорь, взгляд);
        }

        int заКраем = PanelMapRules.Outside(точки, окно);

        return JsonSerializer.Serialize(new
        {
            рисовать = true,
            включена = true,
            людиВключены = люди,
            серверныйРежим = серверный,
            почему = "",
            почемуБезЛюдей = PanelMapRules.WhyNoPeople(люди) ?? "",
            // Урезанные потолки НАЗЫВАЕМ. Человек, у которого бот помнит тысячу
            // клеток руды, увидел бы сорок и решил, что память потерялась
            проСерверныйРежим = PanelMapRules.ServerModeNote(серверный),
            // Координаты игровые — те же, что в журнале и в шапке окна
            координаты = "игровые",
            окно = new
            {
                центрX = окно.CenterX,
                центрZ = окно.CenterZ,
                сторона = окно.Span,
                минX = окно.MinX,
                минZ = окно.MinZ,
                шаг = PanelMapRules.GridStep(окно.Span),
                // МАСШТАБ. Ступени уходят СПИСКОМ, а не правилом «вдвое»:
                // кнопка «приблизить» тогда просто берёт соседнее число из
                // этого списка и не заводит на странице второго мнения о том,
                // какие масштабы бывают. Заведи она своё — «отдалить до упора»
                // показывало бы не то же, что автоподбор при дальней точке
                ступени = MapZoomRules.Spans,
                ступень = MapZoomRules.Step(окно.Span),
                // Само подобралось или человек попросил — надо различать: у
                // кнопки «всё в окне» иначе нет вида «уже так»
                самоПодобралось = взгляд.Untouched,
                // КАРТУ ДЕРЖАТ РУКОЙ. Утянув её от бота, человек через минуту
                // видит, что метки бота на карте нет, — и это неотличимо от
                // «бот пропал». Поэтому и признак, и слова
                держитЧеловек = взгляд.Center is not null,
                проОкно = MapZoomRules.HeldWords(взгляд),
                // СКОЛЬКО МЫШИ ПОЗВОЛЕНО ДРОГНУТЬ, чтобы отпускание кнопки
                // осталось выбором точки, а не концом перетаскивания. Число
                // одно и живёт в правиле (MapPickRules.DragSlopPixels): заведи
                // страница своё, протяжка карты то и дело выбирала бы боту цель
                проскокМыши = MapPickRules.DragSlopPixels,
                // Насколько крупно смотрим — словами. Без числа «плохое
                // качество» и «слишком крупный масштаб» с виду одно и то же
                проМасштаб = MapZoomRules.Words(окно.Span, точекЭкрана)
            },
            заКраем,
            точки = точки.Select(м => new
            {
                вид = Kind(м.Kind),
                имя = м.Title,
                что = м.Note,
                x = м.X,
                y = м.Y,
                z = м.Z,
                // Долю считает правило, а не страница: перепутать здесь Z с Y
                // проще всего, а стоит это карты, которая молча врёт о месте
                доляX = PanelMapRules.Fraction(м.X, окно.MinX, окно.Span),
                доляZ = PanelMapRules.Fraction(м.Z, окно.MinZ, окно.Span)
            }),
            // КАРТА САМОГО СЕРВЕРА подложкой под эти точки — если её адрес
            // задан и она ответила. Точки при этом ТЕ ЖЕ и в тех же долях:
            // подложка ничего не двигает, она ложится под них
            вебкарта = WebMapState(окно, якорь, screenPixels: точекЭкрана)
        }, Json);
    }

    /// <summary>
    /// ЧТО СКАЗАТЬ ОКНУ ПРО КАРТУ СЕРВЕРА.
    ///
    /// ЗАКАЗ ЗАКАЗЧИКА ДОСЛОВНО: «под вебкартой я имел ввиду поддержку карты по
    /// типу https://map.tops.vintagestory.at/?x=0&amp;y=0&amp;zoom=5». Адрес
    /// такой карты — настройка (<see cref="PanelConfig.MapUrl"/>); задан —
    /// панель кладёт её картинки под свои точки, и метка бота оказывается на
    /// настоящей карте мира. Не задан или карта не ответила — вкладка работает
    /// ровно как раньше, и причина названа словами.
    ///
    /// ЧУЖИХ ИГРОКОВ ЗДЕСЬ НЕТ И БЫТЬ НЕ МОЖЕТ: такая карта — выгрузка мира, а
    /// не живая связь, положений игроков она не отдаёт вовсе (разобрано в
    /// <see cref="WebMapRules"/>). Панель показывает на ней только СВОЕГО бота
    /// и то, что бот и так знает.
    /// </summary>
    /// <param name="frame">окно карты; null — рисовать нечего, нужен только ответ про адрес</param>
    /// <param name="anchor">бот, если он в мире: ссылка «открыть на карте» ведёт к нему</param>
    /// <param name="ask">можно ли ходить за сеткой на чужой сервер (см. <see cref="WebMapSource.Look"/>)</param>
    /// <param name="screenPixels">
    /// Во сколько точек экрана страница развернёт эту картинку. Это ЕДИНСТВЕННОЕ
    /// число, которого бот знать не может, а без него уровень картинок
    /// выбирается вслепую — см. <see cref="WebMapRules.LevelForScreen"/> и
    /// жалобу заказчика 16.08 «плохое качество карты».
    /// </param>
    private object WebMapState(MapFrame? frame, MapMark? anchor = null, bool ask = true,
        int screenPixels = 0)
    {
        string адрес = Config?.Panel.MapUrl ?? "";
        var взгляд = webMap.Look(адрес, ask);

        if (взгляд.Grid is not { } сетка || frame is not { } окно)
            return new
            {
                задана = адрес.Trim().Length > 0,
                адрес = взгляд.Address,
                готова = false,
                почему = взгляд.Why,
                ссылка = "",
                уровень = 0,
                проМасштаб = "",
                растяжение = 0.0,
                // Замер покрытия отдаём и в отказе — нулями и молчанием, а не
                // бодрым «накрыто целиком»: подложки нет вовсе, и мерить нечего
                покрытие = (object?)null,
                проПокрытие = "",
                плитки = Array.Empty<object>()
            };

        // УРОВЕНЬ БЕРЁМ ПОД ЭКРАН, А НЕ ПОД ЧИСЛО ПЛИТОК. Заказчик 16.08:
        // «плохое качество карты, проверь точно ли ты выводишь масштаб карты».
        // Проверено и оказалось так: старое правило считало только плитки и
        // отдавало уровень вдвое крупнее нужного, а браузер его растягивал.
        // Не сказал браузер своего размера — LevelForScreen сам вернётся к
        // старому правилу, гадать за него нельзя
        int уровень = WebMapRules.LevelForScreen(сетка, окно.Span, screenPixels);
        var плитки = WebMapRules.Tiles(сетка, окно, уровень, взгляд.Address);

        // ЗАМЕР ПОКРЫТИЯ — прямой ответ на «карта не на всю зону». Заказчику
        // дважды докладывали «готово», и дважды живьём было сломано; поэтому
        // окно теперь не уверяет, а СЧИТАЕТ: сколько клеток под этой областью,
        // сколько попрошено и сколько лежит за краем выгруженного мира
        var покрытие = WebMapRules.Cover(сетка, окно, уровень, плитки);

        // Ссылка ведёт туда, где бот СЕЙЧАС; нет бота в мире — в середину окна.
        // Координаты игровые и без пересчёта: карта считает их так же, как игра
        int ссылкаX = anchor?.X ?? окно.CenterX;
        int ссылкаZ = anchor?.Z ?? окно.CenterZ;

        return new
        {
            задана = true,
            адрес = взгляд.Address,
            готова = плитки.Count > 0,
            // Сетку взяли, а картинок под это место нет — это не «карта не
            // работает», а «сюда никто не заходил, и мир там не выгружен»
            почему = плитки.Count > 0
                ? ""
                : "карта сервера отвечает, но картинок на это место у неё нет: " +
                  "выгружается только то, что в мире кто-то посетил",
            ссылка = WebMapRules.Link(взгляд.Address, ссылкаX, ссылкаZ,
                WebMapRules.ViewZoom(сетка, уровень)),
            уровень,
            // КАЧЕСТВО ПОДЛОЖКИ ЧИСЛОМ: какой уровень взят, сколько в нём
            // блоков на точку и во сколько раз браузер его растянул. Иначе
            // «плохое качество» не отличить от «слишком крупный масштаб», и
            // человек чинит карту вместо того, чтобы её отдалить
            проМасштаб = MapZoomRules.WebMapWords(сетка, уровень, окно.Span, screenPixels),
            // ВО СКОЛЬКО РАЗ РАСТЯГИВАЮТ — числом, а не только словами: по нему
            // страница решает, сглаживать картинку или показывать её точками.
            // Растянутую честнее точками (каждый блок своим цветом), сжатую —
            // только сглаживанием, иначе ровный лес идёт рябью
            растяжение = MapZoomRules.Stretch(сетка, уровень, окно.Span, screenPixels),
            // НАКРЫЛИ ЛИ ПЛИТКИ ВСЮ ОБЛАСТЬ — числом и словами. Числа идут
            // отдельно от слов затем, что по ним видно, чья это беда: клеток
            // «надо» столько-то, «запрошено» столько-то, а «заКраемМира» —
            // это места, куда в игре никто не заходил, и картинки там нет
            // и быть не может
            покрытие = new
            {
                надо = покрытие.Need,
                запрошено = покрытие.Asked,
                заКраемМира = покрытие.Beyond,
                неХватает = покрытие.Missing,
                целиком = покрытие.Whole
            },
            проПокрытие = WebMapRules.CoverWords(покрытие),
            плитки = плитки.Select(п => new
            {
                адрес = п.Url,
                // МЕСТО ПЛИТКИ — ИГРОВЫМИ КООРДИНАТАМИ, а не долей окна, и это
                // прямой ответ на «карта полэкрана только»: доля меняется на
                // каждом шаге бота, и страница пересобирала подложку по три
                // раза в минуту, обрывая недокачанные картинки. Разобрано в
                // WebMapTile — там же и живой случай
                x = п.GameX,
                z = п.GameZ,
                ширина = п.GameW,
                высота = п.GameH
            })
        };
    }

    /// <summary>
    /// Слово для вёрстки. Русское название точка несёт своё
    /// (<see cref="MapMark.Title"/>), а по этому слову страница выбирает цвет:
    /// решай она по русскому имени — перевод окна на английский сломал бы
    /// раскраску.
    /// </summary>
    private static string Kind(MapMarkKind kind) => kind switch
    {
        MapMarkKind.Bot => "bot",
        MapMarkKind.Home => "home",
        MapMarkKind.Post => "post",
        MapMarkKind.Depot => "depot",
        MapMarkKind.Resource => "resource",
        MapMarkKind.Meeting => "meeting",
        _ => "other"
    };

    /// <summary>
    /// МЕСТА ВСТРЕЧ — ИМЯ И МЕСТО, И БОЛЬШЕ НИЧЕГО.
    ///
    /// Отдельным методом нарочно: здесь единственное место, где книга встреч
    /// вообще смотрит наружу, и обрезка полей должна быть видна одним взглядом.
    /// Из <see cref="Meeting"/> берутся ровно <see cref="Meeting.Name"/> и
    /// клетка; <see cref="Meeting.Times"/>, <see cref="Meeting.FirstSeen"/>,
    /// <see cref="Meeting.LastSeen"/> и <see cref="Meeting.LastGreeted"/> не
    /// уходят никуда — это записи о человеке, который о них не знает.
    /// </summary>
    private List<MapMark> MeetingPlaces(BlockPos from, int limit)
    {
        // Книгу пишет поведение приветствия, а читает опрос из браузера.
        // Уронить из-за этого всю карту нельзя, промолчать — тоже
        List<Meeting> снимок;
        try
        {
            снимок = [.. bot.Meetings.All];
        }
        catch (Exception e)
        {
            OnLog?.Invoke($"карта: книга встреч прямо сейчас меняется, мест встреч не будет ({e.Message})");
            return [];
        }

        return снимок
            .Where(м => м.Name.Length > 0)
            .OrderBy(м => ResourceMemory.DistanceBetween(new BlockPos(м.X, м.Y, м.Z), from))
            .Take(limit)
            // ИМЯ И МЕСТО. Ни времени, ни счёта встреч в метку не кладётся
            .Select(м => Mark(MapMarkKind.Meeting, new BlockPos(м.X, м.Y, м.Z), м.Name,
                "место последней встречи"))
            .ToList();
    }

    /// <summary>
    /// Включить или выключить карту (и отдельно — людей на ней) из окна.
    ///
    /// Выбранное ложится в bot.json тем же автосохранением, что и всё
    /// остальное в окне: заказчик просил не выбирать одно и то же на каждый
    /// запуск. Включение ЛЮДЕЙ уходит в журнал отдельной громкой строкой —
    /// «когда на карте появились чужие имена» человек должен уметь прочесть.
    /// </summary>
    private HttpAnswer SetMap(HttpRequest r)
    {
        if (Config is not { } c)
            return HttpAnswer.Json(Fail(
                "настройки запуска к окну не подключены — карту включать негде: " +
                "она живёт настройкой panel.map в bot.json"));

        var body = Body(r);
        string что = (Field(body, "что") ?? "").Trim();
        bool на = Field(body, "на") is "true" or "1" or "True";

        switch (что)
        {
            case "карта":
                c.Panel.Map = на;
                OnLog?.Invoke($"карта в окне управления {(на ? "включена" : "выключена")}");
                break;
            case "люди":
                c.Panel.MapPeople = на;
                // Громко: с этой минуты в окне видны имена живых игроков
                OnLog?.Invoke(на
                    ? "НА КАРТЕ ВКЛЮЧЕНЫ МЕСТА ВСТРЕЧ: в окне видны имена встреченных " +
                      "игроков и места, где бот их видел. Наружу с этой страницы ничего " +
                      "не уходит, но имена — чужие"
                    : "места встреч на карте выключены");
                break;
            // АДРЕС КАРТЫ СЕРВЕРА — не выключатель, а строка, поэтому берётся
            // из отдельного поля. Пустая строка означает «карты сервера нет»,
            // и это законный ответ, а не описка
            case "адрес":
            {
                string сырой = (Field(body, "адрес") ?? "").Trim();
                if (сырой.Length == 0)
                {
                    c.Panel.MapUrl = "";
                    OnLog?.Invoke("карта сервера отключена от окна: адрес стёрт");
                    return HttpAnswer.Json(Ok("адрес карты сервера стёрт — панель рисует " +
                                              "только то, что знает сам бот. " + SaveConfig()));
                }

                // Проверяем ДО записи: адрес с опиской, молча легший в файл, —
                // это вкладка, которая потом неделю говорит «карта не ответила»
                if (WebMapRules.Base(сырой) is not { } основа)
                    return HttpAnswer.Json(Fail(
                        WebMapRules.WhyNoWebMap(сырой) ?? $"адрес не понят: «{сырой}»"));

                c.Panel.MapUrl = основа;
                // Громко: с этой минуты браузер тянет картинки с чужой машины
                OnLog?.Invoke($"карта сервера в окне управления: {основа}. Бот будет читать " +
                              "оттуда сетку уровней, а браузер — картинки; ничего никуда " +
                              "не отправляется");
                return HttpAnswer.Json(Ok($"карта сервера: {основа}. " +
                    // СЕТЬ ТРАНСЛОКАТОРОВ БЕРЁТ АДРЕС НЕ ОТСЮДА — и молчать об
                    // этом нельзя. Живой прогон 15.08, две строки журнала подряд:
                    // в 21:24:23 человек вписал карту в это самое поле, а в
                    // 21:24:34 поход ответил «сети транслокаторов взять
                    // неоткуда: адрес карты сервера не задан» и пошёл пешком.
                    // Настроек и правда ДВЕ: подложка окна — дело панели, а сеть
                    // переходов — политика роли (ручка «КартаТранслокаторов»), и
                    // подставить одну за другую панель не вправе. Но человек,
                    // вписавший адрес один раз, обязан узнать про вторую ЗДЕСЬ,
                    // а не через сорок минут ходьбы
                    "Это подложка окна. Чтобы бот считал дорогу ЧЕРЕЗ ТРАНСЛОКАТОРЫ, " +
                    "тот же адрес нужен ещё в настройке роли «КартаТранслокаторов» " +
                    "(вкладка «Настройки роли», раздел про переходы) — панель за роль " +
                    "его не вписывает. " + SaveConfig()));
            }
            default:
                return HttpAnswer.Json(Fail(
                    $"не понял, что включать: «{что}». Знаю «карта», «люди» и «адрес»"));
        }

        return HttpAnswer.Json(Ok(
            $"{что}: {(на ? "включено" : "выключено")}. " + SaveConfig()));
    }

    // ---------------- точка на карте: «доберись сам» ----------------
    //
    // ЗАКАЗ ЗАКАЗЧИКА ДОСЛОВНО: «хочу по веб админке на карте давать точку куда
    // ему бежать, и он уже думал, через телепорты или пешком и шел».
    //
    // ПОЧЕМУ ЭТО ДВА ЗАПРОСА, А НЕ ОДИН.
    //   • «/api/map/pick» — ЧТО ВЫЙДЕТ, не делая ни шагу: выбранная точка, обе
    //     оценки («пешком 87 мин против 47 через сеть») и каждый шаг маршрута.
    //     Человек читает это и решает;
    //   • «/api/map/goto» — ИДТИ. Отдельным нажатием, потому что промах мышью
    //     по карте иначе увёл бы бота за десять тысяч блоков, и узнал бы об
    //     этом человек по журналу через полчаса.
    //
    // ЩЕЛЧОК СЧИТАЕТСЯ ПО ТОМУ ОКНУ, КОТОРОЕ ЧЕЛОВЕК ВИДЕЛ, а не по нынешнему —
    // потому страница и присылает его вместе с долями. Бот за эти полсекунды
    // мог уйти, окно карты едет за ним, и точка уехала бы вместе с ним: человек
    // ткнул в дом, а бот пошёл бы в поле рядом.

    /// <summary>
    /// ЧТО ВЫЙДЕТ, ЕСЛИ ПОЙТИ В ЭТУ ТОЧКУ. Ни шагу не делается.
    ///
    /// Точку можно назвать двояко: щелчком по карте (доли и то окно, что было
    /// на экране) или числами (человек вписал координаты сам). Второе нужно
    /// затем, что высоты у карты нет вовсе (<see cref="MapPickRules.NoHeightWhy"/>),
    /// и, поправив её, человек вправе увидеть пересчитанный план.
    /// </summary>
    private HttpAnswer MapPickAnswer(HttpRequest r)
    {
        var body = Body(r);

        if (!bot.CoordsKnown())
            return HttpAnswer.Json(Fail(
                "бот не в мире: сдвиг точки спавна приходит только после входа, а без него " +
                "игровые координаты перевести не во что. Мировые я показывать не буду — " +
                "они отличаются на полмиллиона блоков"));

        if (WhereOnMap(body) is not { } точка)
            return HttpAnswer.Json(Fail(
                "щелчок мимо карты: доля вне окна или окно не назвали. Ткните по самой " +
                "картинке — или впишите координаты числами"));

        // ВЫСОТА. Своей у щелчка нет; берём ту, на которой стоит бот, и говорим
        // об этом прямо — «иду к (2050, 111, 6900)» звучит как точный адрес,
        // будучи догадкой
        var (x, z) = точка;
        bool высотуНазвали = Число(body, "y") is not null;
        int y = (int)Math.Floor(Число(body, "y") ?? bot.Self.Position?.Y ?? 0);

        var цель = bot.WorldCell(x, y, z);
        var поход = new Trek(bot.Context, bot.Routes);
        if (поход.PlanTo(цель) is not { } план)
            return HttpAnswer.Json(Fail("бот не знает, где стоит сам — считать дорогу не от чего"));

        return HttpAnswer.Json(JsonSerializer.Serialize(new
        {
            ok = true,
            // Числа — ИГРОВЫЕ, те же, что человек видит в игре и в журнале
            точка = new { x, y, z },
            высотуНазвали,
            проВысоту = MapPickRules.NoHeightWhy,
            // Слова считает МЕХАНИЗМ, а не окно: собери эту строку страница, и
            // у окна, у чата и у журнала вышло бы три разных ответа про один и
            // тот же путь
            коротко = план.Tell(),
            подробно = план.TellSteps(),
            черезСеть = план.ByNet,
            пешкомСекунд = план.Choice.WalkSeconds,
            сетьюСекунд = план.Choice.NetSeconds,
            пересадок = план.Choice.Transfers,
            оговорки = план.Caveats,
            проСеть = план.NetWhy
        }, Json));
    }

    /// <summary>
    /// НАРИСОВАННОЕ НА КАРТЕ → ПОЛЯ ЗАДАЧИ.
    ///
    /// ЗАКАЗ ЗАКАЗЧИКА ДОСЛОВНО: «карту вкладку объедини с задачами и добавим
    /// добавление задач с карты, чтобы можно было нарисовать где копать к
    /// примеру».
    ///
    /// ЭТОТ ОТВЕТ НИЧЕГО НЕ СТАВИТ В ОЧЕРЕДЬ. Он только называет, какие поля
    /// каких дел заполняет нарисованное, — а задача собирается ТЕМ ЖЕ
    /// конструктором и уходит теми же «Пустить сейчас» и «В очередь». Второго
    /// пути в очередь тут нет нарочно: разойдись они, задача с карты пошла бы
    /// мимо проверок, которые бегун делает над набранной руками.
    ///
    /// ВТОРОГО ОПИСАНИЯ КОМАНД ТОЖЕ НЕТ. Виды работ берутся из того же меню
    /// (<see cref="WorkMenu"/>), что и в конструкторе, а какое поле чем
    /// заполнить, решает чистое правило (<see cref="MapDrawRules.Fill"/>) по
    /// полям, которые вид работы объявил о себе сам.
    /// </summary>
    private HttpAnswer MapDrawAnswer(HttpRequest r)
    {
        var body = Body(r);

        if (!bot.CoordsKnown())
            return HttpAnswer.Json(Fail(
                "бот не в мире: сдвиг точки спавна приходит только после входа, а без него " +
                "игровые координаты перевести не во что"));

        string видСтрокой = (Field(body, "вид") ?? "").Trim().ToLowerInvariant();
        MapDrawKind вид = видСтрокой switch
        {
            "область" or "area" => MapDrawKind.Area,
            "отрезок" or "line" => MapDrawKind.Line,
            "точка" or "point" => MapDrawKind.Point,
            _ => MapDrawKind.Point
        };

        // ОБА КОНЦА СЧИТАЕТ ТО ЖЕ ПРАВИЛО, ЧТО И ОБЫЧНЫЙ ЩЕЛЧОК: перепутать в
        // переводе доли ось Z с высотой проще всего, и второго такого перевода
        // заводить нельзя
        if (WhereOnMap(body, "1") is not { } первый)
            return HttpAnswer.Json(Fail(
                "начало нарисованного мимо карты: доля вне окна или окно не назвали"));
        var второй = вид == MapDrawKind.Point
            ? первый
            : WhereOnMap(body, "2") ?? первый;

        // ВЫСОТЫ У КАРТЫ НЕТ ВОВСЕ — берём ту, на которой стоит бот, и говорим
        // об этом прямо (та же оговорка, что и у щелчка)
        bool высотуНазвали = Число(body, "y") is not null;
        int y = (int)Math.Floor(Число(body, "y") ?? bot.Self.Position?.Y ?? 0);

        var нарисовано = new MapDrawn(вид, первый.X, первый.Z, второй.X, второй.Z);
        var меню = Jobs?.Menu() ?? [];

        var дела = меню.Select(k =>
        {
            var годно = MapDrawRules.Fill(k.Fields, нарисовано, y);
            return new
            {
                имя = k.Kind,
                название = k.Title,
                что = k.About,
                годится = годно.Any,
                почему = годно.Why,
                ещёНужно = годно.StillNeeded,
                поля = годно.Fields.Select(п => new
                {
                    имя = п.Name,
                    вид = п.Kind,
                    // Клетка едет ТРЕМЯ числами — ровно теми, что кладутся в
                    // поле конструктора. Высоту несёт само правило: точка без
                    // высоты для конструктора недозаполнена, и человек видел бы
                    // два числа из трёх, не понимая, чего от него хотят
                    x = п.X, y = п.Y, z = п.Z,
                    число = п.Number
                })
            };
        }).ToList();

        return HttpAnswer.Json(JsonSerializer.Serialize(new
        {
            ok = true,
            нарисовано = new
            {
                вид = вид switch
                {
                    MapDrawKind.Area => "область",
                    MapDrawKind.Line => "отрезок",
                    _ => "точка"
                },
                x1 = нарисовано.X1, z1 = нарисовано.Z1,
                x2 = нарисовано.X2, z2 = нарисовано.Z2,
                серединаX = нарисовано.CenterX,
                серединаZ = нарисовано.CenterZ,
                сторона = нарисовано.Side,
                радиус = нарисовано.Radius,
                длина = нарисовано.Length,
                y,
                словами = нарисовано.ToString()
            },
            высотуНазвали,
            проВысоту = MapPickRules.NoHeightWhy,
            // Ни одно дело не подошло — это ОТВЕТ, а не пустой список. Молча
            // пустой список человек читает как поломку окна
            подошло = дела.Count(д => д.годится),
            дела
        }, Json));
    }

    /// <summary>
    /// ИДТИ К ТОЧКЕ. Отвечает СРАЗУ, а сам поход идёт фоном.
    ///
    /// ПОЧЕМУ НЕ ЖДЁМ КОНЦА. Поход через полмира длится сорок минут; запрос,
    /// висящий сорок минут, браузер бросит задолго до конца, и человек решит,
    /// что бот не пошёл. Ход дела виден там же, где и всё остальное, — в
    /// журнале окна: поход докладывает каждый шаг.
    ///
    /// ОСТАНОВИТЬ — тем же «Остановить», что и всё прочее: поход идёт под
    /// возвратом к прерванному (<see cref="Resume"/>), и <c>CancelCurrent</c>
    /// гасит его насмерть вместе с возвратом.
    /// </summary>
    private HttpAnswer MapGoTo(HttpRequest r)
    {
        var body = Body(r);

        if (!bot.Joined)
            return HttpAnswer.Json(Fail("бот не в мире — идти некому"));
        if (!bot.CoordsKnown())
            return HttpAnswer.Json(Fail("сдвиг точки спавна ещё не пришёл — цель перевести не во что"));

        if (Число(body, "x") is not { } x || Число(body, "z") is not { } z)
            return HttpAnswer.Json(Fail("не сказано, куда идти: нужны игровые x и z"));
        int y = (int)Math.Floor(Число(body, "y") ?? bot.Self.Position?.Y ?? 0);

        var цель = bot.WorldCell(x, y, z);
        var поход = new Trek(bot.Context, bot.Routes);
        // Приставка СВОЯ: «[поход]» в журнале отличает разговор о дороге от
        // «[транслокатор] сервер подтвердил перенос» — это разные события
        поход.OnLog += m => OnLog?.Invoke($"[поход] {m}");

        // ПЛАН — В ЖУРНАЛ ДО ВЫХОДА, а не только в окно тому, кто нажал: через
        // час «почему он поплёлся пешком» должно читаться, а не гадаться
        string ответ = поход.PlanTo(цель) is { } план
            ? план.Tell()
            : "плана нет: бот не знает, где стоит";

        _ = Task.Run(async () =>
        {
            try
            {
                var итог = await поход.GoAsync(цель);
                OnLog?.Invoke($"[поход] {итог.Message}");
            }
            catch (Exception e)
            {
                // Фоновая работа, упавшая молча, — это бот, который «просто не
                // пошёл»: ни строки в журнале, ни ответа человеку
                OnLog?.Invoke($"[поход] сорвался: {e.Message}");
            }
        });

        return HttpAnswer.Json(Ok($"пошёл к ({x}, {y}, {z}): {ответ}. Ход дела — в журнале; " +
                                  "остановить можно кнопкой «Остановить»"));
    }

    /// <summary>
    /// КУДА ТКНУЛИ — игровыми X и Z. Либо числами, либо щелчком по карте
    /// (доли + то окно, что было на экране). null — ни того, ни другого.
    ///
    /// Сам перевод доли в клетку — чистое правило
    /// (<see cref="MapPickRules.At"/>), а не строчка здесь: перепутать в нём
    /// ось Z с высотой проще всего, а стоит это бота, ушедшего не туда, куда
    /// ткнули пальцем.
    /// </summary>
    /// <param name="конец">
    /// Хвост имени поля: пусто — обычный щелчок («доляX»), «1» и «2» — концы
    /// нарисованного («доляX1», «доляX2»). Хвост нужен затем, что у области и
    /// отрезка ДВА конца, а перевод у них обязан быть ОДИН: заведи второй ход
    /// для второго конца — и угол области считался бы не тем правилом, что
    /// первый, а увидеть это можно было бы только по кривой яме.
    /// </param>
    private static (int X, int Z)? WhereOnMap(JsonElement body, string конец = "")
    {
        if (Число(body, "x" + конец) is { } x && Число(body, "z" + конец) is { } z)
            return ((int)Math.Floor(x), (int)Math.Floor(z));

        if (Число(body, "минX") is not { } минX || Число(body, "минZ") is not { } минZ ||
            Число(body, "сторона") is not { } сторона ||
            Число(body, "доляX" + конец) is not { } доляX ||
            Число(body, "доляZ" + конец) is not { } доляZ)
            return null;

        // Окно строим ТО САМОЕ, что видел человек: его середина считается из
        // краёв ровно так же, как её считал MapFrame, отдавая эти края окну
        int сторонаЦелая = (int)Math.Round(сторона);
        var окно = new MapFrame((int)Math.Round(минX) + сторонаЦелая / 2,
            (int)Math.Round(минZ) + сторонаЦелая / 2, сторонаЦелая);
        return MapPickRules.At(окно, доляX, доляZ) is { } точка ? (точка.X, точка.Z) : null;
    }

    /// <summary>
    /// Число из тела запроса. null — поля нет или это не число: подставлять
    /// вместо него ноль нельзя, ноль по оси — законная координата.
    /// </summary>
    private static double? Число(JsonElement body, string имя)
    {
        if (body.ValueKind != JsonValueKind.Object || !body.TryGetProperty(имя, out var поле))
            return null;
        if (поле.ValueKind == JsonValueKind.Number && поле.TryGetDouble(out double число))
            return double.IsFinite(число) ? число : null;
        // Страница шлёт то, что набрал человек, — а это строка. Точка
        // десятичная всегда: разбирай мы её по местным правилам, «-260,5» на
        // машине с запятой прочлось бы как два числа
        return поле.ValueKind == JsonValueKind.String &&
               double.TryParse(поле.GetString(), System.Globalization.NumberStyles.Float,
                   System.Globalization.CultureInfo.InvariantCulture,
                   out double изСтроки) && double.IsFinite(изСтроки)
            ? изСтроки
            : null;
    }

    /// <summary>
    /// То же число, но из СТРОКИ ЗАПРОСА. Пустая строка — это «границы нет», а
    /// не ноль: отбор «вес до 0» и отбор «верхней границы не задавал» — разные
    /// ответы, и подставить сюда ноль значило бы спрятать весь список.
    /// Десятичная точка всегда своя (см. <see cref="Число(JsonElement,string)"/>).
    /// </summary>
    private static double? Число(string? изАдреса) =>
        double.TryParse((изАдреса ?? "").Trim(), System.Globalization.NumberStyles.Float,
            System.Globalization.CultureInfo.InvariantCulture, out double n) && double.IsFinite(n)
            ? n
            : null;

    // ---------------- правая кнопка на вещи ----------------
    //
    // ЗАКАЗ ЗАКАЗЧИКА: «чтобы можно в вебформе пкм на предмет и выбирать на
    // него надеть, отнести на склад или выкинуть».
    //
    // ОКНО НИЧЕГО НЕ РЕШАЕТ САМО. Надевается ли вещь — отвечает реестр игры
    // (Hands.WhereWorn); удалось ли действие — отвечает СЕРВЕР, а не факт
    // отправки пакета. Соврать тут особенно легко: перенос идёт пакетом 8, тем
    // самым, на котором склад однажды доложил «легло 112 шт.» в пустой сундук.
    // Поэтому все три ответа окна — это дословный отчёт механизма.

    /// <summary>
    /// Куда человек показал: инвентарь, место в нём и что он там ВИДЕЛ.
    /// Код нужен третьим: страницу оставляют открытой надолго, вещи за это
    /// время переезжают, и надеть или выбросить не то — потеря, которую не
    /// отменить. Не совпало — механизм откажет, а не сделает наугад.
    /// </summary>
    private static (string Inventory, int Slot, string? Code, string? Bad) Pointed(HttpRequest r)
    {
        var body = Body(r);
        string инвентарь = (Field(body, "инвентарь") ?? "").Trim();
        string место = (Field(body, "место") ?? "").Trim();
        string? код = Field(body, "код")?.Trim();
        if (инвентарь.Length == 0)
            return ("", -1, null, "не сказано, в каком инвентаре лежит вещь");
        if (!int.TryParse(место, out int n) || n < 0)
            return ("", -1, null, $"не понял место «{место}»: нужно число");
        return (инвентарь, n, код is { Length: > 0 } ? код : null, null);
    }

    /// <summary>
    /// НАДЕТЬ ВЫБРАННУЮ ВЕЩЬ.
    ///
    /// Тело у бота НЕ ОТБИРАЕМ: надевание не двигает ногами, а забрать очередь
    /// приказом (<see cref="BodyArbiter.Importance.Command"/>) значило бы
    /// оборвать идущий наряд насмерть — человек хотел надеть шлем, а бросил
    /// карьер на 67-й клетке. Защита тут другая и настоящая: успех считается
    /// по содержимому слота брони после переноса.
    /// </summary>
    private async Task<HttpAnswer> WearItemAsync(HttpRequest r)
    {
        var (инвентарь, место, код, беда) = Pointed(r);
        if (беда != null)
            return HttpAnswer.Json(Fail(беда));
        if (!bot.Joined)
            return HttpAnswer.Json(Fail("бот не в мире — надевать некому"));

        try
        {
            var итог = await bot.Hands.WearAsync(инвентарь, место, код);
            return HttpAnswer.Json(итог.Success ? Ok(итог.Reason) : Fail(итог.Reason));
        }
        catch (Exception e)
        {
            return HttpAnswer.Json(Fail($"надеть не вышло: {e.Message}"));
        }
    }

    /// <summary>
    /// СНЯТЬ ВЫБРАННУЮ ВЕЩЬ — обратное «Надеть».
    ///
    /// ЖАЛОБА ЗАКАЗЧИКА ДОСЛОВНО: «в вебформе инвентаря нельзя снять вручную
    /// броню, ток надеть». Половина пары и правда отсутствовала: снять кирасу
    /// можно было только рейсом на склад, то есть отдав её.
    ///
    /// ТЕЛО НЕ ОТБИРАЕМ — по той же причине, что и у надевания: снятие не
    /// двигает ногами, а забрать очередь приказом значило бы оборвать идущий
    /// наряд насмерть. Защита тут другая и настоящая — успех считается по тому,
    /// что слот одежды ОПУСТЕЛ (<see cref="BodyHeat.UndressSlotAsync"/>).
    ///
    /// СНИМАЕТ ЕДИНСТВЕННЫЙ МЕХАНИЗМ, тот же, которым бот переодевается в тёплое
    /// и освобождает занятый слот перед надеванием; своей копии переноса тут
    /// нет ни строки (см. <see cref="Hands.TakeOffAsync"/>).
    /// </summary>
    private async Task<HttpAnswer> TakeOffItemAsync(HttpRequest r)
    {
        var (инвентарь, место, код, беда) = Pointed(r);
        if (беда != null)
            return HttpAnswer.Json(Fail(беда));
        if (!bot.Joined)
            return HttpAnswer.Json(Fail("бот не в мире — снимать некому"));

        try
        {
            var итог = await bot.Hands.TakeOffAsync(инвентарь, место, код);
            return HttpAnswer.Json(итог.Success ? Ok(итог.Reason) : Fail(итог.Reason));
        }
        catch (Exception e)
        {
            return HttpAnswer.Json(Fail($"снять не вышло: {e.Message}"));
        }
    }

    /// <summary>
    /// СНЯТЬ ВСЮ БРОНЮ ОДНОЙ КНОПКОЙ.
    ///
    /// ЗАЧЕМ РЯДОМ С ПОШТУЧНЫМ «СНЯТЬ». Брони три места (голова, тело, ноги), и
    /// три щелчка по меню — это уже не «снять броню», а возня. Механики второй
    /// при этом не заводится: кнопка зовёт <see cref="ArmorKit.UnequipAllAsync"/>,
    /// ту же дверь, которой бот раздевается САМ, когда рядом стало тихо, — а она
    /// уже идёт в <see cref="BodyHeat.UndressSlotAsync"/>, единственный механизм
    /// снятия на весь проект.
    ///
    /// ОТВЕЧАЕМ ЧИСЛОМ СНЯТОГО, А НЕ СЛОВОМ «ГОТОВО»: каждый предмет засчитан
    /// по факту от сервера (слот одежды опустел), и «снял 0» — это честный
    /// ответ, а не молчание. Обычно он значит «в сумках нет места».
    /// </summary>
    private async Task<HttpAnswer> TakeOffArmorAsync()
    {
        if (!bot.Joined)
            return HttpAnswer.Json(Fail("бот не в мире — снимать некому"));

        try
        {
            int сняли = await ArmorKit.UnequipAllAsync(bot.Context);
            return HttpAnswer.Json(сняли > 0
                ? Ok($"снял брони: {сняли} предм. — всё легло в сумки")
                : Fail("снять нечего или некуда: брони на боте нет, " +
                       "либо в сумках не нашлось свободного места"));
        }
        catch (Exception e)
        {
            return HttpAnswer.Json(Fail($"снять броню не вышло: {e.Message}"));
        }
    }

    /// <summary>
    /// ВЗЯТЬ ВЫБРАННУЮ ВЕЩЬ В РУКУ (или убрать её из левой руки).
    ///
    /// ЗАКАЗ ЗАКАЗЧИКА дословно: «нет кнопки его надеть» — про фонарь, который
    /// бот носит в левой руке. Надеть фонарь нельзя (это ни одежда, ни броня, и
    /// реестр игры так и отвечает), а вот ВЗЯТЬ В РУКУ — можно, и в игре это
    /// делается мышью; кнопка здесь и есть замена перетаскиванию.
    ///
    /// ТЕЛО БЕРЁМ, И ЭТО НЕ ПЕРЕСТРАХОВКА. У руки тот же хозяин, что у тела
    /// (<see cref="BodyArbiter"/>): без очереди «оружие к ночи» отбирало бы
    /// вещь обратно через долю секунды, и человек видел бы, как его кнопка
    /// «не работает» (живой случай — спор за руку в журнале 16.08). Важность
    /// «приказ»: человек нажал и ждёт, но спасение жизни всё равно важнее.
    ///
    /// УСПЕХ — ТОЛЬКО ПО ФАКТУ ОТ СЕРВЕРА: и взятие в правую руку
    /// (<see cref="Hands.TakeToHandAsync(Func{SlotContent, bool}, CancellationToken)"/>),
    /// и перенос в левую (<see cref="HandLight.ToOffHandAsync"/>) отвечают по
    /// содержимому слота, а не по отправленному пакету.
    /// </summary>
    private async Task<HttpAnswer> HoldItemAsync(HttpRequest r)
    {
        var (инвентарь, место, код, беда) = Pointed(r);
        if (беда != null)
            return HttpAnswer.Json(Fail(беда));
        if (!bot.Joined)
            return HttpAnswer.Json(Fail("бот не в мире — брать некому"));

        string рука = (Field(Body(r), "рука") ?? "").Trim();
        if (рука is not ("правая" or "левая" or "убрать"))
            return HttpAnswer.Json(Fail(
                $"не понял, что за рука «{рука}»: жду «правая», «левая» или «убрать»"));

        // ЧТО ИМЕННО БРАТЬ, СПРАШИВАЕМ У СУМКИ, а не у страницы: её оставляют
        // открытой надолго, и вещи за это время переезжают. Присланный код —
        // только сверка (та же осторожность, что у рейса на склад)
        if (!bot.Self.Inventories.TryGetValue(инвентарь, out var слоты) ||
            место >= слоты.Length || слоты[место].Code is not { } что)
            return HttpAnswer.Json(Fail(
                $"в месте {место} инвентаря «{инвентарь}» ничего не вижу — брать нечего"));
        if (код is { Length: > 0 } && код != что)
            return HttpAnswer.Json(Fail(
                $"не беру: в месте {место} теперь {что}, а вы указывали на {код} — " +
                "вещи переехали, повторите выбор"));

        // ОТКАЗ ГОВОРИТ МЕХАНИЗМ, а не окно, и теми же словами, что стоят под
        // серой кнопкой: иначе кнопка обещала бы одно, а бот делал другое
        if (рука == "правая" && bot.Hands.WhyToHand(инвентарь, место, что) is { Can: false } нет)
            return HttpAnswer.Json(Fail($"{что} в правую руку не беру: {нет.Why}"));
        if (рука == "левая" && bot.Light.WhyOffHand(инвентарь, место, что) is { Can: false } нетЛев)
            return HttpAnswer.Json(Fail($"{что} в левую руку не беру: {нетЛев.Why}"));

        using var hold = await bot.Context.Turn.TakeAsync($"взять {что} в руку из окна",
            BodyArbiter.Importance.Command, waitSeconds: 5);
        if (hold == null)
            return HttpAnswer.Json(Fail(
                $"взять {что} некогда: тело занято «{bot.Context.Turn.Busy}» — " +
                "остановите это дело или подождите"));

        try
        {
            // ЧТО ВЫШЛО — СПЕРВА ОДНИМ ОТВЕТОМ, а уже потом разбор конца.
            // Обрыв перебивает ЛЮБУЮ из трёх рук одинаково, и разбирать его
            // в каждой ветке значило бы завести три копии одного разбора
            (bool ладно, string слова) итог = рука switch
            {
                "убрать" => await bot.Light.ClearOffHandAsync(hold.Token)
                    ? (true, $"{что} убран из левой руки в сумку")
                    : (false, $"{что} из левой руки убрать не вышло — " +
                              "сервер перенос не показал (скорее всего, в сумках нет места)"),

                "левая" => await bot.Light.ToOffHandAsync(что, hold.Token)
                    ? (true, $"{что} в левой руке")
                    : (false, $"{что} в левую руку не переехал — сервер перенос не показал"),

                // ПРАВАЯ. Ищем по коду, а не по месту: разгребая хотбар, механизм
                // сам двигает стопки, и место, на которое показал человек, к концу
                // переезда бывает уже другим
                _ => await bot.Hands.TakeToHandAsync(
                        с => string.Equals(с.Code, что, StringComparison.Ordinal),
                        hold.Token) is { } n
                    ? (true, $"{что} в правой руке (место {n})")
                    : (false, $"{что} в правую руку не встал — сервер перенос не показал")
            };

            // ОБОРВАЛИ — ГОВОРИМ, КТО ИМЕННО, тем же общим правилом, что у
            // обхода склада и у рейса (см. Broke). Без этого кнопка молчала
            // ровно там, где спор за тело и ждали: у руки ТОТ ЖЕ хозяин, что
            // у тела, и в журнале 16.08 (13:04:59, 13:05:40) «бой» перебивал
            // соседние кнопки окна. Человек получал догадку «сервер перенос не
            // показал» — то есть неправду: сервер тут ни при чём, вещь не
            // переехала потому, что бота увели драться, и сам он к делу уже
            // не вернётся
            return HttpAnswer.Json(Broke(hold) is { } оборвали
                ? Fail($"{итог.слова}; {оборвали}")
                : итог.ладно ? Ok(итог.слова) : Fail(итог.слова));
        }
        catch (Exception e)
        {
            return HttpAnswer.Json(Fail($"взять в руку не вышло: {e.Message}"));
        }
    }

    /// <summary>
    /// ОТНЕСТИ ВЫБРАННУЮ ВЕЩЬ НА СКЛАД.
    ///
    /// А ВОТ ЗДЕСЬ ТЕЛО БЕРЁМ — рейс идёт ногами, и без очереди бот и наряд
    /// тянули бы его в разные стороны (то же, что и у обхода склада).
    ///
    /// НЕСЁМ ВСЁ ТАКОЕ, ЧТО ПРИ СЕБЕ, а не одну стопку: человек, показавший на
    /// кучку руды, имеет в виду руду. Сколько ушло на самом деле — в отчёте.
    /// </summary>
    private async Task<HttpAnswer> HaulItemAsync(HttpRequest r)
    {
        var (инвентарь, место, код, беда) = Pointed(r);
        if (беда != null)
            return HttpAnswer.Json(Fail(беда));
        if (!bot.Joined)
            return HttpAnswer.Json(Fail("бот не в мире — нести некому"));

        // Что именно нести, спрашиваем У СУМКИ, а не у страницы: она могла
        // устареть. Присланный код — только сверка
        if (bot.Self.Inventories.TryGetValue(инвентарь, out var слоты) is not true ||
            место >= слоты.Length || слоты[место].Code is not { } что)
            return HttpAnswer.Json(Fail(
                $"в месте {место} инвентаря «{инвентарь}» ничего не вижу — нести нечего"));
        if (код is { Length: > 0 } && код != что)
            return HttpAnswer.Json(Fail(
                $"не несу: в месте {место} теперь {что}, а вы указывали на {код} — " +
                "вещи переехали, повторите выбор"));

        using var hold = await bot.Context.Turn.TakeAsync($"отнести {что} на склад из окна",
            BodyArbiter.Importance.Command, waitSeconds: 5);
        if (hold == null)
            return HttpAnswer.Json(Fail(
                $"нести {что} некогда: тело занято «{bot.Context.Turn.Busy}» — " +
                "остановите это дело или подождите"));

        // НАДЕТОЕ СПЕРВА СНИМАЕМ. Склад берёт груз ТОЛЬКО ИЗ СУМОК (Depot идёт
        // по CarrySlots), а человек вправе показать на кирасу, которая сейчас
        // на боте, — и «armor… при мне нет» было бы враньём при надетой кирасе.
        // Снимает тот же единственный механизм, что и холод, и он тоже
        // проверяет по факту: не вышло — говорим, а не несём пустоту
        if (инвентарь.StartsWith("character", StringComparison.Ordinal) &&
            !await bot.Cold.UndressSlotAsync(место, hold.Token))
            // ПОЧЕМУ НЕ СНЯЛОСЬ — ДВЕ РАЗНЫЕ БЕДЫ, И ОДНИМ СЛОВОМ ИХ НАЗЫВАТЬ
            // НЕЛЬЗЯ. Дверь снятия одна на всех (BodyHeat.UndressSlotAsync: её
            // же зовут холод и броня), и «не вышло» она отвечает и когда в
            // сумках нет места, и когда ЖДАТЬ подтверждения ей не дали —
            // оборвали по дороге. Здесь стояло одно «некуда»: перебей рейс
            // бой (журнал 16.08, 13:04:59), и человек читал про полные сумки
            // — про беду, которой нет, — а место в сумках проверено строкой
            // выше в самой двери и оказалось
            return HttpAnswer.Json(Fail(Broke(hold) is { } оборвали
                ? $"{что} снять не успел: {оборвали}"
                : $"{что} сейчас надет, а снять его некуда: в сумках нет свободного места"));

        try
        {
            var итог = await bot.Depot.HaulItemAsync(что, hold.Token);
            // ОБОРВАЛИ — ГОВОРИМ ОБ ЭТОМ. Живьём (13:04:59) рейс перебивал бой,
            // и человек видел в ответ только «отнёс 0», без единого слова о том,
            // кто помешал и вернётся ли бот к делу (см. Broke)
            return HttpAnswer.Json(Broke(hold) is { } оборвали
                ? Fail($"{итог.Reason}; {оборвали}")
                : итог.Success ? Ok(итог.Reason) : Fail(итог.Reason));
        }
        catch (Exception e)
        {
            return HttpAnswer.Json(Fail($"рейс на склад сорвался: {e.Message}"));
        }
    }

    /// <summary>
    /// ВЫКИНУТЬ ВЫБРАННУЮ ВЕЩЬ.
    ///
    /// Охрана «этого не бросаем» (Hands.IsKeepsake) тут НЕ судья: она бережёт
    /// бота от него самого, а здесь выбрал человек. Но и молчать нельзя —
    /// сколько чего ушло на землю, механизм говорит в журнал и сюда.
    /// </summary>
    private async Task<HttpAnswer> DropItemAsync(HttpRequest r)
    {
        var (инвентарь, место, код, беда) = Pointed(r);
        if (беда != null)
            return HttpAnswer.Json(Fail(беда));
        if (!bot.Joined)
            return HttpAnswer.Json(Fail("бот не в мире — выбрасывать некому"));

        try
        {
            var итог = await bot.Hands.ThrowAwayAsync(инвентарь, место,
                "по приказу из окна", код);
            return HttpAnswer.Json(итог.Success ? Ok(итог.Reason) : Fail(итог.Reason));
        }
        catch (Exception e)
        {
            return HttpAnswer.Json(Fail($"выбросить не вышло: {e.Message}"));
        }
    }

    /// <summary>
    /// Нейросеть для окна: поставщики списком и честный ответ «чего не хватает».
    ///
    /// САМОГО КЛЮЧА ЗДЕСЬ НЕТ И БЫТЬ НЕ МОЖЕТ. Снимок несёт только имя
    /// переменной окружения и «задан / не задан» (см. <see cref="AiProviders.Снимок"/>),
    /// а открытую в браузере страницу оставляют на весь вечер — окажись в ней
    /// ключ, он стал бы лежать на виду.
    /// </summary>
    private string AiState()
    {
        var настройки = KnobHelp.AiOf(bot.Role);
        var поставщики = AiProviders.Снимок();
        // ЧЕЙ КЛЮЧ РАБОТАЕТ — по каждой переменной отдельно и СЛОВАМИ. Снимок
        // выше отвечает только «переменная окружения задана»; после того как
        // окно научилось задавать ключ, этого мало: человек, у которого ключ
        // лежит и там и тут, обязан узнать, что платят НЕ ТЕМ, что он вписал
        var ключи = поставщики
            .Where(п => п.переменнаяКлюча.Length > 0)
            .Select(п => п.переменнаяКлюча)
            .Distinct(StringComparer.Ordinal)
            .Select(имя => new
            {
                переменная = имя,
                // «В окружении» здесь значит ЧУЖОЙ ключ — не тот, что задан в
                // окне. Свой сохранённый ключ окно кладёт в окружение процесса
                // сейчас же, и голый вопрос «задана ли переменная» ответил бы
                // ДА даже человеку, у которого её отродясь не было: он читал
                // бы «работает переменная, она старше» и шёл искать её по
                // системным настройкам (см. BotSecrets.ВОкруженииЧужой)
                вОкружении = Secrets.ВОкруженииЧужой(имя),
                вФайле = Secrets.Задан(имя),
                кто = BotSecrets.КтоСтарше(Secrets.ВОкруженииЧужой(имя), Secrets.Задан(имя))
            })
            .ToList();
        return JsonSerializer.Serialize(new
        {
            поставщики,
            // ГДЕ ЛЕЖИТ КЛЮЧ НА ДИСКЕ — вслух. «Куда ты его дел» — вопрос,
            // который человек задаёт про всё, что окно у него забрало
            ключи,
            файлКлючей = Secrets.Path,
            // У роли-копателя нейросети нет вовсе — это не беда, а правда:
            // раздел просто говорит, что настраивать нечего
            есть = настройки != null,
            чем = настройки?.Чем() ?? "",
            готов = настройки?.ГотовДумать() ?? false,
            чегоНеХватает = настройки?.ЧегоНеХватает() ?? [],
            какВключить = настройки?.КакВключить() ?? ""
        }, Json);
    }

    /// <summary>
    /// ЗАДАТЬ КЛЮЧ НЕЙРОСЕТИ ИЗ ОКНА — дверь ТОЛЬКО НА ВВОД.
    ///
    /// Заказчик просил прямо: «в вебформе и нужно задавать ключ». Это его
    /// машина и его решение; наше дело — сделать это так, чтобы ключ не
    /// расползся.
    ///
    /// ЧТО ЗДЕСЬ СДЕЛАНО, ЧТОБЫ ОН НЕ РАСПОЛЗСЯ:
    ///   • ответ НЕ СОДЕРЖИТ ключа ни в каком виде — ни значения, ни длины, ни
    ///     хвоста «…abc». Окно узнаёт только «задан / не задан» через /api/ai;
    ///   • в журнал уходит имя переменной и путь к файлу, а не ключ
    ///     (<see cref="BotSecrets.Запомнить"/>);
    ///   • в чат он не попадает никак: сюда не ведёт ни одна команда чата, а
    ///     ручкой роли ключ не становится — <see cref="RoleKnobs.LooksSecret"/>
    ///     держит секреты вне пресетов и вне окна настроек;
    ///   • переменная окружения СТАРШЕ: если она задана, сохранённое ляжет в
    ///     файл, но работать продолжит переменная, и окно об этом СКАЖЕТ.
    ///     Тем, у кого всё уже настроено окружением, не ломается ничего.
    ///
    /// ПУСТОЕ ЗНАЧЕНИЕ — ЭТО «ЗАБЫТЬ». У «убрать ключ» то же поле, что и у
    /// «задать»: второй кнопки для этого не нужно.
    ///
    /// ЗАПУЩЕННЫЙ БОТ КЛЮЧА НЕ ПОДХВАТИТ, и об этом говорится вслух. Клиент
    /// нейросети читает переменную ОДИН раз, когда его создают, — то есть при
    /// запуске бота (см. <c>ClaudeClient</c>). Промолчать тут значило бы
    /// оставить человека ждать думающего бота, который не думает.
    /// </summary>
    private HttpAnswer AiKeySet(HttpRequest r)
    {
        var body = Body(r);
        string переменная = (Field(body, "переменная") ?? "").Trim();
        if (переменная.Length == 0)
            переменная = AiProviders.Найти(KnobHelp.AiOf(bot.Role)?.Поставщик)?.ПеременнаяКлюча
                         ?? "";
        if (переменная.Length == 0)
            return HttpAnswer.Json(Fail(
                "не сказано, в какую переменную класть ключ, и у нынешнего поставщика " +
                "её нет. Имена переменных перечислены в списке поставщиков"));

        // ЧУЖОЕ ИМЯ СЮДА НЕ КЛАДЁМ. Иначе окно стало бы способом записать в
        // окружение бота ЛЮБУЮ переменную (PATH, VINTAGE_STORY, VSBOT_STATE) —
        // это уже не «задать ключ», а подмена запуска
        if (!AiProviders.Снимок().Any(п =>
                string.Equals(п.переменнаяКлюча, переменная, StringComparison.Ordinal)))
            return HttpAnswer.Json(Fail(
                $"«{переменная}» — не переменная ключа ни одного из поставщиков. " +
                "Класть в окружение бота что попало это окно не станет"));

        string? ключ = Field(body, "ключ");
        string сказано = Secrets.Запомнить(переменная, ключ);

        // Кладём в окружение СРАЗУ: роль, созданная после этого (смена роли,
        // переподключение), увидит ключ без перезапуска процесса
        var поставили = Secrets.ПоложитьВОкружение();

        string почему = BotSecrets.КтоСтарше(
            Secrets.ВОкруженииЧужой(переменная), Secrets.Задан(переменная));
        string ещё = поставили.Contains(переменная)
            ? " Уже запущенный клиент нейросети ключа не подхватит: он читает переменную " +
              "один раз, при создании, — перезапустите бота."
            : "";
        return HttpAnswer.Json(Ok($"{сказано}. {почему}.{ещё}"));
    }

    /// <summary>
    /// КТО КОГО ПЕРЕБИВАЕТ: способности бота списком по убыванию важности.
    ///
    /// ПРЯМАЯ ПРОСЬБА ЗАКАЗЧИКА — «вес важности, что над чем превалирует, так
    /// проще будет настроить бота». До этого веса были, а ВИДНЫ не были: в
    /// панели стояла строка «ВесаВажности», которую человек заполнял вслепую,
    /// не зная ни названий способностей, ни их нынешних чисел. Заполнить
    /// вслепую её нельзя — значит она и не заполнялась.
    ///
    /// Порядок здесь настоящий, тот самый, которым бот обходит способности
    /// (<see cref="BehaviorRunner.Ordered"/>), а не пересказ таблицы умолчаний.
    /// </summary>
    private string WeightsState(HttpRequest? r = null)
    {
        var способности = bot.Behaviors.Ordered;
        string ручка = WeightsKnobName();

        // ОТБОР СЧИТАЕТ БОТ, А НЕ СТРАНИЦА — ровно как поиск работы
        // (<see cref="PanelWorkFind"/>). Отбор ПРЯЧЕТ строки, и ошибка в нём
        // выглядит как «такой способности у бота нет»; проверить это можно
        // только стендом, а стенд достаёт до правила, а не до разметки
        double? от = Число(r?.Q("от"));
        double? до = Число(r?.Q("до"));
        string слово = (r?.Q("слово") ?? "").Trim();
        bool толькоИзменённые = r?.Q("изменённые") is "1" or "true";
        var видные = способности
            .Select((b, i) => (Место: i + 1, Способность: b))
            .Where(п => WeightOrder.Fits(
                new WeightRow(п.Способность.Title, п.Способность.Weight,
                    п.Способность.WeightFloor, BehaviorWeights.DefaultOf(п.Способность),
                    п.Способность.GetType().Name, п.Способность.WeightCeiling),
                от, до, слово, толькоИзменённые))
            .ToList();

        return JsonSerializer.Serialize(new
        {
            есть = способности.Count > 0,
            ручка,
            // ЧИСЛА ПОРОГОВ ГОВОРИТ БИБЛИОТЕКА, а не страница: подвинется
            // константа — подвинется и подпись в окне (BehaviorWeights.Marks)
            пороги = BehaviorWeights.Marks.Select(м => new
            {
                вес = м.Weight, имя = м.Name, что = м.About
            }),
            всего = способности.Count,
            показано = видные.Count,
            // Скрытое НАЗЫВАЕТСЯ ЧИСЛОМ и словами: молча укоротить список
            // значило бы дать человеку решить, что способности пропали
            скрыто = способности.Count - видные.Count,
            почемуПусто = WeightOrder.SayEmpty(видные.Count, способности.Count,
                от, до, слово, толькоИзменённые),
            // Почему подвинутое не переживёт перезапуск — СЛОВАМИ. Молча
            // терять настроенное нельзя: человек потратил на список вечер
            почему = ручка.Length > 0
                ? ""
                : $"у роли нет строковой настройки «{KnobHelp.WeightsKnob}», поэтому " +
                  "подвинутое подействует сейчас, но не запишется в пресет и не " +
                  "переживёт перезапуск бота",
            строка = ЧтоВРучкеВесов(),
            // МЕСТО СЧИТАЕТСЯ ДО ОТБОРА. Отбор прячет строки, но «еда третья
            // по важности» остаётся правдой и тогда, когда две первые скрыты:
            // покажи мы место в отобранном списке — еда стала бы «первой», и
            // человек прочёл бы, что важнее неё нет ничего
            способности = видные.Select(п => new
            {
                место = п.Место,
                имя = п.Способность.Title,
                код = п.Способность.GetType().Name,
                вес = п.Способность.Weight,
                пол = п.Способность.WeightFloor,
                // Бесконечность в JSON не кладут — «потолка нет» это 0
                потолок = double.IsFinite(п.Способность.WeightCeiling)
                    ? п.Способность.WeightCeiling : 0,
                // …и отдельным ответом, потому что ноль тут двусмыслен: окно
                // обязано нарисовать «потолка нет» пустотой, а не чертой на нуле
                потолокЕсть = double.IsFinite(п.Способность.WeightCeiling),
                заводской = BehaviorWeights.DefaultOf(п.Способность),
                изменён = Math.Abs(п.Способность.Weight -
                                   BehaviorWeights.DefaultOf(п.Способность)) > 1e-9,
                // «Выключена» надо видеть рядом с весом: способность может
                // стоять первой в списке и не делать НИЧЕГО — ровно так
                // «вещи после смерти» подключены всем и выключены у всех
                выключена = Выключена(п.Способность),
                что = KnobHelp.Short(KnobHelp.Clean(
                    XmlDocs.SummaryOfType(п.Способность.GetType())))
            })
        }, Json);
    }

    /// <summary>
    /// Выключена ли способность. У основы <see cref="BotBehavior"/> такого
    /// поля нет — оно заводится теми, кого можно выключить (сбор вещей после
    /// смерти), поэтому спрашиваем отражением и молчим, если поля нет.
    /// </summary>
    private static bool Выключена(BotBehavior b)
    {
        try
        {
            return b.GetType().GetProperty("Enabled",
                       BindingFlags.Public | BindingFlags.Instance)?.GetValue(b) is false;
        }
        catch
        {
            return false;
        }
    }

    /// <summary>Имя строковой ручки роли, куда пишутся веса. Пусто — такой нет.</summary>
    private string WeightsKnobName() =>
        bot.Role is { } role &&
        RoleKnobs.Of(role).Any(k => string.Equals(k.Name, KnobHelp.WeightsKnob,
            StringComparison.OrdinalIgnoreCase) && k.Kind == WorkFieldKinds.Text)
            ? KnobHelp.WeightsKnob
            : "";

    private string ЧтоВРучкеВесов() =>
        bot.Role is { } role
            ? RoleKnobs.Of(role).FirstOrDefault(k => string.Equals(k.Name, KnobHelp.WeightsKnob,
                StringComparison.OrdinalIgnoreCase))?.Value as string ?? ""
            : "";

    /// <summary>
    /// ПОДВИНУТЬ СПОСОБНОСТЬ В СПИСКЕ ВАЖНОСТИ — или сказать, почему нельзя.
    ///
    /// Принимает либо <c>{"name":"еда","move":"up"}</c> (кнопка «выше»), либо
    /// <c>{"name":"еда","weight":95}</c> (человек вписал число сам).
    ///
    /// Подвинутое уходит ДВУМЯ путями, и оба обязательны:
    ///   • сразу в способности бота — иначе «подвинул, а бот всё тот же»;
    ///   • строкой в ручку роли — иначе первое же изменение любой другой
    ///     настройки донесёт до бота прежние веса и молча вернёт всё назад
    ///     (роль доносит настройки ЦЕЛИКОМ, см. ApplyWeights).
    /// Ручки такой у роли может не быть — тогда говорим это вслух, а не делаем
    /// вид, что записали.
    /// </summary>
    private HttpAnswer SetWeight(HttpRequest r)
    {
        var body = Body(r);
        string имя = Field(body, "name") ?? "";

        // «Вернуть как было» для всего списка — это ПУСТАЯ строка весов, а не
        // перечисление сегодняшних умолчаний: завтрашняя правка таблицы в
        // библиотеке до прибитого числами бота уже не дошла бы
        if (Field(body, "move") == "reset")
        {
            string сброшено = bot.Behaviors.ApplyWeights("");
            string вПресет = "";
            if (bot.Role is { } роль && WeightsKnobName().Length > 0)
            {
                using var пусто = JsonDocument.Parse("\"\"");
                вПресет = RoleKnobs.Apply(роль, KnobHelp.WeightsKnob, пусто.RootElement.Clone())
                          is { } беда ? $" В пресет не записал: {беда}" : $" {SaveKnobs(роль)}";
            }
            OnLog?.Invoke($"[веса] {bot.Behaviors.Report()}");
            return HttpAnswer.Json(Ok($"{сброшено}. Порядок важности: " +
                                      $"{bot.Behaviors.Report()}.{вПресет}"));
        }

        if (имя.Trim().Length == 0)
            return HttpAnswer.Json(Fail("не сказано, какую способность двигать"));

        var строки = bot.Behaviors.Ordered
            .Select(b => new WeightRow(b.Title, b.Weight, b.WeightFloor,
                BehaviorWeights.DefaultOf(b), b.GetType().Name, b.WeightCeiling))
            .ToList();
        if (строки.Count == 0)
            return HttpAnswer.Json(Fail("способностей у бота нет — двигать нечего"));

        double вес;
        string? куда = Field(body, "move");
        if (куда is "up" or "down")
        {
            double? новый = WeightOrder.Moved(строки, имя, куда == "up", out string почему);
            if (новый == null)
                return HttpAnswer.Json(Fail(почему));
            вес = новый.Value;
        }
        else if (Field(body, "weight") is { } число &&
                 double.TryParse(число, System.Globalization.NumberStyles.Float,
                     System.Globalization.CultureInfo.InvariantCulture, out double заданный))
        {
            вес = заданный;
        }
        else
        {
            return HttpAnswer.Json(Fail("нужно либо «move»: «up»/«down», либо «weight»: число"));
        }

        int сколько = bot.Behaviors.SetWeight(имя, вес);
        if (сколько == 0)
            return HttpAnswer.Json(Fail($"«{имя}» — такой способности у бота нет"));

        // ПОЛ НАЗЫВАЕТСЯ ВСЛУХ и здесь: вписавший еде «5» получит 60 и должен
        // узнать об этом сразу, а не гадать, почему бот всё равно бросает
        // кирку и жуёт
        var стало = bot.Behaviors.Behaviors.FirstOrDefault(b =>
            string.Equals(b.Title, имя, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(b.GetType().Name, имя, StringComparison.OrdinalIgnoreCase));
        string пол = стало != null && вес < стало.WeightFloor
            ? $" Ниже {стало.WeightFloor:0.#} эта способность не опускается " +
              $"(просили {вес:0.#}) — иначе бот умрёт с едой в кармане."
            : стало != null && вес > стало.WeightCeiling
                ? $" Выше {стало.WeightCeiling:0.#} эта способность не поднимается " +
                  $"(просили {вес:0.#}) — иначе работа встанет над едой и лечением."
                : "";

        string строка = WeightOrder.Line(bot.Behaviors.Behaviors.Select(b =>
            new WeightRow(b.Title, b.Weight, b.WeightFloor,
                BehaviorWeights.DefaultOf(b), b.GetType().Name, b.WeightCeiling)));

        string записано;
        if (bot.Role is { } role && WeightsKnobName().Length > 0)
        {
            using var док = JsonDocument.Parse(JsonSerializer.Serialize(строка, Json));
            string? жалоба = RoleKnobs.Apply(role, KnobHelp.WeightsKnob, док.RootElement.Clone());
            записано = жалоба == null
                ? $" {SaveKnobs(role)}"
                : $" В пресет не записал: {жалоба}";
        }
        else
        {
            записано = $" В пресет не записал: у роли нет настройки «{KnobHelp.WeightsKnob}», " +
                       "поэтому до перезапуска это подействует, а после — нет";
        }

        OnLog?.Invoke($"[веса] {bot.Behaviors.Report()}");
        return HttpAnswer.Json(Ok($"порядок важности: {bot.Behaviors.Report()}.{пол}{записано}"));
    }

    // ---------------- автосохранение ----------------

    /// <summary>
    /// Записать настройки запуска в файл — или СКАЗАТЬ, почему не записал.
    ///
    /// Возвращается всегда строка, и она всегда доезжает до человека: и в
    /// ответ окна, и в журнал. Молчаливое «не сохранилось» — тот же дефект,
    /// что и молчаливый выход из навыка: со стороны оно неотличимо от
    /// «сохранилось», и человек узнаёт правду только на следующем запуске.
    /// </summary>
    /// <remarks>
    /// ТЕЛО ЖИВЁТ НЕ ЗДЕСЬ, и это не косметика. Настройки запуска пишет ещё и
    /// бот без окна (см. <see cref="PresetLibrary.ЗапомнитьРучки"/>: «!дом тут»
    /// на боте, поднятом без ключа --panel). Две записи разошлись бы в первый
    /// же вечер — разные отказы, разные слова человеку.
    /// </remarks>
    private string SaveConfig() => Presets.ЗаписатьНастройкиЗапуска(Config, OnLogSink);

    /// <summary>
    /// Журнал окна как обычный получатель строк. Событие само по себе передать
    /// нельзя, а общему записывающему нужно знать, куда говорить: у окна журнал
    /// виден человеку прямо в браузере.
    /// </summary>
    private void OnLogSink(string строка) => OnLog?.Invoke(строка);

    /// <summary>
    /// Снять ручки с ЖИВОЙ роли и положить их в тот пресет, который выбран
    /// сейчас.
    /// </summary>
    /// <remarks>
    /// ТЕЛО ЖИВЁТ НЕ ЗДЕСЬ — в <see cref="PresetLibrary.ЗапомнитьРучки"/>, и
    /// там же выписано, почему оно оттуда уехало: ручки крутят тремя дверями
    /// (окно, «!дом тут», «!склад тут»), а бот без окна записать сказанное
    /// словом не мог вовсе. Библиотека пресетов есть у бота всегда, окно — нет.
    /// </remarks>
    private string SaveKnobs(BotRole role) =>
        Presets.ЗапомнитьРучки(role, Config, Roles, OnLogSink);

    /// <summary>Записать очередь задач. Как и всё остальное — вслух.</summary>
    private string SaveJobs()
    {
        if (JobsStore is not { } store || Plan is not { } plan)
            return "файл очереди к окну не подключён — на диск не записал";
        try
        {
            store.Save(plan);
            return $"очередь записана в {store.Path}";
        }
        catch (Exception e)
        {
            string beda = $"очередь НЕ записана ({e.Message})";
            OnLog?.Invoke(beda);
            return beda;
        }
    }

    // ---------------- что делаем ----------------

    private async Task<HttpAnswer> SayAsync(HttpRequest r)
    {
        string? text = Field(Body(r), "text");
        if (string.IsNullOrWhiteSpace(text))
            return HttpAnswer.Json(Fail("нечего говорить"));
        if (!bot.Joined)
            return HttpAnswer.Json(Fail("бот ещё не в игре"));
        await bot.SayAsync(text);
        return HttpAnswer.Json(Ok("сказал"));
    }

    private async Task<HttpAnswer> CommandAsync(HttpRequest r)
    {
        var body = Body(r);
        string? name = Field(body, "name");
        if (string.IsNullOrWhiteSpace(name))
            return HttpAnswer.Json(Fail("не сказано, какую команду"));

        // Тем же путём, что и чат: команда занимает тело у распорядителя,
        // и панель не дерётся с рефлексами выживания за одного бота
        string result = await bot.Commands.RunAsync("панель", name, Field(body, "args") ?? "");
        return HttpAnswer.Json(Ok(result));
    }

    private async Task<HttpAnswer> SkillAsync(HttpRequest r)
    {
        var body = Body(r);
        string? name = Field(body, "name");
        if (string.IsNullOrWhiteSpace(name))
            return HttpAnswer.Json(Fail("не сказано, какой навык"));

        // Запоминаем ДО пуска: событие о конце навыка несёт только имя и итог,
        // а в сводке хочется видеть и то, с чем его звали («добудь медь 20»)
        string args = Field(body, "args") ?? "";
        startedName = name;
        startedArgs = args;

        var result = await bot.Skills.RunAsync(name, args);

        // Навык мог и не начаться («занят другим») — тогда о конце никто не
        // сообщил, и оставленные аргументы прицепились бы к чужому запуску
        if (string.Equals(startedName, name, StringComparison.OrdinalIgnoreCase))
        {
            startedName = null;
            startedArgs = null;
        }

        return HttpAnswer.Json(result.Success
            ? Ok(result.Message ?? "готово")
            : Fail(result.Message ?? "не вышло"));
    }

    private HttpAnswer StopSkill()
    {
        // Гасим и навык, и ВОЗВРАТ к прерванному: без второго окно отвечало
        // «остановил», а бот, как только рефлекс отпускал тело, спокойно
        // докапывал план дальше (см. SkillRunner.CancelCurrent)
        bot.Skills.CancelCurrent("человек нажал «Остановить» в окне управления");
        return HttpAnswer.Json(Ok("остановил"));
    }

    private async Task<HttpAnswer> ToolAsync(HttpRequest r)
    {
        var body = Body(r);
        string? name = Field(body, "name");
        if (Tools?.FirstOrDefault(t => t.Name == name) is not { } tool)
            return HttpAnswer.Json(Fail($"нет такого умения: {name}"));

        JsonElement args = default;
        if (body.ValueKind == JsonValueKind.Object && body.TryGetProperty("args", out var a))
            args = a;

        string result = await tool.RunAsync(args, CancellationToken.None);
        return HttpAnswer.Json(Ok(result));
    }

    private HttpAnswer SetKnob(HttpRequest r)
    {
        if (bot.Role is not { } role)
            return HttpAnswer.Json(Fail("роль не выбрана"));

        var body = Body(r);
        string? name = Field(body, "name");
        if (string.IsNullOrWhiteSpace(name) ||
            body.ValueKind != JsonValueKind.Object || !body.TryGetProperty("value", out var value))
            return HttpAnswer.Json(Fail("нужно имя настройки и значение"));

        // ПОЛОВИНА ТОЧКИ — НЕ ТОЧКА. Живой случай: окно слало значение на
        // каждое движение в поле, и на бота уезжало «Склад = {x:1, y:0, z:0}»
        // — недописанная координата с нулями по незаполненным осям. Ноль по
        // оси это законное число, отличить его от «ещё не ввели» нельзя, —
        // значит недозаполненную клетку не применяем вовсе и говорим об этом.
        // Окно тоже так не делает, но защита нужна здесь: окно можно и обойти
        if (RoleKnobs.Of(role).FirstOrDefault(
                k => string.Equals(k.Name, name, StringComparison.OrdinalIgnoreCase))
            is { Kind: WorkFieldKinds.Cell } &&
            PanelSettings.WhyCellBad(value) is { } badCell)
            return HttpAnswer.Json(Fail($"настройка «{name}»: {badCell}"));

        string? complaint = RoleKnobs.Apply(role, name, value);
        if (complaint != null)
        {
            // ОТКАЗ ТОЖЕ ИДЁТ В ЖУРНАЛ. Раньше он жил одной секундой в углу
            // браузера: в журнал уходило только удавшееся. Разбор жалобы
            // заказчика 16.08 («настройку вроде включил») уткнулся ровно в это —
            // за все прогоны в журнале нет НИ ОДНОЙ строки про «БезДела», и
            // отличить «не набирал» от «набрал с опечаткой и получил отказ»
            // было нечем. Хозяин читает журнал, а не чужую вкладку
            OnLog?.Invoke($"{name} = {value} — НЕ ПРИНЯЛ: {complaint}");
            return HttpAnswer.Json(Fail(complaint));
        }

        // Приставку «[панель]» ставит тот, кто заводит журнал
        // (Program.cs: панель.OnLog += m => log.Write($"[панель] {m}")), и
        // вторая такая же здесь давала в журнале «[панель] [панель] Склад = …»
        OnLog?.Invoke($"{name} = {value}");

        // КОГДА ПОДЕЙСТВУЕТ — ПРО ЭТУ РУЧКУ, А НЕ «ПРО ЧАСТЬ НАСТРОЕК».
        //
        // ЖИВАЯ ПОТЕРЯ 23.08, слова заказчика: «хочется смену настроек и роли
        // без перезапуска». Здесь стояла приписка «часть настроек роль раздаёт
        // способностям при сборке — такие подействуют после перезапуска бота»,
        // и уходила она на КАЖДЫЙ поворот ЛЮБОЙ ручки, ни разу не называя, о
        // какой именно речь. А по факту роль доносит повёрнутое до механизма
        // сейчас же (RoleKnobs.Apply → BotRole.OnKnobsChanged), и человек
        // перезапускал бота после каждой правки без всякой нужды. Сказать
        // «перезапустите» там, где не надо, — тот же обман, что промолчать
        var когда = PanelWhenApplies.Knob(name, role.Name,
            PanelWhenApplies.CarriesKnobsLive(role.GetType()),
            KnobHelp.MarkOf(role.GetType(), name)?.AtStartOnly);
        if (когда.When != WhenApplies.Now)
            OnLog?.Invoke(когда.Why);

        // ЗАПИСЫВАЮЩИЙ ЗОВЁТСЯ НА КАЖДЫЙ ПОВОРОТ ЛЮБОЙ РУЧКИ, И ЭТО ВАЖНО ЗНАТЬ
        // ТОМУ, КТО СОБЕРЁТСЯ ДОПИСАТЬ ТУДА НОВОСТЬ. Всё, что записывающий
        // добавляет к ответу «постоянной» припиской, человек получает здесь по
        // разу на каждое движение мыши. Приёмка 31.08 поймала так приписку про
        // догадки бота; лечится она не здесь, а у самой новости — памятью
        // «сказано один раз» (PresetLibrary.сказаноПроДогадки), потому что
        // дверей к записывающему три, а не одна эта
        return HttpAnswer.Json(Ok($"{name} = {value}. {когда.Why}. {SaveKnobs(role)}"));
    }

    private HttpAnswer SavePreset(HttpRequest r)
    {
        if (bot.Role is not { } role)
            return HttpAnswer.Json(Fail("роль не выбрана — снимать нечего"));

        var body = Body(r);
        string id = Field(body, "id") ?? "";
        if (id.Trim().Length == 0)
            return HttpAnswer.Json(Fail("у пресета должно быть имя"));

        string roleId = Roles?.All.FirstOrDefault(e => e.Title == role.Name)?.Id
                        ?? Field(body, "role") ?? "standard";
        var preset = PresetLibrary.Capture(id.Trim(), roleId, role,
            Field(body, "title"), Field(body, "about"));
        Presets.Save(preset);
        return HttpAnswer.Json(Ok($"пресет «{preset.Id}» сохранён: {preset.SourcePath}"));
    }

    /// <summary>
    /// ВЫБРАН ГОТОВЫЙ БОТ. Пресет — это РОЛЬ плюс пачка ручек, и половины у
    /// него разной судьбы: ручки роль доносит до механизмов живьём, а роль
    /// выбирается один раз, при сборке бота.
    ///
    /// ЖИВАЯ ПОТЕРЯ 23.08, слова заказчика: «хочется смену настроек и роли без
    /// перезапуска». Здесь стояла ОДНА ветка на оба случая: что бы ни выбрали,
    /// панель писала выбор в bot.json и отвечала «перезапустите бота». То есть
    /// единственный способ загрузить в бота пачку настроек разом был отложен на
    /// 100 % — даже когда пресет собран ровно для той роли, которой бот сейчас
    /// и бежит, и менять там было нечего, кроме ручек.
    ///
    /// ПОЧЕМУ СНАЧАЛА СБРОС К ЗАВОДСКИМ, А НЕ ПРОСТО «НАЛОЖИТЬ ПОВЕРХ». Пресет
    /// перечисляет НЕ ВСЕ ручки роли (RoleKnobs.ApplyAll пишет только названные),
    /// а при запуске бот собирается иначе: сперва свежая роль из каталога, и уже
    /// на неё ложится пресет (PresetLibrary.Build). Наложи мы пресет поверх
    /// накрученного за вечер — «выбрать готового бота» давало бы в окне одно, а
    /// после перезапуска другое, и объяснить эту разницу было бы нечем. Сброс
    /// идёт тем же путём, что и кнопка «Вернуть как было»: заводское значение
    /// (RoleDefaults) обратно в ручку через RoleKnobs.Apply.
    /// </summary>
    private HttpAnswer ApplyPreset(HttpRequest r)
    {
        string id = Field(Body(r), "id") ?? "";
        if (Presets.Find(id) is not { } preset)
            return HttpAnswer.Json(Fail($"пресета «{id}» нет"));

        // Выбранный пресет обязан пережить перезапуск: иначе «перезапустите
        // бота, чтобы он стал этим ботом» — пустое обещание, при следующем
        // старте поднимется прежний
        string saved = "";
        if (Config != null)
        {
            Config.Preset = preset.Id;
            saved = " " + SaveConfig() + ".";
        }

        // …А ЕСЛИ ПЕРЕЗАПУСК ЭТОГО НЕ ПОДНИМЕТ — СКАЗАТЬ ЭТО ЗДЕСЬ, А НЕ ЖДАТЬ,
        // ПОКА ЧЕЛОВЕК ОБНАРУЖИТ ПРЕЖНЕГО БОТА.
        //
        // ЖИВАЯ ПОТЕРЯ 22.08. Заказчик выбрал в окне «trader», окно ответило
        // «записано, перезапустите бота», в bot.json вправду встало
        // "preset": "trader" — а запускает он бота через start-bot-panel.bat,
        // где стоит «--preset digger». Строка запуска сильнее файла, поднялся
        // прежний бот, и никто об этом не сказал ни слова. Со стороны это
        // ровно «настройки не запоминаются».
        //
        // Причина берётся ОДНА И ТА ЖЕ и здесь, и в первой строке журнала
        // запуска (BotConfig.Describe) — две разные формулировки одного отказа
        // человек читает как два разных отказа и не верит ни одному
        string? неЗапомнится = Config is { } c
            ? BotConfig.ПочемуНеЗапомнится(BotConfig.ИмяПресет, c.ИзСтрокиЗапуска)
            : null;

        string живаяРоль = bot.Role is { } живая ? RoleIdOf(живая) : "";
        var вид = PanelWhenApplies.PresetKind(живаяРоль, preset.Role);

        // ТА ЖЕ РОЛЬ — МЕНЯЮТСЯ ТОЛЬКО РУЧКИ, А ОНИ УМЕЮТ НА ЛЕТУ
        if (вид == PresetSwap.SameRole && bot.Role is { } роль)
        {
            var ответ = НакатитьПресетНаЖивого(роль, preset);
            OnLog?.Invoke($"[пресет] {ответ.Итог}");
            // ОТКАЗ ТОЖЕ ИДЁТ В ЖУРНАЛ, как и у одиночной ручки: хозяин читает
            // журнал, а не чужую вкладку браузера
            foreach (string строка in ответ.Жалобы.Concat(ответ.ВЖурнал))
                OnLog?.Invoke($"[пресет] {строка}");

            // Перезапуск здесь НЕ просим и события о нём не шлём: менять нечего,
            // роль та же. Ложная просьба перезапустить — тот же обман, что и
            // молчание: человек перестаёт верить окну.
            //
            // …НО ТО, ЧТО ВПРАВДУ ЖДЁТ ЗАПУСКА, НАЗЫВАЕТСЯ ПОИМЁННО — И ТЕМ ЖЕ
            // ПРАВИЛОМ, ЧТО У СМЕНЫ РОЛИ. У готового бота есть две половины
            // помимо ручек (отладочные команды и слово при входе), и обе читает
            // только запуск. Правило про них одно на оба случая: заведи мы
            // здесь второй список, он разошёлся бы со списком смены роли и
            // человек прочёл бы про один и тот же пресет два разных ответа
            return HttpAnswer.Json(Answer(true,
                ответ.Итог + Хвост(СменаРоли.ЧегоСменаНеДелает(
                    preset.Diag && Config is { Diag: false },
                    preset.Script, bot.Joined, неЗапомнится)) + saved,
                ответ.Жалобы));
        }

        // ДРУГАЯ РОЛЬ (или сравнить не с чем) — РУЧКИ НА ЖИВОГО НЕ НАКАТЫВАЕМ.
        // Настройки продавца, вкрученные в копателя, дали бы десяток жалоб «у
        // роли нет настройки» и один молча совпавший ключ, то есть наполовину
        // чужого бота.
        //
        // МЕНЯЕТ РОЛЬ НЕ ОКНО. Собрать роль из готового бота умеет библиотека
        // пресетов, а держат её окно и запуск ПОРОЗНЬ; роль же на боте одна.
        // Поэтому окно только зовёт того, кто держит бота, — через
        // OnRestartRequested, — а он собирает роль и зовёт bot.СменитьРоль
        // (VintageBotStory/Program.cs). Вторая сборка роли здесь разошлась бы
        // с первой в первый же вечер
        var итог = OnRestartRequested?.Invoke(preset.Id);

        // СМЕНИЛАСЬ ЛИ РОЛЬ — СПРАШИВАЕМ У БОТА, А НЕ ОБЕЩАЕМ. Событие
        // синхронное: к этой строке смена либо произошла, либо нет, и это
        // ФАКТ, который можно прочитать. «Роль сменена» на слово было бы тем же
        // «пакет отправлен» вместо «сервер подтвердил»
        string сталаРоль = bot.Role is { } теперь ? RoleIdOf(теперь) : "";
        bool сменилась = PanelWhenApplies.PresetKind(сталаРоль, preset.Role)
                         == PresetSwap.SameRole;

        // СМЕНИЛАСЬ — значит настройки пресета уехали В НОВУЮ роль: собирал её
        // из этого же пресета тот, кто держит бота. Сказать тут «настройки не
        // накатывал» было бы неправдой наоборот
        if (сменилась)
        {
            // «ПЕРЕЗАПУСК НЕ НУЖЕН» ГОВОРИТСЯ ТОЛЬКО ПО ФАКТУ ПОЛНОГО ОТКАТА.
            // Окно решало это по одному признаку — «другая ли теперь роль», —
            // а про итог.Целиком не знало вовсе: событие не возвращало ничего.
            // Выходило, что окно пишет «перезапуск не нужен», а бот в ту же
            // секунду пишет в журнал «бот сейчас полубот; перезапустите его».
            // Два противоположных ответа на одно нажатие — ровно тот обман,
            // ради снятия которого заказ и делался
            bool целиком = итог?.Целиком ?? true;
            string хвостОтката = итог is { Целиком: false } полу
                ? " ПРЕЖНЯЯ РОЛЬ ВЕРНУЛАСЬ НЕ ВСЯ — бот сейчас полубот, " +
                  $"перезапустите его: {string.Join("; ", полу.НеВернулось)}."
                : "";
            return HttpAnswer.Json(Answer(true,
                $"готовый бот «{preset.Id}» применён: роль сменил на ходу, " +
                $"«{живаяРоль}» → «{сталаРоль}»" +
                (целиком ? ", перезапуск не нужен." : ".") + хвостОтката +
                (итог is { Брошено.Count: > 0 } б
                    ? " Смена остановила: " + string.Join("; ", б.Брошено) + "."
                    : "") +
                Хвост(СменаРоли.ЧегоСменаНеДелает(
                    preset.Diag && Config is { Diag: false },
                    preset.Script, bot.Joined, неЗапомнится)) + saved,
                итог?.НеВернулось ?? []));
        }

        // Роль осталась прежней: сменить её некому (окно подняли без того, кто
        // держит бота) или сборка не удалась — причину бот сказал в журнал
        string почему = вид == PresetSwap.OtherRole
            ? $"готовый бот «{preset.Id}» собран для роли «{preset.Role}», а бот сейчас " +
              $"«{живаяРоль}» — на прежнюю роль его настройки не накатывал: они про другую."
            : $"готовый бот «{preset.Id}» выбран. Роли бота нет в каталоге — сравнить её " +
              $"с ролью «{preset.Role}» не с чем, и настроек на живого бота я не накатывал.";

        return HttpAnswer.Json(Ok(
            $"{почему}{saved} " +
            (неЗапомнится ?? "Роль на ходу не сменилась — остаётся " +
                             $"«{(сталаРоль.Length > 0 ? сталаРоль : "прежняя")}»; " +
                             "перезапустите бота, чтобы он стал этим ботом")));
    }

    /// <summary>
    /// Хвост «а вот этого сейчас не будет» — одной строкой и только когда есть
    /// что сказать. Пустой список молчит: приписка «ничего не упущено» под
    /// каждым ответом читается ровно как прежнее «перезапустите бота».
    /// </summary>
    private static string Хвост(IReadOnlyList<string> чего) =>
        чего.Count == 0 ? "" : " " + string.Join(" ", чего);

    /// <summary>Что вышло из горячего наката пресета.</summary>
    private readonly record struct ПресетНакачен(
        string Итог, IReadOnlyList<string> Жалобы, IReadOnlyList<string> ВЖурнал);

    /// <summary>
    /// НАКАТИТЬ ПРЕСЕТ НА ЖИВУЮ РОЛЬ: сперва вернуть к заводскому всё, чего
    /// пресет не называет, потом положить названное.
    ///
    /// Числа в ответе называются ВСЕ ТРИ (сброшено, применено, отвергнуто).
    /// Молчаливое «пресет применён» неотличимо от «применён наполовину» до того
    /// вечера, когда бот поведёт себя не так, как написано в файле.
    /// </summary>
    private ПресетНакачен НакатитьПресетНаЖивого(BotRole роль, RolePreset пресет)
    {
        var жалобы = new List<string>();
        var вЖурнал = new List<string>();

        // Имена, которые пресет называет сам. Без разбора регистра нельзя:
        // файл правят руками, и «Дом» с «дом» — одна и та же ручка
        var названо = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (пресет.Settings is { ValueKind: JsonValueKind.Object } настройки)
            foreach (var поле in настройки.EnumerateObject())
                названо.Add(поле.Name);

        int сброшено = 0;
        var заводские = RoleDefaults.Of(роль.GetType());
        if (заводские == null)
            жалобы.Add($"заводских значений роли «{роль.Name}» не знаю (у неё нет пустого " +
                       "конструктора) — накрученное раньше осталось как было, пресет лёг " +
                       "поверх него");
        else
            foreach (var ручка in RoleKnobs.Of(роль))
            {
                // Названное пресетом сбрасывать незачем: следующим же шагом
                // оно получит своё значение, а «сняли и поставили» дало бы
                // лишнюю строку в журнале про каждый снятый дом
                if (названо.Contains(ручка.Name) ||
                    !заводские.TryGetValue(ручка.Name, out object? было) ||
                    RoleDefaults.Same(ручка.Value, было))
                    continue;

                using var док = JsonDocument.Parse(JsonSerializer.Serialize(было, Json));
                if (RoleKnobs.Apply(роль, ручка.Name, док.RootElement) is { } жалоба)
                    жалобы.Add($"«{ручка.Name}» НЕ вернулась к заводскому: {жалоба}");
                else
                    сброшено++;
            }

        int применено = 0;
        if (пресет.Settings is { ValueKind: JsonValueKind.Object } поля)
        {
            применено = RoleKnobs.ApplyAll(роль, поля, out var беды, out var старые);
            жалобы.AddRange(беды);
            // Старое имя — это ПОДЕЙСТВОВАВШАЯ ручка, и в жалобы ей нельзя:
            // рядом стоит слово «отвергнуто», и это была бы прямая неправда
            вЖурнал.AddRange(старые);
        }

        // МЕСТА, НАЗВАННЫЕ ЧЕЛОВЕКОМ, СБРОС К ЗАВОДСКИМ НЕ УНОСИТ.
        //
        // Тремя строками выше «Дом» и «Склад», которых новый пресет не
        // называет, вернулись к заводскому — то есть в никуда. Для громкости
        // чата это правильно, а для дома нет: выбор другого готового бота не
        // означает «я передумал жить дома». Ровно этим у заказчика 27.08 и
        // пропал дом при переезде с «digger» на «resident» — оба на одной
        // роли, оба на одном сервере, а дом остался в чужом файле.
        //
        // Второй памяти тут не заводится: это тот же единственный зов
        // PresetLibrary.МестаНаРоль, каким места достаются роли при запуске.
        // Своей копии («только Подсказать») здесь стояло до 28.08 — и она уже
        // разошлась с запуском: подбирать места из самого пресета горячий накат
        // не умел, то есть после смены готового бота в окне память о доме
        // заводилась только со следующего перезапуска
        вЖурнал.AddRange(Presets.МестаНаРоль(роль, пресет.Id));

        // ЗАПИСЫВАТЬ РУЧКИ ОБРАТНО В ПРЕСЕТ ЗДЕСЬ НЕЧЕГО: только что накаченный
        // файл и так равен живой роли, и лишняя запись стоила бы человеку
        // перезаписи файла на ровном месте.
        //
        // РАСПУХНУТЬ ФАЙЛ БОЛЬШЕ НЕ МОЖЕТ, И ЭТО ПОЧИНЕНО НЕ ЗДЕСЬ. Приписка
        // тут обещала защиту, которой не было: строкой выше ставится
        // Config.Preset, а SetKnob на КАЖДЫЙ поворот зовёт SaveKnobs — и первый
        // же поворот дописывал в «ночной» все две сотни ручек. Настоящий ответ
        // лежит у снимка (PresetLibrary.Capture пишет только отличия от
        // заводского), а заглушка здесь оставила бы сломанным чат («!дом тут»
        // ходит тем же записывающим)
        string итог =
            $"готовый бот «{пресет.Id}» выбран и применён на живом боте, перезапуск не нужен: " +
            $"роль та же («{пресет.Role}»), настроек применено {применено}, " +
            $"возвращено к заводским {сброшено}" +
            (жалобы.Count > 0 ? $", отвергнуто {жалобы.Count}" : "") + ".";

        return new ПресетНакачен(итог, жалобы, вЖурнал);
    }

    // ---------------- аккаунт, подключение, читы ----------------

    /// <summary>
    /// Аккаунт и соединение — БЕЗ УКРАШЕНИЙ.
    ///
    /// «Вошёл» и «бот идёт под аккаунтом» — РАЗНЫЕ вещи, и панель их путать не
    /// должна. Живой случай: «Выйти из аккаунта» забывает сессию, но клиенту
    /// уже роздано имя аккаунта и добытчик одноразового токена — они живут до
    /// перезапуска. Окно говорило «не вошёл», а бот всё это время стучался
    /// в сервер под прежним именем. Поэтому рядом с «вошёл» едет
    /// <c>используется</c> — прицеплен ли аккаунт к соединению на самом деле.
    /// </summary>
    private string AccountState()
    {
        var сейчас = link;
        object? связь = сейчас == null ? null : new
        {
            что = сейчас.What,
            подробно = сейчас.Detail,
            когда = сейчас.When.ToString("HH:mm:ss")
        };

        return JsonSerializer.Serialize(new
        {
            доступен = Account != null,
            вошёл = Account?.Session is { Usable: true },
            используется = bot.Client.MpTokenProvider != null,
            имя = Account?.Session?.PlayerName ?? "",
            привилегии = Account?.Session?.Entitlements ?? "",
            почта = Config?.Account.Email ?? "",
            файлСессии = Account?.SessionPath ?? "",
            вИгре = bot.Joined,
            ник = bot.Name,
            хост = bot.Client.Host,
            порт = bot.Client.Port,
            парольСервераЗадан = bot.Client.HasServerPassword,
            связь
        }, Json);
    }

    /// <summary>
    /// Войти по почте и паролю.
    ///
    /// Пароль приходит сюда одним запросом и дальше НИГДЕ не задерживается:
    /// не в поле, не в файле, не в журнале. В ответ он тоже не возвращается —
    /// панель показывает только «вошёл» и имя игрока.
    /// </summary>
    private async Task<HttpAnswer> LoginAsync(HttpRequest r)
    {
        if (Account is not { } account)
            return HttpAnswer.Json(Fail("вход под аккаунтом в этом запуске не подключён"));

        var body = Body(r);
        string email = (Field(body, "email") ?? Config?.Account.Email ?? "").Trim();
        string password = Field(body, "password") ?? "";
        string code = (Field(body, "code") ?? "").Trim();

        // Готовая сессия из настроек установленной игры — пароль не нужен вовсе
        if (Field(body, "fromGame") is "true" or "1")
        {
            var takenFromGame = await account.SignInFromGameAsync();
            if (takenFromGame.Ok)
                account.Attach(bot.Client);
            return HttpAnswer.Json(takenFromGame.Ok ? Ok(takenFromGame.Message)
                                                    : Fail(takenFromGame.Message));
        }

        if (email.Length == 0)
            return HttpAnswer.Json(Fail("не заполнена почта"));

        var result = await account.SignInAsync(email,
            askPassword: () => Task.FromResult<string?>(password.Length > 0 ? password : null),
            askCode: _ => Task.FromResult<string?>(code.Length > 0 ? code : null));

        string saved = "";
        if (Config != null && result.Ok)
        {
            // Почта — не секрет, а пароля здесь нет и быть не может: в
            // BotAccountConfig под него нет поля вовсе
            Config.Account.Use = true;
            Config.Account.Email = email;
            saved = " " + SaveConfig() + ".";
        }
        if (result.Ok)
        {
            account.Attach(bot.Client);
            return HttpAnswer.Json(Ok(result.Message + "." + saved +
                " Токен подключения берётся заново на каждый вход — " +
                "чтобы он пошёл в дело, переподключитесь к серверу"));
        }

        // Сервер попросил код 2FA — это не ошибка, а второй шаг входа
        return HttpAnswer.Json(JsonSerializer.Serialize(new
        {
            ok = false,
            message = result.Message,
            нуженКод = result.Outcome is AuthOutcome.NeedTotp or AuthOutcome.NeedEmailCode
        }, Json));
    }

    private HttpAnswer Logout()
    {
        Account?.SignOut();

        // Честно про половинчатость: забыть сессию — не то же самое, что
        // «бот больше не под аккаунтом». Имя и добытчик токена уже у клиента
        // и останутся до перезапуска
        string хвост = bot.Client.MpTokenProvider != null
            ? $". Соединение всё ещё представляется как {bot.Name} — это до перезапуска бота"
            : "";
        return HttpAnswer.Json(Ok("вышел из аккаунта; сессия забыта" + хвост));
    }

    /// <summary>
    /// Панель просит подключиться. Это и есть «Вход» в окне.
    ///
    /// Здесь задаётся ВСЁ, чем бот представляется серверу: адрес, порт, пароль
    /// сервера и имя. Под аккаунтом имя берётся из аккаунта и переписать его
    /// нельзя — сервер сверяет его строго.
    /// </summary>
    private HttpAnswer BotConnect(HttpRequest r)
    {
        var body = Body(r);
        string host = (Field(body, "host") ?? Config?.Host ?? "127.0.0.1").Trim();
        string portText = Field(body, "port") ?? Config?.Port.ToString() ?? "42420";
        if (!int.TryParse(portText, out int port))
            return HttpAnswer.Json(Fail($"порт должен быть числом, а не «{portText}»"));

        if (!bot.Client.UseServer(host, port, Field(body, "password")))
            return HttpAnswer.Json(Fail(
                bot.Joined ? "бот уже в игре — сперва выйдите с сервера"
                           : $"негодный адрес: {host}:{port}"));

        // Имя: под аккаунтом оно НЕ наше, а серверa аккаунтов
        string? nickUsed = null, uidUsed = null;
        if (Account?.Session is { Usable: true })
        {
            Account.Attach(bot.Client);
        }
        else if (Field(body, "name") is { Length: > 0 } nick)
        {
            // Свой ник годится только там, где проверка аккаунта выключена.
            // Uid делаем из ника: сервер отличает игроков именно по нему
            nickUsed = nick.Trim();
            uidUsed = Field(body, "uid") is { Length: > 0 } uid
                ? uid.Trim()
                : "bot-" + BotFolders.SafeName(nick).ToLowerInvariant();
            bot.Client.UseAccount(nickUsed, uidUsed);
        }

        string saved = "";
        if (Config != null)
        {
            Config.Host = host;
            Config.Port = port;
            // Ник и uid раньше уходили ТОЛЬКО в клиента и умирали вместе с
            // запуском: человек вбивал их в окно каждый раз заново
            if (nickUsed is { Length: > 0 })
            {
                Config.Name = nickUsed;
                Config.Uid = uidUsed!;
            }
            // ПАРОЛЬ СЕРВЕРА СЮДА НЕ КЛАДЁТСЯ НИКОГДА: он прошёл насквозь в
            // bot.Client.UseServer и на этом кончился
            saved = ". " + SaveConfig();
        }

        bot.Client.AutoReconnect = true;
        OnConnectRequested?.Invoke();
        return HttpAnswer.Json(Ok($"подключаюсь к {host}:{port}" +
            (Account?.Session is { Usable: true } s ? $" под аккаунтом {s.PlayerName}" : "") +
            saved));
    }

    /// <summary>Панель просит войти на сервер (кнопка «Вход»).</summary>
    public event Action? OnConnectRequested;

    private HttpAnswer BotDisconnect(HttpRequest r)
    {
        bool comeBack = Field(Body(r), "comeBack") is "true" or "1";
        bot.Client.Disconnect("из окна управления", comeBack);
        return HttpAnswer.Json(Ok(comeBack ? "отключился, вернусь" : "вышел с сервера"));
    }

    private HttpAnswer BotReconnect()
    {
        // Разрыв с обещанием вернуться и есть переподключение: приёмный цикл
        // сам поднимет соединение заново
        bot.Client.Disconnect("переподключение из окна управления", comeBack: true);
        return HttpAnswer.Json(Ok("переподключаюсь"));
    }

    /// <summary>
    /// Читы: показываем ЖИВЫЕ значения флагов честности.
    ///
    /// Читы — не настройка вкуса, а отказ от правила «бот не делает того, чего
    /// не может живой игрок». Поэтому панель показывает их отдельной вкладкой
    /// и не прячет: включённый чит должен быть виден.
    /// </summary>
    private string CheatState()
    {
        var cheats = bot.Cheats;
        return JsonSerializer.Serialize(new
        {
            включены = cheats.Enabled,
            флаги = new object[]
            {
                new { имя = nameof(Cheats.Enabled), что = "главный выключатель: без него остальные не действуют", на = cheats.Enabled },
                new { имя = nameof(Cheats.SeeThroughWalls), что = "видеть блоки сквозь камень (руду в породе, чужие сундуки)", на = cheats.SeeThroughWalls },
                new { имя = nameof(Cheats.NoLineOfSight), что = "действовать без прямой видимости", на = cheats.NoLineOfSight },
                new { имя = nameof(Cheats.InfiniteReach), что = "дотягиваться дальше руки", на = cheats.InfiniteReach },
                new { имя = nameof(Cheats.InstantMining), что = "мгновенная добыча", на = cheats.InstantMining },
                new { имя = nameof(Cheats.IgnoreToolTier), что = "ломать без нужного инструмента", на = cheats.IgnoreToolTier },
                new { имя = nameof(Cheats.Teleport), что = "телепорт", на = cheats.Teleport },
                new { имя = nameof(Cheats.SeeInsideContainers), что = "видеть содержимое закрытых сундуков", на = cheats.SeeInsideContainers },
                new { имя = nameof(Cheats.NoFallDamage), что = "не получать урон от падения", на = cheats.NoFallDamage }
            }
        }, Json);
    }

    private HttpAnswer SetCheat(HttpRequest r)
    {
        var body = Body(r);
        string name = Field(body, "name") ?? "";
        bool on = Field(body, "on") is "true" or "1" or "True";
        var cheats = bot.Cheats;

        switch (name)
        {
            case nameof(Cheats.Enabled): cheats.Enabled = on; break;
            case nameof(Cheats.SeeThroughWalls): cheats.SeeThroughWalls = on; break;
            case nameof(Cheats.NoLineOfSight): cheats.NoLineOfSight = on; break;
            case nameof(Cheats.InfiniteReach): cheats.InfiniteReach = on; break;
            case nameof(Cheats.InstantMining): cheats.InstantMining = on; break;
            case nameof(Cheats.IgnoreToolTier): cheats.IgnoreToolTier = on; break;
            case nameof(Cheats.Teleport): cheats.Teleport = on; break;
            case nameof(Cheats.SeeInsideContainers): cheats.SeeInsideContainers = on; break;
            case nameof(Cheats.NoFallDamage): cheats.NoFallDamage = on; break;
            default: return HttpAnswer.Json(Fail($"нет такого чита: {name}"));
        }

        // Громко: включённый чит не должен пройти незамеченным
        OnLog?.Invoke($"[читы] {name} = {(on ? "ВКЛЮЧЁН" : "выключен")} из окна управления");

        // Читы тоже переживают перезапуск — хозяин просил не выбирать одно и
        // то же заново. Опасность этого («случайно осталось со вчера») закрыта
        // тем, что бот при старте называет вслух каждый поднятый из файла чит
        string saved = "";
        if (Config is { } c)
        {
            c.Cheats.CaptureFrom(cheats);
            saved = ". " + SaveConfig();
        }

        return HttpAnswer.Json(Ok(
            $"{name} {(on ? "включён" : "выключен")}" +
            (on && !cheats.Enabled
                ? ". Внимание: главный выключатель читов выключен — этот флаг не действует"
                : "") + saved));
    }

    // ---------------- память: серверный режим ----------------

    /// <summary>
    /// СКОЛЬКО ПАМЯТИ ЕСТ БОТ — числами, а не ощущением.
    ///
    /// Заказчик просил «чтобы на серверах лишнего не отжирала по оперативке»,
    /// и первое, чего не хватало, — величины: сколько чанков держится, сколько
    /// из них разжато и во что это обходится. Всё, что здесь показано,
    /// ПОСЧИТАНО по тому, что лежит (<see cref="WorldModel.Footprint"/>), а не
    /// прикинуто по формуле.
    ///
    /// Отдельной строкой — сколько выброшено и сколько забыто: уборка, о
    /// которой не сказали, неотличима от потери памяти.
    /// </summary>
    private string MemoryState()
    {
        var world = bot.World;
        var (чанков, разжато, сущностей, байт) = world.Footprint();
        // КАРТИНКИ — РЯДОМ С МИРОМ И ТЕМ ЖЕ СПОСОБОМ. Заказчик 17.08 спросил
        // прямо: «бот стал много жрать оперативки, это из-за иконок?» Ответить
        // один раз словами мало — картинок у него 18 560 и завтра будет больше.
        // Пусть обе величины стоят рядом и человек сравнивает их сам
        var (картинок, картинокБайт) = ItemIcons.Footprint();
        var набор = Config?.ServerMode;
        return JsonSerializer.Serialize(new
        {
            включён = набор?.Use ?? false,
            естьНастройки = Config != null,
            живое = new
            {
                чанков,
                разжато,
                сущностей,
                мегабайт = Math.Round(байт / 1024.0 / 1024.0, 2),
                картинок,
                картинокМб = Math.Round(картинокБайт / 1024.0 / 1024.0, 2),
                строкЖурнала = LogLines,
                // Управляемая куча всего процесса — для сравнения с моделью
                // мира: она показывает, какую долю занимает именно мир
                кучаМб = Math.Round(GC.GetTotalMemory(false) / 1024.0 / 1024.0, 1)
            },
            сделано = new
            {
                выброшеноСлоёв = world.DroppedDecodedLayers,
                забытоЧанков = world.ForgottenFarChunks
            },
            ручки = new object[]
            {
                new
                {
                    имя = "набор", вид = "флажок", значение = (object)(набор?.Use ?? false),
                    что = "серверный режим целиком. Пока выключен, остальные ручки здесь " +
                          "действуют только до перезапуска: в bot.json они лягут, но при " +
                          "следующем запуске не поднимутся — их поднимает сам серверный режим"
                },
                new
                {
                    имя = "радиус", вид = "число", значение = (object)world.KeepChunkRadius,
                    что = $"чанков вокруг бота ПО ГОРИЗОНТАЛИ: столько просим у сервера и столько " +
                          $"помним (1 чанк = {WorldModel.ChunkSize} бл, меньше {WorldModel.MinKeepChunkRadius} нельзя, " +
                          "0 — без предела). По высоте столб держим целиком: вертикального запроса " +
                          "в протоколе нет, и забытый слой сервер не пришлёт заново. " +
                          "Действует со следующего входа на сервер",
                    заберётЗнание = true
                },
                new
                {
                    имя = "разжатых", вид = "число", значение = (object)world.DecodedChunkBudget,
                    что = "сколько чанков держать разжатыми (0 — без предела). Один разжатый " +
                          "чанк — 128 КБ на слой блоков и столько же на воду. ЗНАНИЕ ПРИ ЭТОМ " +
                          "ЦЕЛОЕ: выброшенное разжимается заново из сжатых байтов",
                    заберётЗнание = false
                },
                new
                {
                    имя = "журнал", вид = "число", значение = (object)LogLines,
                    что = "строк журнала держать в окне (замерено 210 Б на строку)",
                    заберётЗнание = false
                },
                new
                {
                    имя = "подписи", вид = "флажок", значение = (object)Explanations,
                    что = "подписи к настройкам роли из файла документации (2,6 МБ). " +
                          "Выключены — окно скажет об этом, а не смолчит",
                    заберётЗнание = false
                }
            }
        }, Json);
    }

    /// <summary>
    /// Покрутить одну ручку памяти из окна.
    ///
    /// РАДИУС ЧЕСТНО ПРЕДУПРЕЖДАЕТ О ДВУХ ВЕЩАХ. Первое: он забирает знание —
    /// забытое место отвечает «не знаю», а не «там пусто». Второе: он уходит к
    /// серверу первым же пакетом опознания, поэтому на уже открытом соединении
    /// новый радиус применится только со следующего входа. Молчаливое «готово»
    /// тут было бы обманом: человек подумал бы, что память уже урезана.
    ///
    /// И ТРЕТЬЕ — ПРО ПЕРЕЗАПУСК, см. <see cref="ПереживётПерезапуск"/>.
    /// </summary>
    private HttpAnswer SetMemory(HttpRequest r)
    {
        var body = Body(r);
        string имя = (Field(body, "имя") ?? "").Trim();
        string значение = (Field(body, "значение") ?? "").Trim();
        bool на = значение is "true" or "1" or "True";
        var world = bot.World;
        var набор = Config?.ServerMode;

        string сказать;
        switch (имя)
        {
            case "набор":
                if (набор == null)
                    return HttpAnswer.Json(Fail(
                        "настройки запуска к окну не подключены — серверный режим живёт " +
                        "разделом serverMode в bot.json"));
                набор.Use = на;
                if (на)
                {
                    // Ручки набора применяем ТЕМ ЖЕ механизмом, что и при
                    // запуске: второго правила «что значит серверный режим» в
                    // проекте быть не должно
                    var сделано = набор.ApplyTo(world);
                    LogLines = набор.EffectivePanelLogLines > 0
                        ? набор.EffectivePanelLogLines : LogLines;
                    Explanations = набор.EffectiveDecorations;
                    if (!Explanations)
                        XmlDocs.Forget();
                    сказать = сделано.Count > 0
                        ? "серверный режим включён: " + string.Join("; ", сделано) +
                          $"; журнал в окне {LogLines} строк; подписи " +
                          (Explanations ? "оставлены" : "выключены") +
                          ". Радиус уйдёт к серверу при следующем входе"
                        : "серверный режим включён, но все его ручки стоят на «без предела» — " +
                          "экономить нечего";
                }
                else
                {
                    сказать = "серверный режим выключен. Уже урезанное само не вернётся: " +
                              "радиус и бюджет останутся стоять, поставьте им 0 или войдите заново";
                }
                break;

            case "радиус":
            {
                if (!int.TryParse(значение, out int n) || n < 0)
                    return HttpAnswer.Json(Fail($"радиус — целое число от 0, а не «{значение}»"));
                world.KeepChunkRadius = n;
                if (набор != null)
                    набор.ChunkRadius = world.KeepChunkRadius;
                сказать = world.KeepChunkRadius == 0
                    ? "радиус снят: мир помню весь, что прислали"
                    : $"радиус {world.KeepChunkRadius} чанк. " +
                      $"({world.KeepChunkRadius * WorldModel.ChunkSize} бл)" +
                      (n != world.KeepChunkRadius
                          ? $" — просили {n}, но меньше {WorldModel.MinKeepChunkRadius} нельзя: " +
                            "бот упирался бы в собственное незнание в трёх шагах"
                          : "") +
                      " по горизонтали, столб по высоте держу целиком. " +
                      "Что дальше — забуду честно: «не знаю», а не «пусто». " +
                      "К серверу это уйдёт при следующем ВХОДЕ на сервер: дальность " +
                      "просится первым пакетом опознания, на открытом соединении её не переспросить";
                break;
            }

            case "разжатых":
            {
                if (!int.TryParse(значение, out int n) || n < 0)
                    return HttpAnswer.Json(Fail($"бюджет — целое число от 0, а не «{значение}»"));
                world.DecodedChunkBudget = n;
                if (набор != null)
                    набор.DecodedChunks = n;
                int выброшено = world.DropColdDecoded();
                сказать = n == 0
                    ? "бюджет разжатых снят"
                    : $"разжатыми держу не больше {n} чанков (≈{n * 256 / 1024.0:0.#} МБ)" +
                      (выброшено > 0 ? $", сейчас выбросил {выброшено} слоёв" : "") +
                      ". Знание целое: выброшенное разожму заново";
                break;
            }

            case "журнал":
            {
                if (!int.TryParse(значение, out int n) || n < 10)
                    return HttpAnswer.Json(Fail(
                        $"строк журнала — целое число от 10, а не «{значение}»"));
                LogLines = n;
                if (набор != null)
                    набор.PanelLogLines = n;
                lock (logLock)
                    if (log.Count > LogLines)
                    {
                        // Начало кольца сдвинулось — сдвигаем и его номер, иначе
                        // закладка браузера снова показала бы на выброшенное
                        int cut = log.Count - LogLines;
                        log.RemoveRange(0, cut);
                        firstLine += cut;
                    }
                сказать = $"журнал в окне: {n} строк";
                break;
            }

            case "подписи":
                Explanations = на;
                if (набор != null)
                    набор.Decorations = на;
                if (!на)
                    XmlDocs.Forget();   // отпустить уже прочитанные 2,6 МБ
                сказать = на
                    ? "подписи к настройкам включены — файл документации прочтётся заново"
                    : "подписи к настройкам выключены и прочитанное отпущено (≈2,6 МБ)";
                break;

            default:
                return HttpAnswer.Json(Fail($"нет такой ручки памяти: {имя}"));
        }

        // ПРИПИСКА ПРО ПЕРЕЗАПУСК — ОДНА НА ВСЕ РУЧКИ НАБОРА И В ОДНОМ МЕСТЕ.
        // Сама ручка «набор» её не получает: она и есть тот переключатель,
        // о котором приписка говорит
        if (имя != "набор")
            сказать += ПереживётПерезапуск(набор);

        OnLog?.Invoke($"[память] {сказать}");
        string saved = Config != null ? ". " + SaveConfig() : "";
        return HttpAnswer.Json(Ok(сказать + saved));
    }

    /// <summary>
    /// ПЕРЕЖИВЁТ ЛИ ПОВЁРНУТАЯ РУЧКА ПЕРЕЗАПУСК — словами, всегда.
    ///
    /// Все ручки этой вкладки правят живого бота СЕЙЧАС и ложатся в bot.json.
    /// Но при следующем запуске их поднимает
    /// <see cref="ServerModeConfig.ApplyTo"/> (и рядом с ним
    /// <see cref="ServerModeConfig.EffectivePanelLogLines"/> и
    /// <see cref="ServerModeConfig.EffectiveDecorations"/>), а он первой же
    /// строкой выходит, когда серверный режим выключен: набор, применяемый
    /// наполовину, хуже невключённого.
    ///
    /// Отсюда и приписка. Без неё выходило прямое враньё: человек ставит радиус
    /// 3, читает «уйдёт при следующем входе», видит в окне, что чанков стало
    /// меньше, и уходит довольным, — а после перезапуска бот снова помнит всё
    /// и растёт как раньше, и понять это можно только сверив память руками.
    /// </summary>
    private static string ПереживётПерезапуск(ServerModeConfig? набор) =>
        набор == null
            ? ". Настройки запуска к окну не подключены — записать это некуда, " +
              "после перезапуска бот будет как был"
            : набор.Use
                ? ". Серверный режим включён — поднимется и при следующем запуске"
                : ". НО серверный режим ВЫКЛЮЧЕН: сейчас это действует и в bot.json ляжет, " +
                  "а при следующем запуске НЕ поднимется — включите ручку «набор»";

    // ---------------- задачи: конструктор и очередь ----------------

    private const string НетОчереди =
        "очередь задач в этом запуске к окну не подключена — некуда ставить";

    private const string НетКаталога =
        "ставить в очередь нечего: у роли нет ни одного вида работы, и бот не " +
        "объявил ни одного навыка";

    /// <summary>
    /// МЕНЮ ОЧЕРЕДИ: всё, что вообще можно поставить в очередь, — готовые виды
    /// работ роли и следом ВСЕ навыки бота без изъятия.
    ///
    /// Раньше здесь был только каталог роли, и человек упирался в стену: бот
    /// навык умеет, а поставить его в очередь нечем. Кто стоит за ключом,
    /// решает механизм (<see cref="WorkMenu"/>) — панель не знает ни видов
    /// работ, ни навыков и знать не должна.
    /// </summary>
    private string WorkList(HttpRequest? r = null)
    {
        var menu = Jobs?.Menu() ?? [];

        // ПОИСК ПО СЛОВУ ЧЕЛОВЕКА. Заказ из живого прогона: «команду копания
        // тоннеля в вебформе не могу найти» — работа звалась «Штольня до
        // точки». Подходит работа набранному слову или нет, решает ПРАВИЛО
        // (PanelWorkFind), а не страница: реши это страница своей формулой —
        // правило было бы не проверить стендом, а прячет оно ровно то, ради
        // чего человек и открыл окно
        string искали = (r?.Q("найти") ?? "").Trim();
        var подходит = menu.ToDictionary(k => k.Kind,
            k => PanelWorkFind.Matches(k.Title, k.About, k.SkillName, искали));
        int нашлось = подходит.Count(п => п.Value);

        return JsonSerializer.Serialize(new
        {
            подключено = Jobs != null,
            есть = menu.Count > 0,
            почему = Jobs == null ? НетОчереди : menu.Count == 0 ? НетКаталога : "",
            искали,
            нашлось,
            // Ничего не нашлось — это ОТВЕТ, а не пустой список: молча пустое
            // окно человек читает как «бот так не умеет», и в живом прогоне
            // прочёл именно так
            почемуПусто = искали.Length > 0 && нашлось == 0
                ? $"по слову «{искали}» ничего не нашлось — показываю всё, что бот умеет"
                : "",
            виды = menu.Select(k => new
            {
                имя = k.Kind,          // «карьер» или «навык:карьер»
                название = k.Title,
                навык = k.SkillName,
                что = k.About,
                готовый = k.Ready,     // true — поля роли, false — строка аргументов
                // Подошла ли работа набранному слову. Пусто в поиске — подходят
                // все: пустой поиск не должен прятать список
                подходит = нашлось == 0 || подходит[k.Kind],
                поля = k.Fields.Select(f => new
                {
                    имя = f.Name, вид = f.Kind, что = f.About, нужно = f.Required,
                    // ПОКАЗЫВАТЬ ТОЛЬКО ПРИ ЗАПОЛНЕННОМ СОСЕДЕ. Решает РОЛЬ
                    // (WorkField.OnlyWith), а не страница: заказчик 17.08 —
                    // «лишний пункт везде „что брать с собой“», и лишний он
                    // ровно там, где сундук-источник не задан
                    приЗаполненном = f.OnlyWith
                })
            })
        }, Json);
    }

    /// <summary>
    /// Очередь целиком. Вместе с каждой задачей едет ПРЕДПРОСМОТР
    /// (<see cref="WorkPrep"/>): что получится и почему не получится — тем же
    /// разбором, каким её будет пускать бегун. Отказ человек видит ДО того,
    /// как отправил бота копать, а не через сорок минут.
    /// </summary>
    private string JobList()
    {
        // ЧЕМ ЗАНЯТ ПРЯМО СЕЙЧАС — первой строкой и ВСЕГДА, даже когда очереди
        // в этом запуске нет. Ошибка заказчика: «в активных задачах сейчас не
        // показывается текущая задача». Шапка окна знала занятость («занят:
        // команда добудь»), а вкладка «Задачи» показывала только список
        // очереди — и приказ из чата в ней не появлялся вовсе
        object Сейчас(PanelNow н) => new
        {
            есть = н.Any,
            откуда = н.From switch
            {
                NowFrom.Queue => "из очереди",
                NowFrom.Outside => "со стороны",
                _ => ""
            },
            название = н.Title,
            навык = н.Skill,
            номер = н.Number,
            имя = н.Id,
            что = н.Reason
        };

        if (Jobs is not { } runner || Plan is not { } plan)
            return JsonSerializer.Serialize(new
            {
                подключено = false,
                почему = НетОчереди,
                // Дело со стороны идёт и без очереди — молчать о нём нельзя
                текущая = Сейчас(PanelNowLine.Of(bot.Context.Turn.Busy, bot.Skills.CurrentSkill)),
                задачи = Array.Empty<object>()
            }, Json);

        // Опрос из браузера идёт своим потоком, а бегун ровно в это время
        // может подменять склад временным сундуком. Уронить из-за этого весь
        // ответ окна нельзя, промолчать — тоже
        string storage;
        try
        {
            storage = runner.StorageNow;
        }
        catch (Exception e)
        {
            storage = $"сказать не берусь: склад прямо сейчас меняется ({e.Message})";
        }

        return JsonSerializer.Serialize(new
        {
            подключено = true,
            почему = "",
            файл = JobsStore?.Path ?? "",
            занят = runner.Busy,
            сейчас = runner.Current?.Id ?? "",
            // Имя дела берётся у ОЧЕРЕДИ НА ТЕЛО — той же строкой, что стоит в
            // шапке окна. Придумывать вкладке своё название нельзя: человек не
            // сможет сопоставить «занят: команда добудь» сверху с чем-то другим
            // в списке (см. PanelNowLine)
            текущая = Сейчас(PanelNowLine.Of(bot.Context.Turn.Busy, bot.Skills.CurrentSkill,
                runner.Current?.Name, runner.Current?.Id, plan.NumberOf(runner.Current?.Id))),
            хранилище = storage,
            сводка = plan.ToString(),
            // Номера, «идёт» и «следующая» считает ОЧЕРЕДЬ, а не панель:
            // выключенные задачи тоже занимают номер, и посчитай окно само —
            // «подвинуть третью» двигало бы не ту
            задачи = plan.Lines(runner.Current?.Id).Select(l =>
            {
                var prep = runner.Prep(l.Job);
                return new
                {
                    номер = l.Number,
                    имя = l.Id,
                    вид = l.Job.Skill,
                    название = l.Job.Title,
                    включена = l.Job.Enabled,
                    состояние = l.State,
                    отметка = l.Mark,      // «идёт» / «следующая» / пусто
                    вверх = l.CanUp,
                    вниз = l.CanDown,
                    итог = l.Job.Result,
                    попыток = l.Job.Attempts,
                    поля = l.Job.Fields,
                    готова = prep.Ok,
                    почемуНет = prep.Problem,
                    аргументы = prep.Args,
                    замечания = prep.Notes,
                    // СКОЛЬКО ЭТО ЗАЙМЁТ — тем же счётом, что и у конструктора
                    // (см. JobEta). Очередь из пяти задач без единого срока не
                    // говорит главного: успеет ли бот всё это до ночи
                    срок = runner.EtaOf(l.Job, prep) is { Seconds: { } с } оценка
                        ? $"{(оценка.AtLeast ? "не меньше " : "")}{Времена(с)}"
                        : ""
                };
            })
        }, Json);
    }

    /// <summary>
    /// Найти очередь и каталог, или сказать, чего не хватает.
    ///
    /// Каталог теперь МОЖЕТ быть пустым: свободная задача («навык:карьер»)
    /// ставится и без единого вида работы у роли, а отказывать из-за
    /// отсутствующего каталога значило бы запирать окно там, где механизм
    /// работает.
    /// </summary>
    private bool Ready([NotNullWhen(true)] out WorkPlan? plan,
        out WorkCatalog? catalog, out string why)
    {
        plan = Plan;
        catalog = Works;
        why = plan == null ? НетОчереди : "";
        return why.Length == 0;
    }

    private static JsonElement FieldsOf(JsonElement body) =>
        body.ValueKind == JsonValueKind.Object && body.TryGetProperty("fields", out var f)
            ? f
            : default;

    /// <summary>
    /// «СКОЛЬКО ЭТО ЗАЙМЁТ» — ДО ТОГО, КАК ЗАДАЧА ПОСТАВЛЕНА.
    ///
    /// ЖИВОЙ ПРОГОН 15.08: «выставление задач конструктором неудобно». Одна из
    /// причин неудобства — человек нажимал «Пустить» вслепую: карьер на десять
    /// минут и карьер на три часа выглядели в окне одинаково, и узнать, во что
    /// он ввязался, можно было только к ночи.
    ///
    /// СРОК СЧИТАЕТ БЕГУН (<see cref="WorkRunner.EtaOf"/>), а не окно, и это не
    /// придирка: в оценку идут замер прошлого захода, дорога до места и объём
    /// самой работы, и посчитай окно своей формулой — оно обещало бы одно, а
    /// бот делал другое. Задача при этом В ОЧЕРЕДЬ НЕ КЛАДЁТСЯ: спросить «во
    /// что обойдётся» человек вправе, ничего не запуская.
    ///
    /// Оценка честная и снизу: «не меньше», а не «ровно». Откуда взялось число
    /// — приходит теми же словами, какими бегун объясняет его в журнале.
    /// </summary>
    private HttpAnswer JobEta(HttpRequest r)
    {
        if (!Ready(out _, out var catalog, out string why))
            return HttpAnswer.Json(Fail(why));
        if (Jobs is not { } runner)
            return HttpAnswer.Json(Fail(НетОчереди));

        var body = Body(r);
        if (WorkChoice.Kind(catalog, Field(body, "kind"), runner.SkillNames, out string нельзя)
            is not { } kind)
            return HttpAnswer.Json(Fail(нельзя));

        // Собираем ТОЙ ЖЕ сборкой, что и постановка, — иначе окно считало бы
        // срок для одной задачи, а бот брал бы другую. Имя нарочно временное:
        // в очередь эта задача не попадает и номера не занимает
        var (job, problems) = kind.Compose("прикидка", Field(body, "title"), FieldsOf(body));
        var prep = runner.Prep(job);
        var срок = runner.EtaOf(job, prep);

        return HttpAnswer.Json(JsonSerializer.Serialize(new
        {
            ok = true,
            // Готова ли задача к пуску — тем же разбором, каким её возьмёт
            // бегун: «нет точки» человек обязан увидеть здесь, а не через
            // сорок минут ожидания
            готова = prep.Ok,
            почемуНет = prep.Problem,
            замечания = prep.Notes,
            жалобы = problems,
            секунд = срок.Seconds,
            неМеньше = срок.AtLeast,
            откуда = срок.Why,
            // Одной строкой — то, что человек читает не думая
            словами = срок.Seconds is { } с
                ? $"{(срок.AtLeast ? "не меньше " : "")}{Времена(с)}"
                : "сказать не берусь"
        }, Json));
    }

    /// <summary>
    /// ВО ЧТО ПРЕВРАТИТСЯ ЗАКАЗ — ПОКА ЧЕЛОВЕК ЕЩЁ НАБИРАЕТ ЗАДАНИЕ.
    ///
    /// ЗАКАЗЧИК ДОСЛОВНО: «лучше отображать в вебформе тоже, придумай красиво в
    /// конструкторе задачи». В чат бот это уже говорил до выхода — «медь ×20:
    /// считаю СЛИТКАМИ, 20 слитков — это 2000 ед. металла, около 134 кусков
    /// бедной руды». Но в окне человек НАБИРАЕТ задание, а слышал этот ответ
    /// уже после «Пустить»: поправить было нечего, оставалось ждать сорок минут
    /// и смотреть в сундук.
    ///
    /// НИ ОДНОГО ЧИСЛА ЗДЕСЬ НЕ СЧИТАЕТСЯ. Считает <see cref="OrderPreviews"/>
    /// тем же <see cref="Metals"/>, что ведёт наряд, — а этот берёт единицы
    /// металла из реестра сервера (плавка и metalUnits из ассетов игры).
    /// Единицу счёта называет <see cref="Ores.UnitFor"/>, то есть ручка роли
    /// плюс ответ реестра «а металл ли это». Откуда падает — реестр выпадений
    /// (<see cref="WorldModel.DropsOfBlock"/>) через <see cref="Errands.Sources"/>.
    /// Посчитай окно хоть одно из этих чисел само — оно обещало бы одно, а бот
    /// приносил бы другое.
    ///
    /// ЧТО РАЗБИРАТЬ, РЕШАЕТ РОЛЬ (<see cref="WorkKind.Ordered"/>): вещи она
    /// объявила видом поля, а не именем. Задача в очередь НЕ КЛАДЁТСЯ — спросить
    /// «во что это выльется» человек вправе, ничего не запуская (та же дверь,
    /// что и у оценки срока).
    /// </summary>
    private HttpAnswer JobPreview(HttpRequest r)
    {
        if (!Ready(out _, out var catalog, out string why))
            return HttpAnswer.Json(Fail(why));
        if (Jobs is not { } runner)
            return HttpAnswer.Json(Fail(НетОчереди));
        if (WorkChoice.Kind(catalog, Field(Body(r), "kind"), runner.SkillNames, out string нельзя)
            is not { } kind)
            return HttpAnswer.Json(Fail(нельзя));

        // Собираем ТОЙ ЖЕ сборкой, что и постановка: разбери окно поля по-своему
        // — оно показывало бы разбор одной задачи, а бот брал бы другую
        var (job, _) = kind.Compose("прикидка", null, FieldsOf(Body(r)));
        var строки = kind.Ordered(job);

        // ИМЯ РУЧКИ СПРАШИВАЕМ У РОЛИ, а не пишем здесь: «ВЧёмСчитатьМеталл» —
        // это ПОЛИТИКА копателя, другая роль назовёт её иначе. Ищется она по
        // ТИПУ (MetalCount), и тип принадлежит библиотеке
        string? ручка = RoleKnobs.NameOfType(bot.Role, typeof(MetalCount));

        return HttpAnswer.Json(JsonSerializer.Serialize(new
        {
            ok = true,
            // Ручка «в чём считать» — РЯДОМ с разбором, а не на другой вкладке:
            // увидев «слитки» там, где ждал штуки, человек обязан крутить это
            // тут же. Крутится она той же дверью /api/role/set, что и в
            // настройках роли: второго пути к настройкам у окна нет
            ручка,
            ручкаЗначение = ручка != null && bot.Role != null
                ? RoleKnobs.Of(bot.Role).FirstOrDefault(k => k.Name == ручка)?.Value?.ToString()
                : null,
            ручкаИзЧего = RoleKnobs.ChoicesOf(typeof(MetalCount)),
            почемуНетРучки = ручка == null
                ? $"у роли «{bot.Role?.Name ?? "без роли"}» нет настройки, в чём считать металл — " +
                  "считаю штуками того, что выпадет"
                : "",
            есть = строки.Count > 0,
            // ЗАКАЗЫВАЮТ ЛИ У ЭТОГО ДЕЛА ВЕЩИ ВООБЩЕ. Дороге и разгрузке
            // разбирать нечего, и место под разбор им не нужно: заказчик уже
            // жаловался на «лишний пункт везде», и пустая выноска у каждого
            // дела была бы ровно тем же самым
            заказывает = kind.Fields.Any(f => f.Kind is WorkFieldKinds.Thing
                                                     or WorkFieldKinds.Things),
            // Пустой разбор — это тоже ответ. Молча пустое место человек читает
            // как «окно сломалось» и жмёт «Пустить» вслепую
            почему = строки.Count > 0 ? "" : "что добывать, ещё не сказано",
            строки = строки.Select(строка =>
            {
                var разбор = OrderPreviews.Of(bot.Context, строка.What, строка.Count);
                return new
                {
                    что = разбор.Wanted,
                    сколько = разбор.Asked,
                    вЧёмСчитаю = разбор.Unit.ToString(),
                    единиц = разбор.Metal.Units,
                    металл = разбор.Metal.IsMetal,
                    // Одной строкой — ровно то, что бот скажет в чат перед
                    // выходом. Своей фразы у окна нет: человек, услышавший от
                    // бота одно, а прочитавший в окне другое, не поверит обоим.
                    // Без числа фразы не бывает: «медь ×0» — это не разбор
                    словами = разбор.Asked > 0 ? разбор.Say : "",
                    // Та же фраза без перечня вещей: перечень окно рисует
                    // строками с картинками (изЧего), и повторять его же ещё
                    // раз прозой значило бы писать одно и то же дважды
                    счётом = разбор.Asked > 0 ? MetalRules.Counted(разбор.Metal) : "",
                    код = разбор.Code,
                    имя = разбор.Name,
                    блок = разбор.IsBlock,
                    класс = ItemIcons.Of(разбор.Code, разбор.IsBlock).Kind,
                    картинка = разбор.Code.Length > 0 &&
                               ItemIcons.Of(разбор.Code, разбор.IsBlock).Has,
                    какПонял = разбор.Understood,
                    почему = разбор.Why,
                    // ЧЕМ НАБИРАТЬ: вещь, сколько в ней металла и сколько таких
                    // штук нужно. Числа — из ассетов игры (Metal.cs)
                    изЧего = разбор.Pieces.Select(п => new
                    {
                        код = п.Code,
                        имя = bot.Errands.Lang?.NameOf(п.Code) ?? "",
                        класс = ItemIcons.Of(п.Code, block: false).Kind,
                        картинка = ItemIcons.Of(п.Code, block: false).Has,
                        единиц = п.Units,
                        штук = п.Pieces,
                        как = п.How
                    }),
                    // ОТКУДА ЭТО БЕРЁТСЯ: блоки реестра, с которых оно падает
                    изБлоков = разбор.Blocks.Select(б => new
                    {
                        код = б.Code,
                        имя = б.Name,
                        класс = ItemIcons.Of(б.Code, block: true).Kind,
                        картинка = ItemIcons.Of(б.Code, block: true).Has
                    }),
                    всегоБлоков = разбор.BlocksTotal
                };
            })
        }, Json));
    }

    /// <summary>
    /// Секунды человеческим сроком. Минуты и часы, а не «4711 с»: срок нужен,
    /// чтобы решить «успею ли до ужина», и в секундах этого не видно.
    /// </summary>
    private static string Времена(double seconds)
    {
        if (seconds < 90)
            return $"{seconds:0} с";
        if (seconds < 3600)
            return $"{seconds / 60:0} мин";
        return $"{seconds / 3600:0.#} ч";
    }

    private HttpAnswer AddJob(HttpRequest r)
    {
        if (!Ready(out var plan, out var catalog, out string why))
            return HttpAnswer.Json(Fail(why));

        var body = Body(r);
        string? kindId = Field(body, "kind");
        if (WorkChoice.Kind(catalog, kindId, Jobs?.SkillNames, out string нельзя) is not { } kind)
            return HttpAnswer.Json(Fail(нельзя));

        // Имя задачи — то, чем её потом двигают и повторяют, поэтому оно
        // обязано быть свободным: два «карьера» в очереди означали бы, что
        // «убрать второй» убирает первый
        string wish = Field(body, "id") is { Length: > 0 } id ? id : kind.Id;
        var (job, problems) = kind.Compose(plan.FreeId(wish), Field(body, "title"), FieldsOf(body));
        plan.InsertAfter(job, Field(body, "после"));

        OnLog?.Invoke($"в очередь добавлена задача «{job.Name}» ({kind.Title})");
        // Имя задачи уходит наружу ОТДЕЛЬНЫМ полем, а не только в сообщении:
        // окно сразу после добавления умеет пустить её («пустить сейчас»), и
        // выковыривать имя из русской фразы для этого было бы гаданием
        return HttpAnswer.Json(JsonSerializer.Serialize(new
        {
            ok = true,
            id = job.Id,
            message = $"задача «{job.Name}» встала {plan.NumberOf(job.Id)}-й по очереди. {SaveJobs()}",
            жалобы = problems
        }, Json));
    }

    private HttpAnswer SetJob(HttpRequest r)
    {
        if (!Ready(out var plan, out var catalog, out string why))
            return HttpAnswer.Json(Fail(why));

        var body = Body(r);
        if (plan.Find(Field(body, "id")) is not { } job)
            return HttpAnswer.Json(Fail($"задачи «{Field(body, "id")}» в очереди нет"));
        if (WorkChoice.Kind(catalog, job.Skill, Jobs?.SkillNames, out string нельзя) is not { } kind)
            return HttpAnswer.Json(Fail(нельзя));

        // Собираем той же сборкой, что и при добавлении: одно правило разбора
        // полей в одном месте. Состояние и число попыток остаются задаче —
        // правка полей не делает вид, что задачи не было
        var (fresh, problems) = kind.Compose(job.Id, Field(body, "title") ?? job.Title,
            FieldsOf(body));
        job.Fields = fresh.Fields;
        job.Title = fresh.Title;

        return HttpAnswer.Json(Answer(true, $"задача «{job.Name}» изменена. {SaveJobs()}", problems));
    }

    private HttpAnswer MoveJob(HttpRequest r)
    {
        if (Plan is not { } plan)
            return HttpAnswer.Json(Fail(НетОчереди));

        var body = Body(r);
        string id = Field(body, "id") ?? "";
        bool moved;
        // «номер» — то, что человек видит в окне, и считается он с ЕДИНИЦЫ.
        // Внутренний indexOf с нуля наружу не показывается вовсе: увидев
        // «3» в списке и попросив «на 3», человек должен попасть туда, куда
        // показал, а не строкой выше
        if (Field(body, "номер") is { } numText && int.TryParse(numText, out int number))
            moved = plan.MoveTo(id, number);
        else if (Field(body, "to") is { } toText && int.TryParse(toText, out int to))
            moved = plan.Move(id, to);
        else if (Field(body, "by") is { } byText && int.TryParse(byText, out int by))
            moved = plan.Shift(id, by);
        else
            return HttpAnswer.Json(Fail("не сказано, куда двигать: нужно «номер», «to» или «by»"));

        return HttpAnswer.Json(moved
            ? Ok($"«{id}» теперь {plan.NumberOf(id)}-я по очереди. {SaveJobs()}")
            : Fail($"задачи «{id}» в очереди нет"));
    }

    /// <summary>
    /// Копия задачи. Живой случай: «тот же карьер, но на двадцать блоков
    /// восточнее» — набирать восемь полей заново незачем.
    /// </summary>
    private HttpAnswer CopyJob(HttpRequest r)
    {
        if (Plan is not { } plan)
            return HttpAnswer.Json(Fail(НетОчереди));
        string id = Field(Body(r), "id") ?? "";
        return HttpAnswer.Json(plan.Copy(id) is { } copy
            ? Ok($"копия «{copy.Id}» встала {plan.NumberOf(copy.Id)}-й по очереди. {SaveJobs()}")
            : Fail($"задачи «{id}» в очереди нет"));
    }

    private HttpAnswer RemoveJob(HttpRequest r)
    {
        if (Plan is not { } plan)
            return HttpAnswer.Json(Fail(НетОчереди));
        string id = Field(Body(r), "id") ?? "";
        return HttpAnswer.Json(plan.Remove(id)
            ? Ok($"задача «{id}» убрана. {SaveJobs()}")
            : Fail($"задачи «{id}» в очереди нет"));
    }

    private HttpAnswer EnableJob(HttpRequest r)
    {
        if (Plan is not { } plan)
            return HttpAnswer.Json(Fail(НетОчереди));
        var body = Body(r);
        if (plan.Find(Field(body, "id")) is not { } job)
            return HttpAnswer.Json(Fail($"задачи «{Field(body, "id")}» в очереди нет"));

        plan.Enable(job.Id, Field(body, "on") is "true" or "1" or "True");
        return HttpAnswer.Json(Ok(
            $"задача «{job.Name}» {(job.Enabled ? "включена" : "выключена")}. {SaveJobs()}"));
    }

    private HttpAnswer RepeatJob(HttpRequest r)
    {
        if (Plan is not { } plan)
            return HttpAnswer.Json(Fail(НетОчереди));
        var body = Body(r);
        if (Field(body, "id") is { Length: > 0 } id)
            return HttpAnswer.Json(plan.Repeat(id)
                ? Ok($"задача «{id}» снова ждёт своей очереди. {SaveJobs()}")
                : Fail($"задачи «{id}» в очереди нет"));

        int n = plan.RepeatAll();
        return HttpAnswer.Json(Ok($"снова ждут {n} задач. {SaveJobs()}"));
    }

    /// <summary>
    /// Пустить очередь или одну задачу. Ответ уходит СРАЗУ: очередь на вечер
    /// идёт часами, и держать браузер на этом запросе нельзя. О том, что
    /// происходит, рассказывает журнал бегуна и состояние задач.
    /// </summary>
    private HttpAnswer RunJobs(HttpRequest r)
    {
        if (Jobs is not { } runner || Plan is not { } plan)
            return HttpAnswer.Json(Fail(НетОчереди));
        if (runner.Busy)
            return HttpAnswer.Json(Fail(
                $"бегун занят задачей «{runner.Current?.Name}» — сперва остановите её"));

        string? id = Field(Body(r), "id");
        WorkItem? one = null;
        if (id is { Length: > 0 })
        {
            one = plan.Find(id);
            if (one == null)
                return HttpAnswer.Json(Fail($"задачи «{id}» в очереди нет"));
        }
        else if (!plan.Pending().Any())
        {
            // Пустить пустую очередь и промолчать — ровно то «стою без
            // причины», которое человек не может отличить от поломки
            return HttpAnswer.Json(Fail(
                "пускать нечего: ждущих и включённых задач в очереди нет. " +
                "Нажмите «повторить всё», если хотите пройти её заново"));
        }

        _ = Task.Run(async () =>
        {
            try
            {
                if (one != null)
                    await runner.RunAsync(one);
                else
                    await runner.RunAllAsync();
            }
            catch (Exception e)
            {
                OnLog?.Invoke($"очередь оборвалась ошибкой: {e.Message}");
            }
            finally
            {
                // Состояния задач менялись по ходу дела — очередь на диске
                // должна знать об этом, даже если по дороге что-то упало
                SaveJobs();
            }
        });

        return HttpAnswer.Json(Ok(one != null
            ? $"пустил задачу «{one.Name}»"
            : $"пустил очередь: {plan}"));
    }

    private HttpAnswer StopJobs()
    {
        if (Jobs is not { } runner)
        {
            // Очереди нет, но навык-то идёт — прервать его всё равно надо,
            // и сказать, что прервали именно его, а не очередь
            bot.Skills.CancelCurrent("человек остановил очередь из окна управления");
            return HttpAnswer.Json(Ok(
                "очередь к окну не подключена; прервал то долгое дело, что шло"));
        }
        runner.Stop();
        return HttpAnswer.Json(Ok("останавливаю: и навык, и шаги вокруг него"));
    }

    // ---------------- страница ----------------

    private static string? page;

    /// <summary>
    /// Страница лежит ВНУТРИ исполняемого файла: панель должна работать и
    /// тогда, когда бота скопировали одним файлом, и без выхода в сеть —
    /// никаких внешних библиотек со стороны.
    /// </summary>
    private static string Page()
    {
        if (page != null)
            return page;
        var assembly = Assembly.GetExecutingAssembly();
        string? name = assembly.GetManifestResourceNames()
            .FirstOrDefault(n => n.EndsWith("panel.html", StringComparison.Ordinal));
        if (name == null)
            return page = "<h1>Страница панели не вшита в сборку</h1>";
        using var stream = assembly.GetManifestResourceStream(name)!;
        using var reader = new StreamReader(stream);
        return page = reader.ReadToEnd();
    }
}

/// <summary>
/// ДОК-СТРОКИ СБОРКИ: объяснения настроек, написанные автором роли.
///
/// ЗАЧЕМ. Настройки роли называются «ОбходитьПередКопанием», «ПробиватьсяЧерез»,
/// «ДержатьсяОтЧужого» — и человеку это не говорит НИЧЕГО (прямая жалоба
/// заказчика: «нефига не понятно, что делают некоторые»). Объяснение при этом
/// уже написано — в док-строке над самим свойством, с живым случаем. Брать его
/// оттуда честно: оно не может разойтись с настройкой, потому что лежит
/// вплотную к ней.
///
/// ПОЧЕМУ НЕ СЛОВАРЬ В ПАНЕЛИ. Скопированные сюда тексты разъехались бы с
/// ролью в первый же вечер, и панель начала бы врать про настройку — а соврать
/// про настройку хуже, чем не подписать её. Выдумывать пояснения самой панели
/// запрещено тем же правилом.
///
/// ЧЕГО МЫ НЕ УМЕЕМ И ГОВОРИМ ВСЛУХ. Док-строки попадают в отдельный файл
/// «Сборка.xml» рядом со сборкой, и только если у проекта включено
/// &lt;GenerateDocumentationFile&gt;. Нет файла — <see cref="Problem"/> называет
/// это словами, и панель показывает голое имя, как раньше, а не выдумывает.
///
/// ГДЕ ЭТОТ ФАЙЛ ИСКАТЬ — <see cref="DocFile"/>, и это не мелочь. Отгружаем мы
/// бота ТОЛЬКО одним файлом (publish.sh, publish.bat), а у такой сборки
/// <c>Assembly.Location</c> ВСЕГДА пустой — файла на диске у неё нет.
/// Спрашивать путь у сборки значило бы выключить весь этот механизм ровно в
/// том виде, в котором его отдают человеку, — при том, что VsBotKit.xml и
/// VintageBotStory.xml лежат рядом с программой и прекрасно читаются.
/// </summary>
public sealed class XmlDocs
{
    private static readonly Dictionary<Assembly, XmlDocs> прочитанные = [];
    private static readonly Lock замок = new();

    private readonly Dictionary<string, string> summaries = new(StringComparer.Ordinal);

    private XmlDocs(string file, string? problem)
    {
        File = file;
        Problem = problem;
    }

    /// <summary>Файл, из которого читали (или должны были).</summary>
    public string File { get; }

    /// <summary>Почему объяснений нет. null — всё прочитано.</summary>
    public string? Problem { get; private set; }

    /// <summary>Сколько объяснений нашлось.</summary>
    public int Count => summaries.Count;

    /// <summary>
    /// Док-строки сборки. Читаются ОДИН раз: файл на несколько сотен свойств,
    /// а окно опрашивает настройки каждые пару секунд.
    /// </summary>
    public static XmlDocs For(Assembly assembly)
    {
        lock (замок)
        {
            if (прочитанные.TryGetValue(assembly, out var готовое))
                return готовое;
            var свежее = Read(assembly);
            прочитанные[assembly] = свежее;
            return свежее;
        }
    }

    /// <summary>Забыть прочитанное (пересборка роли на ходу, тесты).</summary>
    public static void Forget()
    {
        lock (замок)
            прочитанные.Clear();
    }

    private static XmlDocs Read(Assembly assembly)
    {
        string имя = assembly.GetName().Name ?? "роль";
        string? где = null;
        try
        {
            // IL3000: у сборки в однофайловом приложении Location пуст. Мы
            // именно это и разбираем ниже, поэтому предупреждение здесь
            // подавлено осознанно, а не заметено под ковёр
#pragma warning disable IL3000
            где = assembly.Location;
#pragma warning restore IL3000
        }
        catch
        {
            // Сборка, сгенерированная в памяти, на этот вопрос может и бросить
        }
        return FromFile(DocFile(где, имя, AppContext.BaseDirectory), имя);
    }

    /// <summary>
    /// ГДЕ ЛЕЖИТ ФАЙЛ ДОКУМЕНТАЦИИ — чистое правило, поэтому и проверяется тестом.
    ///
    /// ЕСТЬ ПУТЬ К СБОРКЕ — файл рядом с ней, то же имя с расширением .xml.
    /// Так собирают тесты и обычную сборку.
    ///
    /// ПУТИ НЕТ (пустая строка) — это НЕ «файла не существует», а однофайловое
    /// приложение: сборки в нём распакованы в память, и <c>Assembly.Location</c>
    /// у них всегда пуст. Отгружаем мы бота ровно так (publish.sh и publish.bat
    /// собирают ТОЛЬКО с -p:PublishSingleFile=true), а VsBotKit.xml и
    /// VintageBotStory.xml при этом кладутся рядом с программой. Значит искать надо от
    /// программы — <see cref="AppContext.BaseDirectory"/>; на это же указывает
    /// и сам компилятор предупреждением IL3000.
    ///
    /// Проверено запуском двух сборок одного кода: раньше однофайловая читала
    /// 0 объяснений при обоих файлах на месте, обычная — 4427. То есть в
    /// отгружаемом виде подписи к настройкам были выключены целиком.
    /// </summary>
    public static string DocFile(string? assemblyLocation, string assemblyName, string baseDirectory) =>
        assemblyLocation is { Length: > 0 } loc
            ? Path.ChangeExtension(loc, ".xml")
            : Path.Combine(baseDirectory, assemblyName + ".xml");

    /// <summary>
    /// Прочитать конкретный файл документации. Отдельно от
    /// <see cref="For"/> затем, что проверить разбор на стенде можно только
    /// так: подсунуть тестам настоящую сборку с документацией нельзя.
    /// </summary>
    public static XmlDocs FromFile(string? file, string assemblyName)
    {
        if (file == null)
            return new XmlDocs("", ЧтоДелать(assemblyName,
                "у сборки роли нет файла на диске (собрана в один файл или в память)"));
        if (!System.IO.File.Exists(file))
            return new XmlDocs(file, ЧтоДелать(assemblyName,
                $"рядом со сборкой нет файла {Path.GetFileName(file)}"));

        string рядом = file;
        var docs = new XmlDocs(рядом, null);
        try
        {
            var корень = XDocument.Load(рядом).Root?.Element("members");
            foreach (var член in корень?.Elements("member") ?? [])
            {
                string? ключ = член.Attribute("name")?.Value;
                var summary = член.Element("summary");
                if (ключ is { Length: > 0 } && summary != null)
                    docs.summaries[ключ] = Text(summary);
            }
            if (docs.summaries.Count == 0)
                docs.Problem = ЧтоДелать(assemblyName,
                    $"в файле {Path.GetFileName(рядом)} нет ни одного описания");
        }
        catch (Exception e)
        {
            docs.summaries.Clear();
            docs.Problem = $"объяснений настроек нет: файл {рядом} не читается ({e.Message})";
        }
        return docs;
    }

    /// <summary>
    /// ЧТО ЧЕЛОВЕКУ ДЕЛАТЬ — и мест здесь ДВА, а не одно. Раньше жалоба называла
    /// только &lt;GenerateDocumentationFile&gt;, и это был неверный диагноз: у
    /// VintageBotStory.csproj он включён, а объяснений всё равно не было — файл просто
    /// искали не там. Назвать одну причину из двух хуже, чем промолчать: человек
    /// проверит указанное, увидит, что там всё в порядке, и решит, что окно
    /// сломано вообще.
    /// </summary>
    private static string ЧтоДелать(string сборка, string почему) =>
        $"объяснений к настройкам нет: {почему}. Проверить надо два места. " +
        $"Первое: у проекта «{сборка}» должна стоять строка <GenerateDocumentationFile>true" +
        "</GenerateDocumentationFile>. Второе: получившийся файл " +
        $"{сборка}.xml должен ехать РЯДОМ С ПРОГРАММОЙ — внутрь однофайловой сборки он " +
        "не вкладывается. Пока его нет, окно показывает имена настроек как есть — " +
        "выдумывать за них объяснения я не буду";

    /// <summary>Описание свойства роли. null — такого описания нет.</summary>
    public string? Summary(Type type, string property)
    {
        // Свойство может быть объявлено не в самой роли, а в её основе
        // (LivingRole, BotRole): ключ док-строки называет ТОТ тип, где оно
        // написано, иначе половина настроек осталась бы без объяснения
        for (Type? t = type; t != null; t = t.BaseType)
            if (summaries.TryGetValue($"P:{t.FullName}.{property}", out string? text))
                return text;
        return null;
    }

    /// <summary>
    /// Описание свойства роли, взятое у ТОЙ сборки, где оно объявлено.
    ///
    /// Живой случай, ради которого это отдельно: «Дом», «ФонарьВРуке» и ещё
    /// дюжина ручек объявлены не в копателе, а в его основе — LivingRole из
    /// VsBotKit. Их описания лежат в VsBotKit.xml, а не в VintageBotStory.xml, и
    /// поиск по одному только файлу роли оставил бы половину настроек без
    /// подписи, причём молча.
    /// </summary>
    public static string? SummaryOf(Type roleType, string property)
    {
        for (Type? t = roleType; t != null; t = t.BaseType)
            if (For(t.Assembly).summaries.TryGetValue($"P:{t.FullName}.{property}", out string? text))
                return text;
        return null;
    }

    /// <summary>
    /// Описание САМОГО КЛАССА — им подписываются способности в таблице весов.
    ///
    /// Иначе в списке «кто кого перебивает» стояли бы двадцать голых слов
    /// («тепло», «упряжь», «сбор лежащего»), и человек двигал бы наугад то, о
    /// чём не знает. Текст — тот же, что у класса в исходнике: выдумывать
    /// пояснения способностям панель не станет, как не выдумывает их настройкам.
    /// </summary>
    public static string? SummaryOfType(Type? type)
    {
        if (type == null)
            return null;
        for (Type? t = type; t != null && t != typeof(object); t = t.BaseType)
            if (For(t.Assembly).summaries.TryGetValue($"T:{t.FullName}", out string? text))
                return text;
        return null;
    }

    /// <summary>
    /// Чего не хватает, чтобы объяснить настройки ЭТОЙ роли: по строке на
    /// каждую сборку из её родословной, где документации нет. Пусто — всё на
    /// месте.
    /// </summary>
    public static IReadOnlyList<string> Problems(Type roleType)
    {
        var беды = new List<string>();
        var видели = new HashSet<Assembly>();
        for (Type? t = roleType; t != null && t != typeof(object); t = t.BaseType)
        {
            if (!видели.Add(t.Assembly))
                continue;
            if (For(t.Assembly).Problem is { } беда)
                беды.Add(беда);
        }
        return беды;
    }

    /// <summary>Есть ли хоть одно описание для родословной этой роли.</summary>
    public static bool AnyFor(Type roleType)
    {
        for (Type? t = roleType; t != null && t != typeof(object); t = t.BaseType)
            if (For(t.Assembly).Count > 0)
                return true;
        return false;
    }

    /// <summary>Ключ док-строки свойства — то же, что пишет в файл компилятор.</summary>
    public static string KeyOf(Type type, string property) => $"P:{type.FullName}.{property}";

    /// <summary>
    /// Текст описания словами: ссылки «см. такое-то» превращаются в имя, на
    /// которое ссылаются, разметка выбрасывается, абзацы остаются абзацами.
    /// </summary>
    private static string Text(XElement element)
    {
        var текст = new System.Text.StringBuilder();
        Walk(element, текст);
        return текст.ToString();
    }

    /// <summary>
    /// ИМЯ, НА КОТОРОЕ ССЫЛАЮТСЯ, — человеку в окне нужно оно, а не путь с
    /// двоеточием: «P:VsBotKit.Depot.Chests» → «Chests».
    ///
    /// СПЕРВА ОТРЕЗАЕМ СКОБКИ. Здесь стояло голое «кусок после последней
    /// точки», и на ссылке НА МЕТОД С ДОВОДАМИ получалось вот что:
    ///     M:VsBotKit.ArmorKit.NeedGear(VsBotKit.VsBot,System.Boolean) → «Boolean)»
    /// Живьём человек читал в окне управления: «правило под ней ТО ЖЕ САМОЕ
    /// (Boolean))». Приёмка 27.08 померила по всем 656 ручкам четырёх ролей:
    /// 33 подписи были обрублены так — «Boolean)», «Int32)», «String)»,
    /// «Single)», «BlockPos)», — среди них «НоситьЩит» (дважды),
    /// «НоситьБроню», «ГретьсяДоТемпературы», «ФонарьВПещере», «ЧужиеНики».
    /// </summary>
    public static string ShortName(string cref)
    {
        int скобка = cref.IndexOf('(');
        string без = скобка >= 0 ? cref[..скобка] : cref;
        int точка = без.LastIndexOf('.');
        return точка >= 0 ? без[(точка + 1)..] : без.TrimStart('T', 'P', 'M', 'F', ':');
    }

    private static void Walk(XElement element, System.Text.StringBuilder куда)
    {
        foreach (var узел in element.Nodes())
        {
            switch (узел)
            {
                case XText t:
                    куда.Append(t.Value);
                    break;
                case XElement e when e.Name.LocalName is "see" or "seealso":
                    куда.Append(ShortName(e.Attribute("cref")?.Value ?? e.Value));
                    break;
                case XElement e when e.Name.LocalName == "para":
                    куда.Append('\n');
                    Walk(e, куда);
                    куда.Append('\n');
                    break;
                case XElement e:
                    Walk(e, куда);
                    break;
            }
        }
    }
}

/// <summary>
/// Раздел настроек: как его зовут внутри, как показать человеку и что в нём
/// лежит.
///
/// Третья строка (<paramref name="About"/>) появилась после ВТОРОЙ жалобы
/// заказчика («как-то визуально отсортируй настройки, непонятно же»). Одних
/// заголовков не хватило: «Работа» и «Прочее» не говорят, что искать внутри, и
/// человек всё равно открывал все разделы подряд. Это подсказка про МЕСТО, а не
/// про смысл настройки — смысл по-прежнему берётся только из её док-строки.
/// </summary>
public sealed record KnobSection(string Id, string Title, string About = "");

/// <summary>
/// ГДЕ ЖИВЁТ ЭТА НАСТРОЙКА — сказанное САМОЙ настройкой.
///
/// Зачем понадобилось. Раньше раздел выбирался таблицей слов в панели
/// (<see cref="KnobHelp.SectionOf"/>): «есть ли в имени „лава“, „руда“,
/// „склад“». Пока ручек было двадцать, это работало; на восьмидесяти таблица
/// начала врать — «ВесаВажности» и «ДержатьИнструменты» падали в «Прочее», а
/// «РадиусСбораЕды» уезжал в «Безопасность», потому что в нём есть слово «еды».
/// И главное: КАЖДАЯ НОВАЯ ручка сваливалась в «Прочее» до тех пор, пока
/// кто-нибудь не вспомнит про таблицу в чужом файле. Это ровно та беда, на
/// которую заказчик пожаловался второй раз.
///
/// Поэтому место — свойство самой настройки, стоящее рядом с ней:
/// <code>
///     [KnobPlace("работа", Order = 1, Main = true)]
///     /// &lt;summary&gt;Сторона карьера в блоках.&lt;/summary&gt;
///     public int РазмерКарьера { get; set; } = 7;
/// </code>
/// Ничего О СМЫСЛЕ настройки здесь не пишут: пояснение по-прежнему одно и
/// только одно — её док-строка. Здесь говорят лишь «где искать» и «насколько
/// часто это крутят».
///
/// Метки нет — панель не падает и не прячет ручку: раздел она угадает по
/// словам, как и раньше, а порядок возьмёт из <c>ГлавныеНастройки</c> роли.
/// </summary>
[AttributeUsage(AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
public sealed class KnobPlaceAttribute(string section) : Attribute
{
    /// <summary>Имя раздела: любое из <see cref="KnobHelp.Sections"/> или своё.</summary>
    public string Section { get; } = section;

    /// <summary>
    /// Название своего раздела для человека. Нужно только тому, кто завёл
    /// раздел, которого нет в общем списке: без названия человек увидел бы в
    /// заголовке внутреннее имя.
    /// </summary>
    public string Title { get; init; } = "";

    /// <summary>Одной строкой: что лежит в этом разделе (для своего раздела).</summary>
    public string About { get; init; } = "";

    /// <summary>
    /// Порядок внутри раздела: меньше — выше. 0 — «порядок не назван», и тогда
    /// ручка встаёт после названных, в порядке объявления в роли.
    /// </summary>
    public int Order { get; init; }

    /// <summary>
    /// Показывать сразу, не под «Показать всё». Ставится тому, за чем в панель
    /// и приходят: склад, размер карьера, «забирать вещи».
    /// </summary>
    public bool Main { get; init; }

    /// <summary>
    /// ЭТА РУЧКА НАСТРАИВАЕТСЯ НА ВКЛАДКЕ «НАСТРОЙКА РОЛИ» — ДАЖЕ ЕСЛИ ОНА
    /// ЕСТЬ У КАЖДОЙ РОЛИ.
    ///
    /// ЖИВАЯ ПРОСЬБА ЗАКАЗЧИКА, дословно: «сохранение склада и дома давай на
    /// одной странице настроек — в настройки роли». Обе точки живут в
    /// <c>LivingRole</c>, то есть есть у ВСЕХ ролей, — а вкладку окно делило
    /// одним-единственным признаком «своя ли ручка у роли»
    /// (<see cref="RoleCatalog.OnlyHere"/>: чего нет ни у кого другого). По
    /// этому признаку общая ручка своей не станет НИКОГДА, и «Дом» со
    /// «Складом» не попадали на названную вкладку НИ У ОДНОЙ роли. Заказчик
    /// назвал вкладку вслух — значит вкладка есть свойство самой ручки, и
    /// сказать об этом должна она сама, рядом с собой.
    ///
    /// ЭТО НЕ ВТОРОЙ ДЕЛИТЕЛЬ, А ТОТ ЖЕ САМЫЙ. Ответ «где эта ручка живёт в
    /// окне» собирается в одном месте — <see cref="KnobHelp.PlaceOf"/>, — и
    /// туда же входили раздел, порядок и «показывать сразу». Вкладка теперь
    /// оттуда же: страница только читает готовое поле и своих правил не
    /// заводит (до этой правки она держала своё исключение для раздела «ии» —
    /// его больше нет, ручки нейросети говорят о себе сами этой же меткой).
    ///
    /// ЧТО ЭТА МЕТКА НЕ ОТМЕНЯЕТ. «Своё у роли» остаётся тем же, чем было:
    /// настройка, которой нет у соседей. Метка не делает ручку «своей» и не
    /// врёт про неё в списке ролей — она отвечает на другой вопрос: ГДЕ ЕЁ
    /// КРУТЯТ. Ставить её надо скупо: вкладка роли тем и полезна, что на ней
    /// не сто ручек.
    /// <code>
    ///     [KnobPlace("склад", Order = 1, Main = true, RoleTab = true)]
    ///     public GamePos? Склад { get; set; }
    /// </code>
    /// </summary>
    public bool RoleTab { get; init; }

    /// <summary>
    /// ЭТА РУЧКА ПОДЕЙСТВУЕТ ТОЛЬКО ПРИ СЛЕДУЮЩЕМ ЗАПУСКЕ — и ВОТ ПОЧЕМУ,
    /// сказанное самой ручкой. Пусто (обычный случай) — подействует сейчас же,
    /// как только роль донесёт её до механизма.
    ///
    /// ЗАЧЕМ ЭТО НУЖНО. Роли доносят ручки живьём, и окно теперь честно говорит
    /// «подействовала сейчас». Но единицы ручек читаются РОВНО ОДИН РАЗ, при
    /// сборке бота: <c>LlmRole.РефлексыВыживания</c> решает, подключать ли
    /// рефлексы выживания, и снять уже подключённые нечем. Роль на нейросети
    /// жаловалась на это В ЖУРНАЛ (AiTraderRole.OnKnobsChanged), то есть туда,
    /// куда человек, крутящий ручку в браузере, не смотрит.
    ///
    /// Слова пишет тот, кто объявил ручку, и панель их не сочиняет: причина
    /// живёт рядом с настройкой, а не таблицей исключений в чужом файле — по
    /// той же причине, по какой рядом с ней живёт и раздел.
    ///
    /// ОБРАЗЕЦ ЗДЕСЬ ПО-РУССКИ НАРОЧНО. Он стоял с английским именем ручки
    /// (<c>UseSurvivalReflexes</c>) и пережил переименование семи ручек ИИ —
    /// приёмка 27.08 назвала это третьей находкой: кто заведёт ручку по этому
    /// образцу, напишет латиницу и упрётся в сторож
    /// «у роли ИИ ни одного английского имени ручки». Имена ручек в этом
    /// проекте русские, и образец обязан это показывать (закон 1).
    /// <code>
    ///     [KnobPlace("безопасность", Order = 40,
    ///         AtStartOnly = "рефлексы выживания подключаются один раз, при сборке бота")]
    ///     public bool РефлексыВыживания { get; set; } = true;
    /// </code>
    /// </summary>
    public string AtStartOnly { get; init; } = "";
}

/// <summary>
/// Куда встала настройка и КТО ЭТО РЕШИЛ.
/// </summary>
/// <param name="Section">Имя раздела.</param>
/// <param name="Order">Порядок внутри раздела: меньше — выше.</param>
/// <param name="Main">Показывать сразу, без «Показать всё».</param>
/// <param name="Source">
/// Чьё это решение: «настройка» (метка рядом с ней), «роль» (список
/// <c>ГлавныеНастройки</c>) или «догадка» (таблица слов в панели). Наружу идёт
/// затем, что «Прочее», набитое догадками, — это не свойство настроек, а
/// недоделка роли, и видно это должно быть сразу.
/// </param>
/// <param name="RoleTab">
/// Сама настройка сказала, что крутят её на вкладке «Настройка роли», хотя
/// она есть у всех ролей (<see cref="KnobPlaceAttribute.RoleTab"/>). Это
/// ПОЛОВИНА ответа про вкладку; вторая — «своё у роли» по каталогу, и
/// складывает их окно (<c>ControlPanel</c>), которому каталог известен, а
/// метке — нет.
/// </param>
public sealed record KnobPlace(string Section, int Order, bool Main, string Source,
    bool RoleTab = false);

/// <summary>
/// ОДНО МЕСТО В ОКНЕ, НА КОТОРОМ СТОИТ БОЛЬШЕ ОДНОЙ РУЧКИ.
///
/// Место — это пара «раздел + порядок», и занимать его двоим нельзя: панель
/// равные номера раскладывает как придётся, а человек, выучивший «безопасность,
/// третья сверху», после любой правки найдёт там соседку. Именно этим кончилось
/// расхождение семи настроек боя, названное в док-строке
/// <c>LivingRole.ДонестиОбщее</c>.
///
/// Имена идут ВСЕ и в том порядке, в каком их отдало отражение: человеку, чтобы
/// расселить пару, нужны обе стороны, а не «где-то в разделе безопасность».
/// </summary>
/// <param name="Section">Раздел окна.</param>
/// <param name="Order">Порядок внутри раздела — тот, что уехал бы в панель.</param>
/// <param name="Names">Ручки, претендующие на это место. Их всегда двое и больше.</param>
public sealed record KnobClash(string Section, int Order, IReadOnlyList<string> Names);

/// <summary>
/// ЗАВОДСКИЕ ЗНАЧЕНИЯ РОЛИ: с чем она рождается.
///
/// Зачем. Человек накрутил за вечер два десятка ручек и не помнит, какие
/// именно, — а «вернуть как было» без заводского значения невозможно.
/// Спросить их можно только у самой роли: свежая роль и есть тот самый
/// «заводской» набор. Выдумывать «разумные значения» нельзя — это была бы
/// ложь про роль, которую человек примет за правду.
///
/// Роль создаётся РОВНО ОДИН раз на тип и живёт в памяти: она ничего не знает
/// о боте, в мир не входит и в журнал не пишет — это просто объект с полями.
/// Не создалась (у роли нет пустого конструктора, конструктор упал) — честное
/// «заводских значений не знаю», а не подставленные нули.
/// </summary>
public static class RoleDefaults
{
    private static readonly Dictionary<Type, IReadOnlyDictionary<string, object?>?> известные = [];
    private static readonly Lock замок = new();

    private static readonly JsonSerializerOptions Ровно = new()
    {
        Encoder = JavaScriptEncoder.Create(UnicodeRanges.All)
    };

    /// <summary>Заводские значения ручек роли. null — узнать не вышло.</summary>
    public static IReadOnlyDictionary<string, object?>? Of(Type roleType)
    {
        lock (замок)
        {
            if (известные.TryGetValue(roleType, out var готовое))
                return готовое;
            var свежее = Make(roleType);
            известные[roleType] = свежее;
            return свежее;
        }
    }

    /// <summary>Забыть посчитанное (тесты, пересборка).</summary>
    public static void Forget()
    {
        lock (замок)
            известные.Clear();
    }

    private static IReadOnlyDictionary<string, object?>? Make(Type roleType)
    {
        try
        {
            if (Activator.CreateInstance(roleType) is not BotRole свежая)
                return null;
            return RoleKnobs.Of(свежая).ToDictionary(k => k.Name, k => k.Value);
        }
        catch
        {
            // У роли нет пустого конструктора или он требует живого бота.
            // Это не беда: панель просто не покажет «заводское» и не соврёт
            return null;
        }
    }

    /// <summary>
    /// То же ли это значение. Сравниваем ЗАПИСЬЮ, а не объектами: клетка
    /// приходит безымянным объектом {x,y,z}, и обычное сравнение сказало бы
    /// «разные» про две одинаковые точки — человек бы видел «изменена» там,
    /// где он ничего не трогал.
    /// </summary>
    public static bool Same(object? a, object? b)
    {
        try
        {
            return JsonSerializer.Serialize(a, Ровно) == JsonSerializer.Serialize(b, Ровно);
        }
        catch
        {
            return Equals(a, b);
        }
    }
}

/// <summary>
/// ЧИСТЫЕ ПРАВИЛА ПАНЕЛИ: те решения, цена ошибки в которых — не «неудобно»,
/// а «утекло» или «бот ушёл не туда».
///
/// Вынесены из <see cref="ControlPanel"/> отдельно потому, что панель без
/// живого бота не собрать, а проверять эти четыре правила надо: они про
/// секреты и про координаты.
/// </summary>
public static class PanelSettings
{
    /// <summary>
    /// Куда складывать накрученное, когда пресет не выбран.
    ///
    /// Заведённое имя, а не «никуда»: иначе накрученное за вечер пропадает при
    /// первом же перезапуске, и человек крутит одно и то же по третьему разу —
    /// ровно то, на что жаловался хозяин.
    /// </summary>
    public const string LastPreset = "последний";

    /// <summary>
    /// Можно ли автосохранять настройки запуска. null — можно; строка — готовая
    /// причина отказа для человека.
    ///
    /// <see cref="BotConfig.Save"/> пишет объект ЦЕЛИКОМ, поэтому автосохранение
    /// перенесло бы в файл токен или пароль, пришедшие аргументом запуска, —
    /// то есть ровно то, что человек передавал так, чтобы оно нигде не осело.
    /// </summary>
    public static string? WhySkipSave(BotConfig? config)
    {
        if (config == null)
            return "настройки запуска к окну не подключены — сохранять некуда";
        if (config.SecretsFromCommandLine)
            return "не сохраняю: токен или пароль сервера пришли аргументом запуска, а файл " +
                   "настроек пишется целиком — запись их на диск была бы утечкой. Уберите " +
                   "--token/--password из запуска или впишите значения в файл руками";

        // РАЗОВЫЙ КЛЮЧ ПРОГОНА НЕ СТАНОВИТСЯ ПОСТОЯННОЙ НАСТРОЙКОЙ ХОЗЯИНА —
        // И ЗАПРЕТА ЗАПИСИ ЗДЕСЬ ЗА ЭТО БОЛЬШЕ НЕТ.
        //
        // ЖИВАЯ ПОРЧА, РАДИ КОТОРОЙ ВСЁ ЗАТЕВАЛОСЬ. В bot.json заказчика стоит
        // «"directory": "…\\Temp\\claude\\…\\scratchpad\\botlog"» и стояло
        // «"openBrowser": false» — ни того, ни другого он не писал: чужие
        // прогоны шли с «--log-dir …» и «--no-browser», в окне повернулась одна
        // ручка, и файл, который пишется ЦЕЛИКОМ, унёс разовое в постоянное.
        //
        // ЗДЕСЬ ЭТОГО ЧИНИТЬ НЕЛЬЗЯ, И ВОТ ЦЕНА ПОПЫТКИ. Запрет «идёт с ключами
        // — не пишу» стоял в этой волне и ломал окно целиком: штатный
        // start-bot.bat подаёт «--diag», заводское значение диагностики — «нет»,
        // значит на свежей установке любой запуск батником отнимал у человека
        // запись ВСЕГО — выбора готового бота, хоста, порта, имени. Человек
        // выбирает бота, окно отвечает «не сохраняю», перезапуск поднимает
        // прежнего: дословно жалоба 22.08 «настройки не запоминаются».
        //
        // ПОЧИНЕНО ТАМ, ГДЕ БЕДА: <see cref="BotConfig.ТекстДляЗаписи"/> пишет
        // файл, но перебитым строкой запуска настройкам возвращает их ФАЙЛОВОЕ
        // значение — по ключам, а не по всему файлу. Что сбережено, человеку
        // говорит <see cref="BotConfig.ЧтоСбереженоПриЗаписи"/>.
        return null;
    }

    /// <summary>
    /// Что не так с клеткой, пришедшей из окна. null — точка полная.
    ///
    /// ЖИВОЙ СЛУЧАЙ. Окно слало значение, не дожидаясь конца ввода, и на бота
    /// уезжало «Склад = {"x":1,"y":0,"z":0}»: одна набранная цифра и нули по
    /// двум незаполненным осям. Ноль по оси — законное число, отличить его от
    /// «ещё не ввели» нельзя, поэтому незаполненная ось приходит пустой, а
    /// половина точки не применяется вовсе.
    /// </summary>
    public static string? WhyCellBad(JsonElement value)
    {
        // Значение целиком пустое — это «точку убрали», законное действие:
        // так снимают склад. От половины точки оно отличается тем, что
        // человек не ввёл НИЧЕГО, а не часть
        if (value.ValueKind is JsonValueKind.Null or JsonValueKind.Undefined)
            return null;

        if (value.ValueKind != JsonValueKind.Object)
            return "клетка задаётся тремя числами: {\"x\": …, \"y\": …, \"z\": …}";

        var empty = new List<string>();
        foreach (string axis in (string[])["x", "y", "z"])
        {
            bool ok = value.TryGetProperty(axis, out var v) && v.ValueKind switch
            {
                JsonValueKind.Number => v.TryGetInt32(out _),
                JsonValueKind.String => int.TryParse(v.GetString(), out _),
                _ => false
            };
            if (!ok)
                empty.Add(axis);
        }

        return empty.Count == 0
            ? null
            : $"точка заполнена не до конца (нет: {string.Join(", ", empty)}). Половину точки " +
              "я не применяю: незаполненная ось стала бы нулём, и бот ушёл бы не туда";
    }

    /// <summary>Пресет, в который ложатся накрученные ручки. Пусто — «последний».</summary>
    public static string KnobPreset(string? preset) =>
        preset is { Length: > 0 } p && p.Trim().Length > 0 ? p.Trim() : LastPreset;

    /// <summary>
    /// В каких координатах записана клетка-ручка. Пусто — сказать нечего, и
    /// врать не будем.
    ///
    /// Отличать обязательно: (258, 111, −260) и (512258, 111, 511740) — это
    /// одно и то же место, но в разных числах, и человек, подписавший поле
    /// неверно, введёт не то. Тип у них разный именно затем
    /// (<see cref="GamePos"/> против <see cref="BlockPos"/>), а вид ручки
    /// у обоих один — «клетка».
    /// </summary>
    public static string CoordsOf(Type? type)
    {
        if (type == null)
            return "";
        Type t = Nullable.GetUnderlyingType(type) ?? type;
        if (t == typeof(GamePos))
            return "игровые";
        if (t == typeof(BlockPos))
            return "мировые";
        return "";
    }

    /// <summary>
    /// Настройки БЕЗ СЕКРЕТОВ — то, что панель отдаёт наружу.
    ///
    /// Токен, пароль сервера и ключ сессии не уходят никогда: только «задан»
    /// или «нет». Иначе открытая в браузере страница становится местом, где
    /// лежит доступ, — а её оставляют открытой на весь вечер.
    /// </summary>
    public static object Public(BotConfig? config, string botName, string system,
        string? jobsFile = null)
    {
        var c = config;
        string? why = WhySkipSave(c);
        return new
        {
            хост = c?.Host ?? "",
            порт = c?.Port ?? 0,
            имя = c?.Name ?? botName,
            uid = c?.Uid ?? "",
            токенЗадан = !string.IsNullOrEmpty(c?.MpToken),
            парольСервераЗадан = !string.IsNullOrEmpty(c?.ServerPassword),
            аккаунт = c?.Account.Use == true,
            почта = c?.Account.Email ?? "",
            пресет = c?.Preset ?? "",
            отладка = c?.Diag ?? false,
            нейросеть = c?.Ai ?? false,
            // Карта — доп настройка, выключенная по умолчанию: окно обязано
            // знать её состояние, чтобы не рисовать вкладку молча пустой
            карта = c?.Panel.Map ?? false,
            картаЛюди = c?.Panel.MapPeople ?? false,
            // Адрес карты СЕРВЕРА — не секрет: это публичная страница, её и так
            // видно всем. Секретов в неё не подставляется никаких
            картаАдрес = c?.Panel.MapUrl ?? "",
            файл = c?.SourcePath ?? "",
            файлЗадач = jobsFile ?? "",
            автосохранение = why == null,
            почемуНет = why ?? "",
            система = system,

            // КОГДА ПОДЕЙСТВУЕТ КАЖДАЯ НАСТРОЙКА САМОГО БОТА — списком, а не
            // общей припиской внизу вкладки.
            //
            // ЗАЧЕМ. Настройки бота живут тремя разными жизнями: читы и карта
            // действуют сейчас же, адрес и аккаунт — со следующего входа на
            // сервер, а порт окна и журнал в файле читаются один раз при
            // запуске. Окно не говорило об этом НИЧЕГО, а половину из них не
            // показывало вовсе — и человек искал в браузере то, что правится
            // только руками в bot.json.
            //
            // Идут КОДЫ, а не готовые фразы: фразу окно составляет само и
            // переводит вместе со всей обстановкой
            когда = PanelWhenApplies.Settings.Select(н => new
            {
                имя = н.Name,
                когда = PanelWhenApplies.Code(н.When),
                где = PanelWhenApplies.Code(н.Where)
            })
        };
    }
}

/// <summary>
/// ПОМОЩЬ ПО НАСТРОЙКАМ: как показать ручку роли, чтобы человек понял, что она
/// делает.
///
/// ПРЯМАЯ ЖАЛОБА ЗАКАЗЧИКА: «настройки в вебформе надо шире расписать и как-то
/// удобнее что ли сделать, не юзерфрендли и нефига не понятно, что делают
/// некоторые». Три десятка ручек шли одной простынёй, подписанные именами
/// свойств: «ОбходитьПередКопанием», «ПробиватьсяЧерез», «ДержатьсяОтЧужого».
///
/// ГЛАВНОЕ ПРАВИЛО ЭТОГО КЛАССА: НИ ОДНО СЛОВО О СМЫСЛЕ НАСТРОЙКИ ЗДЕСЬ НЕ
/// ПРИДУМЫВАЕТСЯ. Объяснение берётся из док-строки самой настройки
/// (<see cref="XmlDocs"/>), единица измерения — только если ручка ЧИСЛОВАЯ и
/// мера НАЗВАНА в имени свойства или в его же описании, заводское значение — у свежей роли
/// (<see cref="RoleDefaults"/>). Всё, что здесь решается своей головой, —
/// расстановка по разделам и порядок показа: это подсказка, где искать, а не
/// утверждение о том, что настройка делает.
/// </summary>
public static class KnobHelp
{
    /// <summary>
    /// Имя ручки, в которой роль держит веса важности одной строкой. Панель
    /// пишет подвинутое ИМЕННО В НЕЁ, а не прямо в способности: настройки
    /// доносятся до механизмов целиком на каждый поворот ручки, и вес,
    /// поставленный мимо роли, был бы стёрт первым же изменением любой другой
    /// настройки.
    /// </summary>
    public const string WeightsKnob = "ВесаВажности";

    /// <summary>
    /// Разделы по порядку показа: от «за этим сюда и приходят» к «сюда
    /// заглядывают раз в месяц».
    ///
    /// У каждого — строка о том, что внутри. Без неё заголовки «Работа» и
    /// «Прочее» не помогали: человек открывал разделы подряд и жаловался
    /// второй раз.
    /// </summary>
    public static readonly IReadOnlyList<KnobSection> Sections =
    [
        new("работа", "Работа", "что копать, чем и как долго"),
        new("руда", "Поиск руды", "разведка, штреки, самородки"),
        new("склад", "Дом и склад", "куда носить добытое и где ночевать"),
        new("безопасность", "Безопасность", "еда, лечение, бегство, чужие клеймы"),
        new("люди", "Люди и чат", "приветствия, команды из чата, торговля"),
        new("время", "Время и скорость", "сроки, пороги, паузы"),
        new("ии", "Нейросеть", "характер, цель и правила бота, поставщик, модель, расходы"),
        new("прочее", "Прочее",
            "сюда попадает то, чего роль не разложила по разделам сама — " +
            "метка [KnobPlace] рядом с настройкой убирает её отсюда")
    ];

    /// <summary>
    /// ПРАВИЛА РАССТАНОВКИ ПО РАЗДЕЛАМ.
    ///
    /// Порядок строк важен: побеждает ПЕРВАЯ подошедшая. «ЛаваОстанавливает»
    /// говорит и про лаву, и про работу — человеку она нужна в «Безопасности»,
    /// поэтому опасность спрашивается раньше работы. «МинутНаНаряд» говорит и
    /// про минуты, и про наряд — она про работу, поэтому время спрашивается
    /// последним.
    ///
    /// Ошибка здесь стоит «настройка лежит не в том ящике», а не «панель
    /// соврала о том, что настройка делает»: смысла эти слова не сочиняют, и
    /// рядом с каждой ручкой стоит её собственное описание.
    /// </summary>
    private static readonly (string Id, string[] Слова)[] Правила =
    [
        // Нейросеть — первой: её ручки ни с чем не пересекаются, зато «модель»
        // и «усилие» утонули бы в «прочем»
        ("ии", ["поставщик", "модель", "усили", "потолокответа", "помнитьсообщен",
                "обращенийвчас", "токен", "цена", "валют", "нейросет", "промпт"]),

        // Опасность раньше работы: «лава», «смерть», «бегство» важнее того, что
        // в той же фразе сказано про копание
        ("безопасность", ["лав", "смерт", "погиб", "бегств", "бежать", "убега", "опасн",
                          "враг", "драк", "атак", "защит", "здоровь", "лечит", "голод",
                          "еда", "еды", "еду", "смелость", "осторожн", "выбира", "подъем",
                          "наверх", "столб", "стену", "стены", "завал", "упас", "паден",
                          "спуск", "спуса", "обрыв", "чужо", "избега", "клейм", "утоп"]),

        ("руда", ["руд", "жил", "самород", "разведк", "штрек", "обход", "прощуп",
                  "залеж", "минерал", "проспект"]),

        ("склад", ["склад", "сундук", "хранилищ", "дом", "разгруз", "сдавать", "ящик"]),

        ("работа", ["карьер", "копа", "кирк", "факел", "фонар", "крафт", "наряд", "добыч",
                    "добыва", "инструмент", "ломать", "работ", "строит", "дорог",
                    "полотн", "туннел", "мост", "лестниц", "материал", "запас"]),

        ("люди", ["здорова", "приветств", "махать", "игрок", "чат", "команд",
                  "встреч", "прощат", "люд", "эмоци", "торг", "магазин", "покупател"]),

        // Время — последним: «минут» встречается у половины ручек, и спроси мы
        // его раньше, «МинутНаНаряд» уехала бы из работы в скорость
        ("время", ["минут", "секунд", "часов", "суток", "дней", "порог", "задержк",
                   "пауз", "скорост", "часто"])
    ];

    /// <summary>
    /// В какой раздел положить настройку. Не узнали — «прочее»: это честнее
    /// натянутого раздела, в котором человек решит, что нашёл не то.
    /// </summary>
    public static string SectionOf(string? name, string? about = null) =>
        // СПЕРВА ИМЯ, И ТОЛЬКО ПОТОМ ОПИСАНИЕ. Живая причина: описания у ручек
        // длинные, с живыми случаями, и слово из рассказа перебивало слово из
        // имени. «ПомнитьЧасов» уезжала в «Поиск руды», потому что в её
        // рассказе встречалось «обход»; «ПокрытиеДороги» — туда же; половина
        // ручек оседала в «Безопасности» из-за слова «выберет». Имя ручки
        // человек написал коротко и по делу — ему и верим первым
        Найти(Слова(Words(name))) ?? Найти(Слова(about)) ?? "прочее";

    /// <summary>
    /// Правило ищется НАЧАЛОМ СЛОВА, а не куском строки.
    ///
    /// Живой случай: «СмотретьВодуПередПрямымХодом» уезжала в «Дом и склад»,
    /// потому что в слове «ходом» есть буквы «дом». Кусок строки ловит такое
    /// молча, и человек ищет настройку не в том ящике.
    /// </summary>
    private static string? Найти(IReadOnlyList<string> слова)
    {
        if (слова.Count == 0)
            return null;
        foreach (var (id, ключи) in Правила)
            foreach (string ключ in ключи)
                foreach (string слово in слова)
                    if (слово.StartsWith(ключ, StringComparison.Ordinal))
                        return id;
        return null;
    }

    /// <summary>Текст словами, одним регистром и без «ё».</summary>
    private static List<string> Слова(string? текст)
    {
        var слова = new List<string>();
        var буквы = new System.Text.StringBuilder();
        foreach (char c in Ровно(текст ?? ""))
        {
            if (char.IsLetterOrDigit(c))
                буквы.Append(c);
            else if (буквы.Length > 0)
            {
                слова.Add(буквы.ToString());
                буквы.Clear();
            }
        }
        if (буквы.Length > 0)
            слова.Add(буквы.ToString());
        return слова;
    }

    /// <summary>Одним регистром и без «ё»: «Ёмкость» и «емкость» — одно слово.</summary>
    private static string Ровно(string текст) =>
        текст.ToLowerInvariant().Replace('ё', 'е');

    /// <summary>
    /// Метка места, поставленная рядом с самой настройкой. null — не ставили.
    ///
    /// Ищем по всей родословной: половина ручек копателя объявлена не в нём, а
    /// в LivingRole, и метка стоит там же, где свойство.
    /// </summary>
    public static KnobPlaceAttribute? MarkOf(Type? roleType, string? name)
    {
        if (roleType == null || string.IsNullOrEmpty(name))
            return null;
        try
        {
            for (Type? t = roleType; t != null && t != typeof(object); t = t.BaseType)
            {
                var p = t.GetProperty(name, BindingFlags.Public | BindingFlags.Instance |
                                            BindingFlags.DeclaredOnly | BindingFlags.IgnoreCase);
                if (p?.GetCustomAttribute<KnobPlaceAttribute>() is { } mark &&
                    mark.Section.Trim().Length > 0)
                    return mark;
            }
        }
        catch (AmbiguousMatchException)
        {
            // Две ручки, различающиеся только регистром: чья это метка —
            // сказать честно нельзя, и мы не говорим
        }
        return null;
    }

    /// <summary>
    /// ГДЕ ПОКАЗАТЬ НАСТРОЙКУ И КАКОЙ ПО СЧЁТУ. Решают, в таком порядке:
    ///
    /// 1. МЕТКА РЯДОМ С НЕЙ (<see cref="KnobPlaceAttribute"/>) — место сказала
    ///    сама настройка, и спорить не с чем.
    /// 2. СПИСОК <c>ГлавныеНастройки</c> роли — роль назвала, что важнее.
    ///    Раньше из этого списка брался только сам факт «главная», а ПОРЯДОК
    ///    выбрасывался: человек называл склад первым, а видел его четвёртым,
    ///    после трёх случайно покрученных ручек. Теперь номер в списке и есть
    ///    порядок показа.
    /// 3. ДОГАДКА ПО СЛОВАМ (<see cref="SectionOf"/>) — последняя мера. Такие
    ///    ручки идут ПОСЛЕ названных, в порядке объявления в роли, и панель
    ///    честно говорит, что раздел выбран догадкой.
    ///
    /// «Уже покрученное» поднимается наверх при любом раскладе: человек эту
    /// ручку искал руками, и прятать её под «Показать всё» — значит заставить
    /// искать второй раз.
    /// </summary>
    /// <param name="roleType">Тип роли — у него спрашиваем метку.</param>
    /// <param name="knob">Сама ручка (нужен её вид: точки на карте всегда наверх).</param>
    /// <param name="about">Описание из док-строки — по нему идёт догадка.</param>
    /// <param name="declared">Список <c>ГлавныеНастройки</c> роли (null — роль его не завела).</param>
    /// <param name="declaredAt">Номер ручки в порядке объявления — им равные держат строй.</param>
    /// <param name="changed">Отличается ли от заводского.</param>
    public static KnobPlace PlaceOf(Type? roleType, RoleKnob knob, string? about,
        IReadOnlyList<string>? declared, int declaredAt, bool changed)
    {
        var mark = MarkOf(roleType, knob.Name);

        int названа = -1;
        if (declared != null)
            for (int i = 0; i < declared.Count; i++)
                if (string.Equals(declared[i], knob.Name, StringComparison.OrdinalIgnoreCase))
                {
                    названа = i;
                    break;
                }

        string раздел = mark != null ? mark.Section.Trim() : SectionOf(knob.Name, about);

        // Порядок: названный меткой → номер в «ГлавныеНастройки» → место
        // объявления в роли, отодвинутое за названные
        int порядок = mark is { Order: > 0 }
            ? mark.Order
            : названа >= 0 ? названа + 1 : 1000 + declaredAt;

        // Правило «что показывать сразу» живёт в одном месте — Main; здесь
        // к нему добавляется только слово самой настройки
        bool главная = mark?.Main == true || Main(knob, changed, declared);

        string кто = mark != null ? "настройка" : названа >= 0 ? "роль" : "догадка";
        // ВКЛАДКУ ТОЖЕ РЕШАЕТ МЕСТО, А НЕ ОТДЕЛЬНЫЙ СПИСОК. Без этой строки
        // «Дом» и «Склад» не попадали на вкладку «Настройка роли» ни у одной
        // роли: они общие, а вкладка делилась только признаком «своё у роли»
        return new KnobPlace(раздел, порядок, главная, кто, mark?.RoleTab == true);
    }

    /// <summary>
    /// ДВЕ РУЧКИ НА ОДНОМ МЕСТЕ В ОКНЕ — СПИСКОМ И ПОИМЁННО. Пусто — у роли
    /// каждое место занято не больше чем одной ручкой.
    ///
    /// НА ЧТО ЭТО ЖАЛУЕТСЯ. Ровно на ту беду, которую назвала док-строка
    /// <c>LivingRole.ДонестиОбщее</c>: «у семи настроек боя номера мест в окне
    /// разошлись, и человек искал парную ручку в другом ящике». Место в окне —
    /// это пара «раздел + порядок», и порядок при равных номерах панель
    /// раскладывает КАК ПРИДЁТСЯ: сортировка не обещает держать строй, а
    /// человек, выучивший «безопасность, третья сверху», после любой правки
    /// найдёт там соседку. Жалоба в проекте была, а сторожа не было вовсе —
    /// столкновения жили молча, десятками.
    ///
    /// СЧИТАЕТСЯ ТЕМ ЖЕ ПУТЁМ, КАКИМ ОКНО СОБИРАЕТ РАСКЛАДКУ
    /// (<see cref="PlaceOf"/> на каждую ручку <see cref="RoleKnobs.Of"/>), а не
    /// своим: спроси сторож метки напрямую — он не увидел бы столкновения между
    /// ручкой С меткой и ручкой ИЗ СПИСКА <c>ГлавныеНастройки</c>, а место в
    /// окне у них одно и то же.
    ///
    /// ПОЧЕМУ НОЛЬ В МЕТКЕ СТОЛКНОВЕНИЕМ НЕ БЫВАЕТ, и особого случая здесь нет.
    /// <see cref="KnobPlaceAttribute.Order"/> = 0 значит «порядок не назван», и
    /// до раскладки этот ноль НЕ ДОХОДИТ: <see cref="PlaceOf"/> заменяет его
    /// либо номером в списке роли (от 1), либо местом объявления, отодвинутым
    /// за названные (от 1000). Оба числа у двух разных ручек разные, поэтому
    /// «два нуля» столкнуться не могут в принципе — а не потому, что их здесь
    /// нарочно не считают.
    /// </summary>
    /// <param name="role">Роль. null — считать нечего.</param>
    /// <param name="explanations">
    /// Читать ли док-строки — РОВНО ТО ЖЕ, что <c>ControlPanel.Explanations</c>.
    /// Раскладок у окна две: с подписями раздел ручки БЕЗ метки угадывается по
    /// имени и описанию, без подписей — по одному имени, и разойтись они могут.
    /// Сторожу надо уметь спросить обе, иначе половина окна остаётся без
    /// присмотра.
    /// </param>
    public static IReadOnlyList<KnobClash> Clashes(BotRole? role, bool explanations = true)
    {
        if (role == null)
            return [];

        var главные = DeclaredMain(role);
        var ручки = RoleKnobs.Of(role);
        var места = new List<(string Имя, KnobPlace Место)>(ручки.Count);
        for (int i = 0; i < ручки.Count; i++)
        {
            string текст = explanations
                ? Clean(XmlDocs.SummaryOf(role.GetType(), ручки[i].Name))
                : "";
            // «Уже покрученное» (changed) двигает только признак «показывать
            // сразу», а места не касается — см. PlaceOf. Спрашивать ради него
            // заводские значения роли значило бы платить за то, чего не спросили
            места.Add((ручки[i].Name,
                PlaceOf(role.GetType(), ручки[i], текст, главные, i, changed: false)));
        }

        return места
            .GroupBy(м => (м.Место.Section, м.Место.Order))
            .Where(g => g.Count() > 1)
            .OrderBy(g => g.Key.Section, StringComparer.Ordinal)
            .ThenBy(g => g.Key.Order)
            .Select(g => new KnobClash(g.Key.Section, g.Key.Order,
                g.Select(м => м.Имя).ToList()))
            .ToList();
    }

    /// <summary>
    /// Разделы ДЛЯ ЭТОЙ РОЛИ: общие плюс те, что роль завела себе сама метками.
    ///
    /// Иначе вышло бы вот что: роль пишет <c>[KnobPlace("торговля")]</c>, панель
    /// такого раздела не знает — и ручка пропадает из окна вовсе. Молча
    /// потерянная настройка хуже настройки в неудобном месте.
    /// Свой раздел встаёт перед «Прочим»: «Прочее» обязано остаться последним.
    /// </summary>
    public static IReadOnlyList<KnobSection> SectionsFor(BotRole? role)
    {
        var список = Sections.ToList();
        if (role == null)
            return список;

        var известные = список.Select(р => р.Id).ToHashSet(StringComparer.OrdinalIgnoreCase);
        foreach (var k in RoleKnobs.Of(role))
        {
            if (MarkOf(role.GetType(), k.Name) is not { } mark)
                continue;
            string id = mark.Section.Trim();
            if (id.Length == 0 || !известные.Add(id))
                continue;
            // Название не назвали — показываем внутреннее имя: врать про
            // раздел нечем, а прятать ручку нельзя
            список.Insert(список.Count - 1,
                new KnobSection(id, mark.Title is { Length: > 0 } t ? t : id, mark.About));
        }
        return список;
    }

    /// <summary>
    /// Слова про КРАЙ значения, сказанные самой ролью: «Ноль — не требовать
    /// вовсе», «Не задан — бот поищет сундук рядом», «0 — трус, 1 — обычный,
    /// 2 — смелый».
    ///
    /// ЖИВОЙ СЛУЧАЙ. Заказчик поставил «ДержатьФакелов = 0», ожидая «держать
    /// ноль факелов, то есть требовать их всё-таки», а ноль означает «не
    /// требовать вовсе» — и это НАПИСАНО во второй фразе описания, которую окно
    /// прятало под «подробнее». Край значения человек читает ровно тогда, когда
    /// стоит над полем и не решается его тронуть, — значит эта фраза обязана
    /// быть рядом с полем, а не за кнопкой.
    ///
    /// НИЧЕГО НЕ ПРИДУМЫВАЕТСЯ: берутся ЕЁ ЖЕ фразы, в которых край назван
    /// прямо («0 —», «ноль —», «пусто —», «не задан —», «−1 —»). Нет такой
    /// фразы — возвращается пусто, и панель молчит.
    /// </summary>
    public static string EdgeOf(string? about)
    {
        // ТОЛЬКО ПЕРВЫЙ АБЗАЦ. Дальше в док-строках идут живые случаи, и в них
        // те же слова встречаются рассказом: у «Склада» ниже пересказана
        // жалоба «...получил в ответ „склад не задан — некуда нести“». Это не
        // край значения, а история, и в строку под полем ей нельзя
        string текст = (about ?? "").Replace("\r\n", "\n").Split('\n')[0].Trim();
        if (текст.Length == 0)
            return "";

        var края = new List<string>();
        foreach (string фраза in Фразы(текст))
        {
            string ровно = Ровно(фраза);
            foreach (string край in Края)
            {
                // Край назван либо в начале фразы («Ноль — не требовать»),
                // либо внутри перечисления («0 — трус, 1 — обычный»)
                int где = ровно.IndexOf(край, StringComparison.Ordinal);
                if (где < 0)
                    continue;
                // «...в 0 — » внутри слова краем не считаем: перед меткой
                // должно быть начало фразы или пробел
                if (где > 0 && ровно[где - 1] is not (' ' or '(' or '«' or ',' or ':'))
                    continue;
                края.Add(фраза);
                break;
            }
            // Двух фраз про край хватает: третья — это уже вся док-строка,
            // а она и так открывается кнопкой «подробнее»
            if (края.Count == 2)
                break;
        }
        return string.Join(" ", края);
    }

    /// <summary>
    /// Край, который стоит показать ОТДЕЛЬНОЙ строкой. Пусто — не стоит.
    ///
    /// У коротких настроек первая же фраза и есть край: «Осторожность в пути:
    /// 0 — трус, 1 — обычный, 2 — смелый». Показать её дважды — под полем и
    /// строкой «на краю» — значит выставить окно сломанным: человек читает
    /// повтор как ошибку, а не как заботу.
    /// </summary>
    public static string EdgeBesides(string? shortText, string? edge)
    {
        string край = (edge ?? "").Trim();
        if (край.Length == 0)
            return "";
        string коротко = (shortText ?? "").Trim();
        return коротко.Contains(край, StringComparison.Ordinal) ? "" : край;
    }

    /// <summary>
    /// Метки края значения. Знак «—» и знак «-» тут разные символы, и в
    /// описаниях встречаются оба; «=» пишут в «пусто = умолчания».
    /// </summary>
    private static readonly string[] Края =
    [
        "0 —", "0 -", "0 –", "0 =", "0:", "ноль —", "ноль -", "ноль =",
        "нуль —", "пусто —", "пусто -", "пусто =", "пустая строка —",
        "пустое —", "не задан —", "не задана —", "не задано —", "не заданы —",
        "-1 —", "−1 —"
    ];

    /// <summary>
    /// Описание фразами: точка с пробелом кончает фразу, «0.5» — нет, «(см. …»
    /// — тоже нет.
    ///
    /// Сокращения перечислены поимённо и коротким списком: правило «точка после
    /// двух букв не считается» отрезало бы «...кирки. Ноль — ...». Живой случай:
    /// без этого под полем «ПолублокДороги» стояло «Пусто — искать в сумках по
    /// форме, а нет — сделать по рецепту (см.» — обрубок, который человек
    /// читает как поломку окна.
    /// </summary>
    private static readonly string[] Сокращения = ["см", "т", "е", "др", "напр", "рис", "стр"];

    private static IEnumerable<string> Фразы(string текст)
    {
        int начало = 0;
        for (int i = 0; i < текст.Length; i++)
        {
            bool конец = текст[i] is '.' or '!' or '?' or '\n';
            if (!конец)
                continue;
            if (текст[i] != '\n' && i + 1 < текст.Length && текст[i + 1] is not (' ' or '\n'))
                continue;
            if (текст[i] == '.' && Сокращение(текст, i))
                continue;
            string кусок = текст[начало..(i + 1)].Trim();
            if (кусок.Length > 0)
                yield return кусок;
            начало = i + 1;
        }
        string хвост = текст[начало..].Trim();
        if (хвост.Length > 0)
            yield return хвост;
    }

    /// <summary>Стоит ли перед точкой сокращение, а не конец фразы.</summary>
    private static bool Сокращение(string текст, int точка)
    {
        int начало = точка;
        while (начало > 0 && char.IsLetter(текст[начало - 1]))
            начало--;
        string слово = Ровно(текст[начало..точка]);
        return слово.Length > 0 && Array.IndexOf(Сокращения, слово) >= 0;
    }

    /// <summary>
    /// Меры по порядку проверки. «часов» стоит раньше «час», иначе более
    /// короткое правило перехватило бы имя «ПомнитьЧасов».
    /// </summary>
    private static readonly (string Корень, string Слово)[] Меры =
    [
        ("секунд", "секунды"), ("минут", "минуты"), ("часов", "часы"), ("час", "часы"),
        ("суток", "сутки"), ("дней", "дни"), ("блок", "блоки"), ("слоя", "слои"),
        ("слоях", "слои"), ("слоев", "слои"), ("штук", "штуки"), ("процент", "проценты"),
        ("токен", "токены"), ("метр", "метры")
    ];

    /// <summary>
    /// ЕДИНИЦА, НАЗВАННАЯ САМОЙ РОЛЬЮ. Пусто — роль её не назвала, и додумывать
    /// нельзя: «РадиусСбораЕды = 32» это блоки, а «ПомнитьЧасов = 72» — часы, и
    /// перепутать их значит подписать поле ложью.
    ///
    /// Из описания единица берётся только там, где она стоит МЕРОЙ: «в блоках»,
    /// «, минут», «(секунд)». Просто встреченное в рассказе слово «минуты»
    /// мерой не считается.
    ///
    /// ВИД РУЧКИ СПРАШИВАЕТСЯ ПЕРВЫМ И БЕЗ ЗАВОДСКОГО ЗНАЧЕНИЯ — то есть
    /// назвать его обязан КАЖДЫЙ, кто спрашивает про меру. «Какая тут единица»
    /// — вопрос О ЧИСЛЕ, и заданный без вида он неполон: у клетки, галочки,
    /// строки и выбора меры не бывает вовсе (<see cref="RoleKnobs.Меряется"/>).
    /// Живьём необязательность этого довода стоила подписи «секунды» под
    /// тремя координатами склада и ещё пяти таких же подписей — «минуты» и
    /// «блоки» под галочками.
    /// </summary>
    /// <param name="kind">вид ручки словами <see cref="RoleKnobs.KindOf"/></param>
    public static string UnitOf(string? name, string? about, string? kind)
    {
        if (!RoleKnobs.Меряется(kind))
            return "";

        string имя = Ровно(name ?? "");
        foreach (var (корень, слово) in Меры)
            if (имя.Contains(корень, StringComparison.Ordinal))
                return слово;

        string текст = Ровно(about ?? "");
        foreach (var (корень, слово) in Меры)
            foreach (string перед in (string[])["в ", ", ", "("])
                if (текст.Contains(перед + корень, StringComparison.Ordinal))
                    return слово;
        return "";
    }

    /// <summary>
    /// Имя настройки словами: «ОбходитьПередКопанием» → «Обходить перед
    /// копанием». Это НЕ перевод и не пересказ — те же слова, только с
    /// пробелами: панель вправе расставить пробелы, но не подбирать слова.
    ///
    /// Настоящее имя рядом всё равно показывается: им настройка зовётся в
    /// пресете, в файле и в чате, и потерять его нельзя.
    /// </summary>
    public static string Words(string? name)
    {
        string имя = name ?? "";
        if (имя.Length == 0)
            return "";
        var текст = new System.Text.StringBuilder();
        текст.Append(имя[0]);
        for (int i = 1; i < имя.Length; i++)
        {
            char c = имя[i];
            if (char.IsUpper(c) && char.IsLetter(имя[i - 1]))
            {
                текст.Append(' ').Append(char.ToLowerInvariant(c));
                continue;
            }
            текст.Append(c);
        }
        return текст.ToString();
    }

    /// <summary>
    /// Описание в человеческий вид: отступы компилятора убрать, абзацы
    /// сохранить. Пустое остаётся пустым — придумывать нечего.
    /// </summary>
    public static string Clean(string? xmlText)
    {
        if (string.IsNullOrWhiteSpace(xmlText))
            return "";
        var абзацы = new List<string>();
        var текущий = new List<string>();
        foreach (string строка in xmlText.Replace("\r\n", "\n").Split('\n'))
        {
            string s = строка.Trim();
            if (s.Length == 0)
            {
                if (текущий.Count > 0) { абзацы.Add(string.Join(' ', текущий)); текущий.Clear(); }
                continue;
            }
            текущий.Add(s);
        }
        if (текущий.Count > 0)
            абзацы.Add(string.Join(' ', текущий));
        return string.Join('\n', абзацы).Trim();
    }

    /// <summary>
    /// Первая фраза описания — та, что помещается в строку под полем. Остальное
    /// окно раскрывает по нажатию: длинные объяснения с живыми случаями нужны,
    /// но не все тридцать сразу.
    /// </summary>
    public static string Short(string? text)
    {
        string t = (text ?? "").Trim();
        if (t.Length == 0)
            return "";
        int абзац = t.IndexOf('\n');
        if (абзац > 0)
            t = t[..абзац].Trim();
        // Фразу режем тем же правилом, что и края значений: точка внутри «0.5»
        // и точка в «(см. рецепт)» фразу не кончают
        return Фразы(t).FirstOrDefault() ?? t;
    }

    /// <summary>
    /// Показывать настройку сразу или спрятать под «показать все».
    ///
    /// Что именно «самое нужное», знает роль, а не панель. Поэтому наверх идут:
    /// названные самой ролью (свойство <c>ГлавныеНастройки</c>, если она его
    /// завела), точки на карте (склад и дом ищут первым делом) и всё, что
    /// человек УЖЕ крутил, — то есть отличающееся от заводского.
    /// </summary>
    public static bool Main(RoleKnob knob, bool changed, IReadOnlyCollection<string>? declared)
    {
        if (declared != null && declared.Contains(knob.Name, StringComparer.OrdinalIgnoreCase))
            return true;
        return changed || knob.Kind == WorkFieldKinds.Cell;
    }

    /// <summary>
    /// Главные настройки, названные самой ролью. null — роль их не называла, и
    /// гадать за неё панель не станет.
    ///
    /// ПОРЯДОК В СПИСКЕ — ЭТО ПОРЯДОК ПОКАЗА, и он тоже слово роли: тот, кто
    /// написал «сперва склад, потом дом, потом смелость», сказал этим, что
    /// важнее. Раньше список превращался в множество и порядок терялся —
    /// человек называл склад первым, а видел его посреди списка.
    /// </summary>
    public static IReadOnlyList<string>? DeclaredMain(BotRole? role)
    {
        if (role == null)
            return null;
        try
        {
            var p = role.GetType().GetProperty("ГлавныеНастройки",
                BindingFlags.Public | BindingFlags.Instance);
            if (p?.GetValue(role) is IEnumerable<string> имена)
                return имена.ToList();
        }
        catch
        {
            // Роль вправе не иметь такого свойства — это не беда
        }
        return null;
    }

    /// <summary>
    /// Настройки нейросети роли, если они у неё есть.
    ///
    /// Ищем по ТИПУ, а не по имени свойства: имя роль вправе выбрать любое, а
    /// тип <see cref="AiSettings"/> в проекте один — он и есть то самое «одно
    /// место настроек ИИ».
    /// </summary>
    public static AiSettings? AiOf(BotRole? role)
    {
        if (role == null)
            return null;
        try
        {
            foreach (var p in role.GetType()
                         .GetProperties(BindingFlags.Public | BindingFlags.Instance))
                if (p.CanRead && p.PropertyType == typeof(AiSettings) &&
                    p.GetIndexParameters().Length == 0)
                    return p.GetValue(role) as AiSettings;
        }
        catch
        {
            // Роль могла бросить из своего свойства — окно из-за этого падать
            // не должно, а «нейросети у роли нет» здесь честный ответ
        }
        return null;
    }
}

/// <summary>
/// Строка таблицы весов для окна: способность, её вес, пол и заводское
/// значение. Ни бота, ни мира здесь нет нарочно — двигать способности по
/// списку это чистое правило, и проверяется оно стендом.
/// </summary>
/// <param name="Name">Как способность зовут человеку («еда», «бой»).</param>
/// <param name="Weight">Вес сейчас.</param>
/// <param name="Floor">Ниже этого не опускается (0 — можно до нуля).</param>
/// <param name="Default">Заводской вес этой способности.</param>
/// <param name="Code">Имя типа — им называют способность, если имя со знаком препинания.</param>
/// <param name="Ceiling">Выше этого не поднимается (∞ — предела нет).</param>
public readonly record struct WeightRow(
    string Name, double Weight, double Floor = 0, double Default = 0, string Code = "",
    double Ceiling = double.PositiveInfinity);

/// <summary>
/// КТО КОГО ПЕРЕБИВАЕТ — список по убыванию веса и правило «подвинуть».
///
/// ПРЯМАЯ ПРОСЬБА ЗАКАЗЧИКА: «вес важности, что над чем превалирует, так проще
/// будет настроить бота». Числа у способностей уже есть
/// (<see cref="BehaviorWeights"/>), но человек их не видел вовсе: строка
/// «еда 95; бой 70» заполнялась вслепую, и узнать, кто над кем, можно было
/// только из исходников.
///
/// ПОЧЕМУ ДВИГАТЬ, А НЕ ВПИСЫВАТЬ ЧИСЛО. Человеку нужно «еда важнее карьера»,
/// а не «еда = 62,5». Кнопка «выше» находит ближайшее число, которое ставит
/// способность НАД соседом и никого больше не перепрыгивает, — считает его
/// правило здесь, а не браузер: цена ошибки — бот, который бросил спасаться и
/// пошёл копать.
///
/// ПОЛ И ПОТОЛОК НЕ ОБХОДЯТСЯ И ОТСЮДА. Опустить еду ниже
/// <see cref="BehaviorWeights.LifeFloor"/> кнопкой нельзя ровно так же, как
/// строкой; поднять безделье выше того же числа — тоже. Правило отказывает и
/// НАЗЫВАЕТ причину: молчаливое «кнопка не нажалась» здесь было бы худшим из
/// ответов.
/// </summary>
public static class WeightOrder
{
    /// <summary>
    /// Способности в том порядке, в каком их обходит бот: по весу вниз, равные
    /// — жизненные вперёд, дальше в порядке подключения (порядок устойчив и
    /// разбирает ничью так же, как <see cref="BehaviorRunner.Ordered"/>).
    /// </summary>
    public static IReadOnlyList<WeightRow> Ordered(IEnumerable<WeightRow> rows) =>
        rows.OrderByDescending(r => r.Weight).ThenByDescending(r => r.Floor).ToList();

    /// <summary>
    /// Какой вес поставить, чтобы способность встала на строчку выше (или
    /// ниже). null — двигать нельзя, и <paramref name="why"/> говорит почему.
    ///
    /// Правило выбора числа: встать между соседом и тем, кто над ним. Если
    /// между ними меньше единицы — ровно посередине, иначе на единицу выше
    /// соседа: круглые числа человек читает, а «61,999» — нет. Соседи с
    /// РАВНЫМ весом (а таких много: вся работа стоит на 50) перепрыгиваются
    /// группой — иначе кнопка не делала бы ничего, и это выглядело бы поломкой.
    /// </summary>
    public static double? Moved(IReadOnlyList<WeightRow> ordered, string? name, bool up,
        out string why)
    {
        why = "";
        var список = Ordered(ordered);
        int i = -1;
        for (int n = 0; n < список.Count; n++)
            if (string.Equals(список[n].Name, name, StringComparison.OrdinalIgnoreCase) ||
                (список[n].Code.Length > 0 &&
                 string.Equals(список[n].Code, name, StringComparison.OrdinalIgnoreCase)))
            {
                i = n;
                break;
            }
        if (i < 0)
        {
            why = $"«{name}» — такой способности у бота нет";
            return null;
        }

        if (up)
        {
            if (i == 0)
            {
                why = $"«{список[i].Name}» и так первая — выше некуда";
                return null;
            }
            double сосед = список[i - 1].Weight;
            double надНим = i - 1 == 0 ? double.PositiveInfinity : список[i - 2].Weight;
            double вверх = Округлить(Между(сосед, надНим));

            // ПОТОЛОК НАЗЫВАЕТСЯ ВСЛУХ. Кнопка «выше» у безделья доходила до
            // еды и дальше не двигалась молча — со стороны это «кнопка
            // сломалась». Работа не встаёт над жизненными ни строкой, ни
            // кнопкой, и причину человек обязан прочесть
            if (вверх > список[i].Ceiling)
            {
                why = $"«{список[i].Name}» выше {список[i].Ceiling:0.#} не поднимается: " +
                      "возрождение, лечение и еда всегда важнее любой работы — иначе " +
                      "бот умрёт с едой в кармане";
                return null;
            }
            return вверх;
        }

        if (i == список.Count - 1)
        {
            why = $"«{список[i].Name}» и так последняя — ниже некуда";
            return null;
        }
        double под = список[i + 1].Weight;
        double подНим = i + 2 < список.Count ? список[i + 2].Weight : double.NegativeInfinity;
        double вес = Округлить(-Между(-под, -подНим));

        // ПОЛ НАЗЫВАЕТСЯ ВСЛУХ. Живой случай: бот рыл карьер и умирал от голода
        // с хлебом в кармане — после этого у еды, лечения и возрождения
        // появился предел, ниже которого их не опустить ничем
        if (вес < список[i].Floor)
        {
            why = $"«{список[i].Name}» ниже {список[i].Floor:0.#} не опускается: возрождение, " +
                  "лечение и еда всегда важнее любой работы — иначе бот умрёт с едой в кармане";
            return null;
        }
        return вес;
    }

    /// <summary>Число строго между соседом и тем, кто над ним.</summary>
    private static double Между(double сосед, double дальше) =>
        дальше - сосед > 1 ? сосед + 1 : дальше > сосед ? (сосед + дальше) / 2 : сосед + 1;

    private static double Округлить(double вес) => Math.Round(вес, 1);

    /// <summary>
    /// Человеческая строка весов для ручки роли: «еда 95; бой 70».
    ///
    /// НАЗЫВАЮТСЯ ТОЛЬКО ОТЛИЧАЮЩИЕСЯ от заводского. Причина не в краткости:
    /// строка задаёт веса ЦЕЛИКОМ (см. <see cref="BehaviorRunner.ApplyWeights"/>),
    /// и перечислить в ней все двадцать способностей значило бы намертво
    /// прибить к пресету сегодняшнюю таблицу умолчаний — завтрашняя правка
    /// весов в библиотеке до такого бота уже не дошла бы.
    ///
    /// Имя со знаком препинания («,», «;», «=») ломает разбор строки, поэтому
    /// такая способность называется своим типом: это некрасиво, но читается
    /// обратно — а красивое и неработающее хуже.
    /// </summary>
    public static string Line(IEnumerable<WeightRow> rows) =>
        string.Join("; ", rows
            .Where(r => Math.Abs(r.Weight - r.Default) > 1e-9)
            .Select(r => $"{Назвать(r)} " +
                         r.Weight.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture)));

    private static string Назвать(WeightRow r) =>
        r.Name.IndexOfAny([',', ';', '=', '\n']) >= 0 && r.Code.Length > 0 ? r.Code : r.Name;

    // ======================================================================
    //  ОТБОР СТРОК: «покажи только то, что важнее еды»
    // ======================================================================

    /// <summary>
    /// ПОДХОДИТ ЛИ СПОСОБНОСТЬ ОТБОРУ. Заказчик 16.08 дословно: «неудобно
    /// выставлять приоритет веса и НЕТ ТАМ ФИЛЬТРАЦИИ ПО ЗНАЧЕНИЯМ».
    ///
    /// Строк в списке два с лишним десятка («возрождение 100 (пол 60); не висеть
    /// в воздухе 95; сон 90; … без дела 0 (потолок 60)»), и человек ищет в них
    /// не «строку номер семь», а ПОЛОСУ ЧИСЕЛ: что у меня стоит выше еды, что
    /// провалилось под работу, что я вообще трогал. Глазами по двадцати трём
    /// строкам это делается один раз, а потом бросается.
    ///
    /// ПОЧЕМУ ЭТО ПРАВИЛО, А НЕ ФОРМУЛА В РАЗМЕТКЕ. Ошибка отбора не рушит
    /// ничего громко — она ПРЯЧЕТ строку, и человек уходит уверенный, что такой
    /// способности у бота нет (ровно так в живом прогоне 15.08 пропала штольня,
    /// см. <see cref="PanelWorkFind"/>). Такое ловится только стендом.
    ///
    /// Границы ВКЛЮЧАЮЩИЕ с обеих сторон: человек, набравший «от 60», ждёт, что
    /// увидит и саму шестидесятку — это же пол жизненных, ради которого он
    /// границу и ставил.
    /// </summary>
    /// <param name="row">строка списка весов</param>
    /// <param name="from">нижняя граница веса (null — не задана)</param>
    /// <param name="to">верхняя граница веса (null — не задана)</param>
    /// <param name="word">слово в названии или в имени типа (пусто — любое)</param>
    /// <param name="onlyChanged">только отличающиеся от заводского</param>
    public static bool Fits(WeightRow row, double? from, double? to, string? word,
        bool onlyChanged = false)
    {
        if (from is { } низ && row.Weight < низ)
            return false;
        if (to is { } верх && row.Weight > верх)
            return false;
        if (onlyChanged && Math.Abs(row.Weight - row.Default) <= 1e-9)
            return false;

        // Слово приводим к сравнимому виду ТЕМ ЖЕ способом, каким бот сравнивает
        // человеческие имена вещей (<see cref="GameLang.Tidy"/>): строчные буквы
        // и «ё» как «е». Своей второй мерки здесь не заводится — «фонарь в руке»
        // человек набирает и с «ё», и без неё, и промолчать в ответ нельзя
        string искомое = GameLang.Tidy(word ?? "");
        if (искомое.Length == 0)
            return true;
        return GameLang.Tidy(row.Name).Contains(искомое, StringComparison.Ordinal) ||
               GameLang.Tidy(row.Code).Contains(искомое, StringComparison.Ordinal);
    }

    /// <summary>
    /// ЧТО СКАЗАТЬ, КОГДА ОТБОР НЕ ОСТАВИЛ НИЧЕГО. Пустое место человек читает
    /// как «способностей у бота нет» — это и была беда прошлого окна. Пусто в
    /// ответе значит «показывать нечего не надо, всё в порядке».
    /// </summary>
    public static string SayEmpty(int shown, int total, double? from, double? to,
        string? word, bool onlyChanged)
    {
        if (shown > 0 || total == 0)
            return "";
        var чем = new List<string>();
        if (from != null || to != null)
            чем.Add(from != null && to != null ? $"вес от {from:0.#} до {to:0.#}"
                : from != null ? $"вес от {from:0.#}"
                : $"вес до {to:0.#}");
        if (!string.IsNullOrWhiteSpace(word))
            чем.Add($"слово «{word!.Trim()}»");
        if (onlyChanged)
            чем.Add("только изменённые");
        return чем.Count == 0
            ? ""
            : $"под отбор ({string.Join(", ", чем)}) не подошла ни одна из {total} " +
              "способностей — сам список никуда не делся, снимите отбор";
    }
}

/// <summary>
/// СЕКРЕТЫ БОТА НА ДИСКЕ: ключ нейросети, заданный из окна управления.
///
/// ЖИВАЯ ПРОСЬБА ЗАКАЗЧИКА, ради которой это заведено: «по поводу ролей — в
/// вебформе и нужно задавать ключ». До этого ключ клали ТОЛЬКО в переменную
/// окружения, и на своей машине это лишний поход в системные настройки с
/// перезапуском всего.
///
/// ПЕРЕМЕННАЯ ОКРУЖЕНИЯ ОСТАЁТСЯ И ОНА СТАРШЕ. Тем, у кого ключ уже лежит в
/// окружении (сервер, контейнер, чужая сборка), не должно сломаться ничего:
/// сохранённое здесь кладётся в окружение процесса ТОЛЬКО когда переменная
/// пуста (<see cref="ПоложитьВОкружение"/>). Иначе файл, забытый в папке
/// состояния полгода назад, молча перебивал бы ключ, заданный при запуске, — и
/// человек платил бы чужим ключом, не зная об этом.
///
/// НАРУЖУ ЗНАЧЕНИЕ НЕ ВЫХОДИТ НИКОГДА. Ни в ответ окну (окно спрашивает и
/// показывает только «задан / не задан»), ни в журнал, ни в чат, ни в файл
/// готового бота. Отсюда его читает ровно один вызывающий — тот, кто создаёт
/// клиента нейросети, и читает он его В ОКРУЖЕНИЕ ПРОЦЕССА, а не в строку,
/// которую можно случайно напечатать.
///
/// ЧЕСТНО О ТОМ, ЧЕГО ЭТОТ ФАЙЛ НЕ ДЕЛАЕТ. Он НЕ ШИФРУЕТ. Ключ лежит на диске
/// открытым текстом — ровно так же, как токен сессии игры рядом
/// (<see cref="SessionStore"/>), и по той же причине: шифровать надо ключом, а
/// его пришлось бы положить рядом же. На POSIX файлу ставится 0600 (читает
/// только хозяин); на Windows прав файлу не меняем — там их наследует папка
/// профиля, и притворяться, что мы что-то защитили, нельзя. Кто имеет доступ к
/// папке состояния бота — имеет доступ и к ключу; это надо знать, а не прятать.
/// </summary>
public sealed class BotSecrets
{
    /// <summary>Как зовётся файл. Рядом с botsession.json и по той же причине.</summary>
    public const string DefaultFileName = "botsecrets.json";

    /// <summary>Полный путь к файлу — его показывают человеку в окне.</summary>
    public string Path { get; }

    /// <param name="path">
    /// Свой путь (нужен стендам). Пусто — файл в папке состояния бота, там же,
    /// где bot.json и токен сессии.
    /// </param>
    public BotSecrets(string? path = null)
    {
        Path = string.IsNullOrWhiteSpace(path)
            ? System.IO.Path.Combine(BotFolders.State(), DefaultFileName)
            : System.IO.Path.GetFullPath(path);
    }

    /// <summary>Что случилось с файлом — в журнал. ЗНАЧЕНИЙ здесь не бывает.</summary>
    public event Action<string>? OnLog;

    private static readonly JsonSerializerOptions КакПисать = new()
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    /// <summary>
    /// Прочитать всё, что лежит в файле. Файла нет, он битый или недоступен —
    /// пусто: секрет, который не прочитался, это «ключа нет», а не падение
    /// бота.
    /// </summary>
    public Dictionary<string, string> Все()
    {
        try
        {
            if (!File.Exists(Path))
                return new Dictionary<string, string>(StringComparer.Ordinal);
            return JsonSerializer.Deserialize<Dictionary<string, string>>(File.ReadAllText(Path))
                   ?? new Dictionary<string, string>(StringComparer.Ordinal);
        }
        catch (Exception e)
        {
            OnLog?.Invoke($"файл секретов не прочитался ({Path}): {e.Message}");
            return new Dictionary<string, string>(StringComparer.Ordinal);
        }
    }

    /// <summary>
    /// ЗАДАН ЛИ СЕКРЕТ С ТАКИМ ИМЕНЕМ. Возвращается «да/нет», а не значение, и
    /// это единственный вопрос, на который снаружи вообще отвечают.
    /// </summary>
    public bool Задан(string name) =>
        !string.IsNullOrWhiteSpace(name) &&
        Все().TryGetValue(name, out var з) && !string.IsNullOrWhiteSpace(з);

    /// <summary>
    /// СТОИТ ЛИ В ОКРУЖЕНИИ ЧУЖОЙ КЛЮЧ — то есть НЕ ТОТ, что лежит здесь.
    ///
    /// ЖИВАЯ ПУТАНИЦА, ради которой это заведено, поймана на живом прогоне.
    /// Окно сохраняет ключ, тут же кладёт его в окружение процесса
    /// (<see cref="ПоложитьВОкружение"/>) — и следующий же вопрос «задана ли
    /// переменная окружения» честно отвечает ДА. Человек, у которого никакой
    /// переменной отродясь не было, читал в окне «работает тот ключ, что в
    /// ПЕРЕМЕННОЙ: она старше» и шёл искать её по системным настройкам.
    ///
    /// Различить эти два «да» можно только СЛИЧИВ ЗНАЧЕНИЯ, и сличение живёт
    /// здесь, внутри: наружу уходит один <c>bool</c>, значения не покидают
    /// класс никогда. Совпали — значит переменную поставили мы сами из файла;
    /// разошлись — значит её задал человек до запуска, и она вправду старше.
    ///
    /// Пограничный случай назван вслух: если человек задал В ОКРУЖЕНИИ ТОТ ЖЕ
    /// САМЫЙ ключ, что лежит здесь, ответ будет «свой» — и это безвредно,
    /// потому что работает всё равно один и тот же ключ.
    /// </summary>
    public bool ВОкруженииЧужой(string name)
    {
        string? вОкружении = Environment.GetEnvironmentVariable(name);
        if (string.IsNullOrWhiteSpace(вОкружении))
            return false;
        return !Все().TryGetValue(name, out var своё) ||
               !string.Equals(своё?.Trim(), вОкружении.Trim(), StringComparison.Ordinal);
    }

    /// <summary>
    /// ЗАПОМНИТЬ СЕКРЕТ. Пустое значение — ЗАБЫТЬ его: у «убрать ключ» должно
    /// быть то же поле, что и у «задать», иначе человек стирает поле, видит
    /// «задан» и не понимает, чем бот платит.
    ///
    /// Возвращает строку для человека — БЕЗ значения и без его длины.
    /// </summary>
    public string Запомнить(string name, string? value)
    {
        if (string.IsNullOrWhiteSpace(name))
            return "не сказано, что за секрет сохранять";
        var всё = Все();
        bool забыть = string.IsNullOrWhiteSpace(value);
        if (забыть)
        {
            if (!всё.Remove(name))
                return $"{name}: и так не был задан";
        }
        else
        {
            всё[name] = value!.Trim();
        }

        try
        {
            Directory.CreateDirectory(System.IO.Path.GetDirectoryName(Path)!);
            if (всё.Count == 0)
            {
                if (File.Exists(Path))
                    File.Delete(Path);
            }
            else
            {
                File.WriteAllText(Path, JsonSerializer.Serialize(всё, КакПисать),
                    new System.Text.UTF8Encoding(false));
                ЗакрытьОтЧужих(Path);
            }
        }
        catch (Exception e)
        {
            return $"{name}: сохранить не вышло ({Path}): {e.Message}";
        }

        // В ЖУРНАЛ УХОДИТ ИМЯ ПЕРЕМЕННОЙ, А НЕ КЛЮЧ — и не его длина: длина
        // ключа это тоже сведения о ключе, а журнал заказчик пересылает
        OnLog?.Invoke(забыть
            ? $"секрет {name} забыт ({Path})"
            : $"секрет {name} сохранён ({Path}); наружу он не отдаётся и в журнал не пишется");
        return забыть
            ? $"{name}: забыт. В окружении запущенного процесса он останется до перезапуска"
            : $"{name}: сохранён в {Path}";
    }

    /// <summary>
    /// ПОЛОЖИТЬ СОХРАНЁННОЕ В ОКРУЖЕНИЕ ПРОЦЕССА — не трогая того, что там уже
    /// есть. Возвращает имена переменных, которые вправду поставили.
    ///
    /// ЗАЧЕМ ЧЕРЕЗ ОКРУЖЕНИЕ, А НЕ СТРОКОЙ В КЛИЕНТА. Ключ читает сам SDK
    /// поставщика (<c>AnthropicClient</c> без аргументов), и он же читает его
    /// <see cref="AiProvider.КлючЗадан"/>, когда отвечает окну «ключ есть».
    /// Понеси мы значение строкой через роль и клиента — оно прошло бы через
    /// полдюжины мест, каждое из которых можно случайно напечатать в журнал, и
    /// «задан ли ключ» стало бы иметь ДВА ответа.
    /// </summary>
    public IReadOnlyList<string> ПоложитьВОкружение()
    {
        var поставили = new List<string>();
        foreach (var (имя, значение) in Все())
        {
            if (string.IsNullOrWhiteSpace(имя) || string.IsNullOrWhiteSpace(значение))
                continue;
            // ПЕРЕМЕННАЯ СТАРШЕ ФАЙЛА. Заданное при запуске не перебиваем
            // никогда — иначе забытый файл молча менял бы, чьим ключом платят
            if (!string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(имя)))
                continue;
            Environment.SetEnvironmentVariable(имя, значение);
            поставили.Add(имя);
        }
        return поставили;
    }

    /// <summary>
    /// КТО СТАРШЕ ПРЯМО СЕЙЧАС — словами для окна. Четыре разных случая, и
    /// путать их нельзя: человек, вписавший ключ в окно ПОВЕРХ переменной
    /// окружения, должен узнать, что платят не его ключом.
    ///
    /// Чистое правило: ни файлов, ни окружения — два «да/нет» на входе, потому
    /// и проверяется стендом.
    /// </summary>
    public static string КтоСтарше(bool вОкружении, bool вФайле) =>
        (вОкружении, вФайле) switch
        {
            (true, true) => "ключ есть и в переменной окружения, и здесь. Работает тот, " +
                            "что в ПЕРЕМЕННОЙ: она старше. Сохранённый здесь подхватится, " +
                            "если переменную убрать и перезапустить бота",
            (true, false) => "ключ берётся из переменной окружения — она задана до запуска " +
                             "и старше всего. Задавать его здесь незачем",
            (false, true) => "ключ задан здесь, в окне, и лежит в файле секретов бота",
            (false, false) => "ключа нет нигде: ни в переменной окружения, ни здесь"
        };

    /// <summary>
    /// Закрыть файл от чужих там, где это умеет система. На Windows прав файлу
    /// не меняем НАРОЧНО: там их наследует папка профиля, а притворная
    /// «защита» хуже честного «не защищено».
    /// </summary>
    private static void ЗакрытьОтЧужих(string path)
    {
        if (OperatingSystem.IsWindows())
            return;
        try
        {
            File.SetUnixFileMode(path, UnixFileMode.UserRead | UnixFileMode.UserWrite);
        }
        catch
        {
            // Права не поставились (чужая файловая система, контейнер) — файл
            // всё равно записан. Молча: это не отказ в работе, а сказать про
            // него было бы нечего сверх того, что уже написано в док-строке
        }
    }
}
